def _build_wp_ssl_context() -> ssl.SSLContext:
    ca_bundle = os.getenv("SEO_WP_SYNC_CA_BUNDLE", "").strip()
    if not ca_bundle:
        return ssl.create_default_context()
    ca_path = Path(ca_bundle).expanduser().resolve()
    if not ca_path.is_file():
        raise RuntimeError(f"SEO_WP_SYNC_CA_BUNDLE does not exist: {ca_path}")
    return ssl.create_default_context(cafile=str(ca_path))


# WordPress HTTPS always verifies the server identity. Enterprise deployments
# can add their private CA through SEO_WP_SYNC_CA_BUNDLE without weakening TLS
# for every site and request in the process.
_WP_SSL_CTX = _build_wp_ssl_context()

