def _truthy(value: str) -> bool:
    return str(value or "").strip().lower() in {"1", "true", "yes", "on"}


def _is_windows_platform() -> bool:
    return os.name == "nt"


def _default_user_data_dir() -> Path:
    override = (
        os.getenv("SEO_WP_SYNC_DATA_DIR", "").strip()
        or os.getenv("SEOWPSYNC_DATA_DIR", "").strip()
    )
    if override:
        return Path(override).expanduser()
    if _is_windows_platform():
        base = os.getenv("APPDATA", "").strip()
        return (Path(base).expanduser() if base else Path.home() / "AppData" / "Roaming") / APP_STORAGE_NAME
    if sys.platform == "darwin":
        return Path.home() / "Library" / "Application Support" / APP_STORAGE_NAME
    base = os.getenv("XDG_DATA_HOME", "").strip()
    return (Path(base).expanduser() if base else Path.home() / ".local" / "share") / APP_STORAGE_NAME


def _default_user_log_dir() -> Path:
    override = (
        os.getenv("SEO_WP_SYNC_LOG_DIR", "").strip()
        or os.getenv("SEOWPSYNC_LOG_DIR", "").strip()
    )
    if override:
        return Path(override).expanduser()
    if _is_windows_platform():
        return _default_user_data_dir() / "logs"
    if sys.platform == "darwin":
        return Path.home() / "Library" / "Logs" / APP_STORAGE_NAME
    base = os.getenv("XDG_STATE_HOME", "").strip()
    return (Path(base).expanduser() if base else Path.home() / ".local" / "state") / APP_STORAGE_NAME / "logs"


def _default_user_cache_dir() -> Path:
    override = (
        os.getenv("SEO_WP_SYNC_CACHE_DIR", "").strip()
        or os.getenv("SEOWPSYNC_CACHE_DIR", "").strip()
    )
    if override:
        return Path(override).expanduser()
    if _is_windows_platform():
        return _default_user_data_dir() / "cache"
    if sys.platform == "darwin":
        return Path.home() / "Library" / "Caches" / APP_STORAGE_NAME
    base = os.getenv("XDG_CACHE_HOME", "").strip()
    return (Path(base).expanduser() if base else Path.home() / ".cache") / APP_STORAGE_NAME


