@asynccontextmanager
async def _app_lifespan(_app: FastAPI):
    background_task_manager.restart_runtime()
    _start_daily_seo_scheduler()
    _start_product_auto_scan_scheduler()
    _start_seo_health_auto_scan_scheduler()
    _start_link_index_auto_scan_scheduler()
    try:
        yield
    finally:
        _stop_link_index_auto_scan_scheduler()
        _stop_seo_health_auto_scan_scheduler()
        _stop_product_auto_scan_scheduler()
        _stop_daily_seo_scheduler()
        background_task_manager.shutdown()


