def _configure_backend_logging() -> None:
    """Keep normal polling quiet; reserve terminal noise for actionable failures."""
    logging.getLogger("uvicorn.access").setLevel(logging.WARNING)
    api_logger.setLevel(logging.INFO)


def _request_label(request: Request) -> str:
    query = request.url.query
    suffix = f"?{query}" if query else ""
    return f"{request.method} {request.url.path}{suffix}"


def _format_log_detail(detail: Any, max_chars: int = 3000) -> str:
    try:
        text = json.dumps(detail, ensure_ascii=False, default=str)
    except Exception:
        text = str(detail)
    text = re.sub(r"\s+", " ", text).strip()
    if len(text) > max_chars:
        return f"{text[:max_chars]}... [truncated]"
    return text


def _exception_location(exc: Exception) -> str:
    frames = traceback.extract_tb(exc.__traceback__)
    if not frames:
        return "unknown location"
    frame = frames[-1]
    return f"{frame.filename}:{frame.lineno} in {frame.name}"


def _log_http_exception(request: Request, exc: HTTPException) -> None:
    api_logger.error(
        "[api-error] %s -> HTTP %s detail=%s",
        _request_label(request),
        exc.status_code,
        _format_log_detail(exc.detail),
    )


@app.exception_handler(HTTPException)
async def _http_exception_logger(request: Request, exc: HTTPException):
    _log_http_exception(request, exc)
    return JSONResponse(
        status_code=exc.status_code,
        content=jsonable_encoder({"detail": exc.detail}),
        headers=exc.headers,
    )


@app.exception_handler(RequestValidationError)
async def _validation_exception_logger(request: Request, exc: RequestValidationError):
    detail = exc.errors()
    api_logger.error(
        "[api-error] %s -> HTTP 422 detail=%s",
        _request_label(request),
        _format_log_detail(detail),
    )
    return JSONResponse(status_code=422, content=jsonable_encoder({"detail": detail}))


@app.exception_handler(Exception)
async def _unhandled_exception_logger(request: Request, exc: Exception):
    api_logger.exception(
        "[api-exception] %s -> %s: %s at %s",
        _request_label(request),
        exc.__class__.__name__,
        exc,
        _exception_location(exc),
    )
    return JSONResponse(status_code=500, content={"detail": "Internal server error"})


_configure_backend_logging()

def _resolve_runtime_path(env_key: str, default_relative_path: str, base_dir: Path) -> Path:
    raw = os.getenv(env_key, "").strip()
    if not raw:
        if not default_relative_path:
            return base_dir
        return base_dir / default_relative_path
    path = Path(raw)
    return path if path.is_absolute() else PROJECT_ROOT / path


