def _get_ai_batch_concurrency() -> int:
    if _use_vertex_ai():
        raw = os.getenv("VERTEX_AI_BATCH_CONCURRENCY", "").strip()
        try:
            value = int(raw) if raw else 1
        except ValueError:
            value = 1
        return max(1, min(value, 4))

    raw = os.getenv("AI_BATCH_CONCURRENCY", "").strip()
    try:
        value = int(raw) if raw else 10
    except ValueError:
        value = 10
    return max(1, min(value, 20))


def _is_ai_rate_limit_error(error: BaseException) -> bool:
    status = getattr(getattr(error, "response", None), "status_code", None)
    if status == 429:
        return True
    if isinstance(error, HTTPException) and error.status_code == 429:
        return True
    text = str(error).lower()
    return (
        "429" in text
        or "rate limit" in text
        or "too many requests" in text
        or "resource has been exhausted" in text
        or "resource exhausted" in text
    )


def _run_adaptive_ai_batch_tasks(
    tasks: list[tuple[int, str]],
    run_task: Callable[[int, str], Union[str, tuple]],
    make_failure: Callable[[int, str, BaseException], dict[str, Any]],
    *,
    initial_concurrency: int,
) -> tuple[dict[tuple[int, str], Union[str, tuple]], list[dict[str, Any]], dict[str, int]]:
    current_concurrency = max(1, initial_concurrency)
    pending = list(tasks)
    active = {}
    results: dict[tuple[int, str], Union[str, tuple]] = {}
    failed: list[dict[str, Any]] = []
    rate_limit_throttles = 0

    with ThreadPoolExecutor(max_workers=current_concurrency) as pool:
        while pending or active:
            while pending and len(active) < current_concurrency:
                product_id, field = pending.pop(0)
                active[pool.submit(run_task, product_id, field)] = (product_id, field)

            if not active:
                continue

            done, _ = wait(active.keys(), return_when=FIRST_COMPLETED)
            for future in done:
                product_id, field = active.pop(future)
                try:
                    results[(product_id, field)] = future.result()
                except BaseException as error:
                    failed.append(make_failure(product_id, field, error))
                    if _is_ai_rate_limit_error(error) and current_concurrency > 1:
                        current_concurrency = max(1, current_concurrency // 2)
                        rate_limit_throttles += 1

    return results, failed, {
        "initial_concurrency": max(1, initial_concurrency),
        "final_concurrency": current_concurrency,
        "rate_limit_throttles": rate_limit_throttles,
    }


