def _get_proxy_url() -> str:
    for key in PROXY_ENV_KEYS:
        value = os.getenv(key, "").strip()
        if value:
            return value
    return ""


def _first_env_value(*keys: str) -> str:
    for key in keys:
        value = os.getenv(key, "").strip()
        if value:
            return value
    return ""


def _settings_or_env(stored: dict[str, Any], settings_key: str, *env_keys: str) -> str:
    return str(stored.get(settings_key, "")).strip() or _first_env_value(*env_keys)


def _should_retry_without_proxy(exc: Exception) -> bool:
    if not _get_proxy_url():
        return False

    seen: set[int] = set()
    pending: list[Optional[BaseException]] = [exc]
    while pending:
        current = pending.pop()
        if current is None:
            continue
        current_id = id(current)
        if current_id in seen:
            continue
        seen.add(current_id)

        message = str(current).lower()
        if (
            "connection refused" in message
            or "econnrefused" in message
            or "server disconnected without sending a response" in message
            or "remoteprotocolerror" in message
            or "connection reset" in message
        ):
            return True

        pending.append(current.__cause__)
        pending.append(current.__context__)

    return False


def _redact_http_log_url(url: str) -> str:
    text = str(url or "")
    text = re.sub(r"(://)[^/@\s:]+:[^/@\s]+@", r"\1<redacted>@", text)
    return re.sub(
        r"([?&](?:key|api_key|token|access_token|consumer_key|consumer_secret|password|pass)=)[^&\s]+",
        r"\1<redacted>",
        text,
        flags=re.IGNORECASE,
    )


def _log_httpx_timeout(method: str, url: str, timeout: float, transport: str) -> None:
    api_logger.warning(
        "[httpx-timeout] %s %s timed out after %ss via %s",
        method.upper(),
        _redact_http_log_url(url),
        timeout,
        transport,
    )


def _httpx_request_with_proxy_fallback(
    method: str,
    url: str,
    *,
    timeout: float,
    follow_redirects: bool = True,
    verify: Any = True,
    apply_wp_rest_bypass: bool = True,
    **kwargs: Any,
) -> httpx.Response:
    request_kwargs = _with_wp_rest_bypass_headers(url, kwargs) if apply_wp_rest_bypass else kwargs
    try:
        with httpx.Client(timeout=timeout, follow_redirects=follow_redirects, verify=verify) as client:
            return client.request(method, url, **request_kwargs)
    except httpx.TimeoutException:
        _log_httpx_timeout(method, url, timeout, "env-proxy")
        raise
    except httpx.HTTPError as exc:
        if not _should_retry_without_proxy(exc):
            raise
        print(f"[httpx] Proxy {_get_proxy_url()} failed for {url}; retrying direct.")

    try:
        with httpx.Client(timeout=timeout, follow_redirects=follow_redirects, trust_env=False, verify=verify) as client:
            return client.request(method, url, **request_kwargs)
    except httpx.TimeoutException:
        _log_httpx_timeout(method, url, timeout, "direct")
        raise


def _configured_wp_url(*, include_hardcoded: bool = True) -> str:
    stored = _effective_settings()
    return _settings_or_env(stored, "wpUrl", "WP_URL", "WP_BASE_URL")


def _is_placeholder_wp_url(wp_url: str) -> bool:
    parsed = urlparse(str(wp_url or "").strip())
    host = parsed.netloc.lower().split("@")[-1].split(":")[0]
    return host in {"example.com", "www.example.com", "your-site.com", "www.your-site.com"}


def _reject_placeholder_wp_url(wp_url: str) -> None:
    if not _is_placeholder_wp_url(wp_url):
        return
    raise HTTPException(
        status_code=400,
        detail=(
            f"WordPress URL 还是占位地址 {wp_url!r}，请在设置里填写真实的 WordPress 站点网址。"
        ),
    )


def _utc_now_iso() -> str:
    return f"{datetime.utcnow().replace(microsecond=0).isoformat()}Z"


def _is_running_in_docker() -> bool:
    if Path("/.dockerenv").exists():
        return True
    try:
        cgroup = Path("/proc/1/cgroup").read_text(encoding="utf-8", errors="ignore").lower()
    except OSError:
        return False
    return any(marker in cgroup for marker in ("docker", "containerd", "kubepods"))


def _system_status_check(
    key: str,
    label: str,
    ok: bool,
    detail: str,
    owner: str,
    *,
    status: Optional[str] = None,
    url: str = "",
    http_status: Optional[int] = None,
) -> dict[str, Any]:
    payload: dict[str, Any] = {
        "key": key,
        "label": label,
        "ok": ok,
        "status": status or ("ok" if ok else "error"),
        "owner": owner,
        "detail": detail,
    }
    if url:
        payload["url"] = url
    if http_status is not None:
        payload["httpStatus"] = http_status
    return payload


def _probe_configured_wordpress_reachability(timeout: float = 4.0) -> dict[str, Any]:
    wp_url = _configured_wp_url(include_hardcoded=False).strip()
    if not wp_url:
        return {
            "ok": False,
            "detail": "后端还没有配置 WordPress URL，无法检查 WordPress 连接。",
            "url": "",
            "httpStatus": None,
            "status": "warning",
        }
    if _is_placeholder_wp_url(wp_url):
        return {
            "ok": False,
            "detail": f"WordPress URL 还是占位地址：{wp_url}",
            "url": wp_url,
            "httpStatus": None,
            "status": "warning",
        }

    parsed = urlparse(wp_url)
    if parsed.scheme not in {"http", "https"} or not parsed.netloc:
        return {
            "ok": False,
            "detail": f"WordPress URL 格式不正确，需要包含 http:// 或 https://：{wp_url}",
            "url": wp_url,
            "httpStatus": None,
            "status": "warning",
        }

    target = f"{wp_url.rstrip('/')}/wp-json/"
    try:
        resp = _http_request_with_proxy_fallback(
            "GET",
            target,
            timeout=timeout,
            headers={"Accept": "application/json"},
        )
    except Exception as exc:
        return {
            "ok": False,
            "detail": f"后端服务无法访问 WordPress：{exc}",
            "url": target,
            "httpStatus": None,
        }

    if resp.status_code < 400:
        detail = f"后端服务可访问 WordPress REST API（HTTP {resp.status_code}）。"
        ok = True
    elif resp.status_code < 500:
        detail = f"后端服务已连到 WordPress，但返回 HTTP {resp.status_code}；这通常是认证或安全策略，不是断网。"
        ok = True
    else:
        detail = f"后端服务已连到 WordPress，但远端返回 HTTP {resp.status_code}。"
        ok = False

    return {
        "ok": ok,
        "detail": detail,
        "url": target,
        "httpStatus": resp.status_code,
    }


def _probe_configured_woocommerce_reachability(timeout: float = 4.0) -> dict[str, Any]:
    stored = _effective_settings()
    wp_url = _settings_or_env(stored, "wpUrl", "WP_URL", "WP_BASE_URL").strip()
    if not wp_url:
        return {
            "ok": False,
            "detail": "先填写 WordPress URL，才能检查 WooCommerce 连接。",
            "url": "",
            "httpStatus": None,
            "status": "warning",
        }
    if _is_placeholder_wp_url(wp_url):
        return {
            "ok": False,
            "detail": f"WordPress URL 还是占位地址：{wp_url}，暂不能检查 WooCommerce。",
            "url": wp_url,
            "httpStatus": None,
            "status": "warning",
        }

    wc_key = (
        str(stored.get("wcConsumerKey", "")).strip()
        or os.getenv("WC_CONSUMER_KEY", "").strip()
    )
    wc_secret = (
        str(stored.get("wcConsumerSecret", "")).strip()
        or os.getenv("WC_CONSUMER_SECRET", "").strip()
    )
    if not wc_key or not wc_secret:
        return {
            "ok": False,
            "detail": "还没有配置 WooCommerce Consumer Key / Secret，产品扫描与同步暂不可用。",
            "url": "",
            "httpStatus": None,
            "status": "warning",
        }

    parsed = urlparse(wp_url)
    if parsed.scheme not in {"http", "https"} or not parsed.netloc:
        return {
            "ok": False,
            "detail": f"WordPress URL 格式不正确，暂不能检查 WooCommerce：{wp_url}",
            "url": wp_url,
            "httpStatus": None,
            "status": "warning",
        }

    target = f"{wp_url.rstrip('/')}/wp-json/wc/v3/products"
    try:
        resp = _http_request_with_proxy_fallback(
            "GET",
            target,
            timeout=timeout,
            params={"per_page": "1", "page": "1"},
            auth=(wc_key, wc_secret),
            headers={"Accept": "application/json"},
        )
    except Exception as exc:
        return {
            "ok": False,
            "detail": f"后端服务无法访问 WooCommerce API：{exc}",
            "url": target,
            "httpStatus": None,
        }

    if resp.status_code < 400:
        return {
            "ok": True,
            "detail": f"WooCommerce 产品 API 可访问（HTTP {resp.status_code}）。",
            "url": target,
            "httpStatus": resp.status_code,
        }
    if resp.status_code in {401, 403}:
        return {
            "ok": False,
            "detail": f"WooCommerce 已响应，但 Consumer Key / Secret 无权限或不正确（HTTP {resp.status_code}）。",
            "url": target,
            "httpStatus": resp.status_code,
            "status": "warning",
        }
    return {
        "ok": False,
        "detail": f"WooCommerce 已响应，但返回 HTTP {resp.status_code}。",
        "url": target,
        "httpStatus": resp.status_code,
    }


def _failed_system_probe(label: str, exc: Exception) -> dict[str, Any]:
    return {
        "ok": False,
        "detail": f"{label} 检查失败：{exc}",
        "url": "",
        "httpStatus": None,
    }


def _run_configured_site_reachability_probes() -> tuple[dict[str, Any], dict[str, Any]]:
    with ThreadPoolExecutor(max_workers=2) as pool:
        wp_future = pool.submit(
            _probe_configured_wordpress_reachability,
            SYSTEM_NETWORK_STATUS_PROBE_TIMEOUT_SECONDS,
        )
        woo_future = pool.submit(
            _probe_configured_woocommerce_reachability,
            SYSTEM_NETWORK_STATUS_PROBE_TIMEOUT_SECONDS,
        )
        try:
            wp_probe = wp_future.result(timeout=SYSTEM_NETWORK_STATUS_TOTAL_TIMEOUT_SECONDS)
        except Exception as exc:
            wp_probe = _failed_system_probe("WordPress", exc)
        try:
            woo_probe = woo_future.result(timeout=SYSTEM_NETWORK_STATUS_TOTAL_TIMEOUT_SECONDS)
        except Exception as exc:
            woo_probe = _failed_system_probe("WooCommerce", exc)
    return wp_probe, woo_probe


def _build_system_network_status() -> dict[str, Any]:
    started_at = time.monotonic()
    in_docker = _is_running_in_docker()
    wp_probe, woo_probe = _run_configured_site_reachability_probes()
    woo_warning_label = (
        "WooCommerce 权限"
        if woo_probe.get("httpStatus") in {401, 403}
        else "WooCommerce 配置"
    )
    checks = [
        _system_status_check(
            "backend",
            "后端 API",
            True,
            "后端服务已响应，业务电脑已经连到后端 API。",
            "server",
        ),
        _system_status_check(
            "runtime",
            "后端运行方式",
            True,
            "当前是容器运行模式。" if in_docker else "当前是本机开发模式。",
            "server",
            status="info",
        ),
        _system_status_check(
            "wordpress",
            "WordPress 配置" if wp_probe.get("status") == "warning" else "WordPress 连接",
            bool(wp_probe["ok"]),
            str(wp_probe["detail"]),
            "server",
            status=str(wp_probe.get("status") or ""),
            url=str(wp_probe.get("url") or ""),
            http_status=wp_probe.get("httpStatus"),
        ),
        _system_status_check(
            "woocommerce",
            woo_warning_label if woo_probe.get("status") == "warning" else "WooCommerce 连接",
            bool(woo_probe["ok"]),
            str(woo_probe["detail"]),
            "server",
            status=str(woo_probe.get("status") or ""),
            url=str(woo_probe.get("url") or ""),
            http_status=woo_probe.get("httpStatus"),
        ),
    ]
    failed = [check for check in checks if not check["ok"]]
    problem_area = "none"
    summary = "系统连接正常"
    if failed:
        if any(check.get("key") in {"wordpress", "woocommerce"} and check.get("status") == "warning" for check in failed):
            problem_area = "configuration"
        else:
            first_owner = failed[0]["owner"]
            problem_area = first_owner if first_owner in {"server", "backend", "businessComputer"} else "unknown"
        summary_by_area = {
            "businessComputer": "业务电脑网络异常",
            "server": "站点连接异常",
            "backend": "后端服务异常",
            "configuration": "站点配置待完善",
            "unknown": "网络状态异常",
        }
        summary = summary_by_area.get(problem_area, "网络状态异常")

    return {
        "ok": not failed,
        "checkedAt": _utc_now_iso(),
        "summary": summary,
        "problemArea": problem_area,
        "checks": checks,
        "durationMs": int((time.monotonic() - started_at) * 1000),
    }


def _read_persisted_system_network_status_cache() -> None:
    if _system_network_status_cache or not _SYSTEM_NETWORK_STATUS_CACHE_FILE.exists():
        return
    try:
        payload = json.loads(_SYSTEM_NETWORK_STATUS_CACHE_FILE.read_text(encoding="utf-8"))
    except Exception:
        return
    status = payload.get("status") if isinstance(payload, dict) else None
    if not isinstance(status, dict):
        return
    wall_checked_at = payload.get("checked_wall_at")
    if isinstance(wall_checked_at, (int, float)):
        checked_at = time.monotonic() - max(0.0, time.time() - float(wall_checked_at))
    else:
        checked_at = time.monotonic() - (SYSTEM_NETWORK_STATUS_DEFAULT_MAX_AGE_SECONDS + 1)
    _system_network_status_cache.update({
        "status": status,
        "checked_at": float(checked_at),
        "checked_wall_at": float(wall_checked_at) if isinstance(wall_checked_at, (int, float)) else time.time(),
        "last_success_at": str(payload.get("last_success_at") or status.get("lastSuccessAt") or ""),
    })


def _write_persisted_system_network_status_cache() -> None:
    try:
        _SYSTEM_NETWORK_STATUS_CACHE_FILE.parent.mkdir(parents=True, exist_ok=True)
        _SYSTEM_NETWORK_STATUS_CACHE_FILE.write_text(
            json.dumps(_system_network_status_cache, ensure_ascii=False),
            encoding="utf-8",
        )
    except Exception:
        pass


def _system_status_cache_snapshot() -> Optional[dict[str, Any]]:
    with _system_network_status_lock:
        _read_persisted_system_network_status_cache()
        status = _system_network_status_cache.get("status")
        if not isinstance(status, dict):
            return None
        return {
            "status": dict(status),
            "checked_at": float(_system_network_status_cache.get("checked_at") or time.monotonic()),
            "last_success_at": str(_system_network_status_cache.get("last_success_at") or ""),
            "refreshing": bool(_system_network_status_refreshing),
        }


def _decorate_system_network_status(
    status: dict[str, Any],
    *,
    source: str,
    stale: bool,
    refreshing: bool,
    last_success_at: str = "",
) -> dict[str, Any]:
    payload = dict(status)
    payload["source"] = source
    payload["stale"] = bool(stale)
    payload["refreshing"] = bool(refreshing)
    payload["lastSuccessAt"] = last_success_at or str(payload.get("lastSuccessAt") or "")
    return payload


def _refresh_system_network_status_cache() -> dict[str, Any]:
    status = _build_system_network_status()
    checked_at = time.monotonic()
    with _system_network_status_lock:
        last_success_at = str(_system_network_status_cache.get("last_success_at") or "")
        if status.get("ok"):
            last_success_at = str(status.get("checkedAt") or _utc_now_iso())
        _system_network_status_cache.clear()
        _system_network_status_cache.update({
            "status": dict(status),
            "checked_at": checked_at,
            "checked_wall_at": time.time(),
            "last_success_at": last_success_at,
        })
        _write_persisted_system_network_status_cache()
    return _decorate_system_network_status(
        status,
        source="live",
        stale=False,
        refreshing=False,
        last_success_at=last_success_at,
    )


def _system_network_status_refresh_worker() -> None:
    global _system_network_status_refreshing
    try:
        _refresh_system_network_status_cache()
    except Exception:
        api_logger.exception("[system-network-status] Background refresh failed")
    finally:
        with _system_network_status_lock:
            _system_network_status_refreshing = False


def _start_system_network_status_refresh() -> bool:
    global _system_network_status_refreshing
    with _system_network_status_lock:
        if _system_network_status_refreshing:
            return False
        _system_network_status_refreshing = True
    threading.Thread(target=_system_network_status_refresh_worker, daemon=True).start()
    return True


def _get_system_network_status(
    *,
    prefer_cached: bool,
    background_refresh: bool,
    force_refresh: bool,
    max_age_seconds: int,
) -> dict[str, Any]:
    clean_max_age = max(0, int(max_age_seconds or 0))
    if not force_refresh and prefer_cached:
        snapshot = _system_status_cache_snapshot()
        if snapshot:
            age = max(0.0, time.monotonic() - snapshot["checked_at"])
            stale = age > clean_max_age
            refreshing = bool(snapshot["refreshing"])
            if background_refresh and stale:
                refreshing = _start_system_network_status_refresh() or refreshing
            return _decorate_system_network_status(
                snapshot["status"],
                source="cache",
                stale=stale,
                refreshing=refreshing,
                last_success_at=snapshot["last_success_at"],
            )
    return _refresh_system_network_status_cache()


@app.get("/system/network-status")
def system_network_status(
    prefer_cached: bool = False,
    background_refresh: bool = False,
    force_refresh: bool = False,
    max_age_seconds: int = SYSTEM_NETWORK_STATUS_DEFAULT_MAX_AGE_SECONDS,
):
    return _get_system_network_status(
        prefer_cached=prefer_cached,
        background_refresh=background_refresh,
        force_refresh=force_refresh,
        max_age_seconds=max_age_seconds,
    )


def _configured_wp_rest_bypass_header() -> tuple[str, str]:
    stored = _effective_settings()
    name = (
        str(stored.get("cloudflareBypassHeaderName", "")).strip()
        or os.getenv("WP_REST_BYPASS_HEADER_NAME", "").strip()
        or os.getenv("CLOUDFLARE_BYPASS_HEADER_NAME", "").strip()
    )
    value = (
        str(stored.get("cloudflareBypassHeaderValue", "")).strip()
        or os.getenv("WP_REST_BYPASS_HEADER_VALUE", "").strip()
        or os.getenv("CLOUDFLARE_BYPASS_HEADER_VALUE", "").strip()
    )
    if not name or not value:
        return "", ""
    if not re.fullmatch(r"[A-Za-z0-9!#$%&'*+.^_`|~-]+", name):
        return "", ""
    return name, value


def _is_configured_wp_rest_url(url: str) -> bool:
    wp_url = _configured_wp_url()
    if not wp_url:
        return False
    parsed_url = urlparse(url)
    parsed_wp = urlparse(wp_url)
    return (
        parsed_url.scheme in ("http", "https")
        and parsed_url.netloc.lower() == parsed_wp.netloc.lower()
        and parsed_url.path.startswith("/wp-json/")
    )


def _with_wp_rest_bypass_headers(url: str, kwargs: dict[str, Any]) -> dict[str, Any]:
    header_name, header_value = _configured_wp_rest_bypass_header()
    if not header_name or not header_value or not _is_configured_wp_rest_url(url):
        return kwargs

    merged = dict(kwargs)
    headers = dict(merged.get("headers") or {})
    for key in list(headers):
        if key.lower() == header_name.lower():
            del headers[key]
    headers[header_name] = header_value
    merged["headers"] = headers
    return merged


def _http_request_with_proxy_fallback(
    method: str,
    url: str,
    *,
    timeout: float,
    follow_redirects: bool = True,
    **kwargs: Any,
) -> httpx.Response:
    return _httpx_request_with_proxy_fallback(
        method,
        url,
        timeout=timeout,
        follow_redirects=follow_redirects,
        verify=_WP_SSL_CTX,
        **kwargs,
    )


async def _http_async_request_with_proxy_fallback(
    method: str,
    url: str,
    *,
    timeout: float,
    follow_redirects: bool = True,
    **kwargs: Any,
) -> httpx.Response:
    request_kwargs = _with_wp_rest_bypass_headers(url, kwargs)
    try:
        async with httpx.AsyncClient(timeout=timeout, follow_redirects=follow_redirects, verify=_WP_SSL_CTX) as client:
            return await client.request(method, url, **request_kwargs)
    except httpx.TimeoutException:
        _log_httpx_timeout(method, url, timeout, "env-proxy")
        raise
    except httpx.HTTPError as exc:
        if not _should_retry_without_proxy(exc):
            raise
        print(f"[httpx] Proxy {_get_proxy_url()} refused connection for {url}; retrying direct.")

    try:
        async with httpx.AsyncClient(
            timeout=timeout,
            follow_redirects=follow_redirects,
            trust_env=False,
            verify=_WP_SSL_CTX,
        ) as client:
            return await client.request(method, url, **request_kwargs)
    except httpx.TimeoutException:
        _log_httpx_timeout(method, url, timeout, "direct")
        raise


