AUTH_KDF_ITERATIONS = 210_000
AUTH_PASSWORD_MIN_LENGTH = 6
AUTH_SECRET_PREFIX = "enc:v1:"
AUTH_PUBLIC_PATH_PREFIXES = (
    "/auth/",
    "/desktop/",
    "/docs",
    "/redoc",
)
AUTH_PUBLIC_PATHS = {
    "/auth/bootstrap-status",
    "/openapi.json",
    "/favicon.ico",
    "/system/network-status",
}
SECRET_SETTING_KEYS = {
    "googleApiKey",
    "wpAppPass",
    "cloudflareBypassHeaderValue",
    "wcConsumerKey",
    "wcConsumerSecret",
    "sftpPass",
    "gscServiceAccountJson",
}
GLOBAL_SETTING_KEYS = {
    "googleApiKey",
    "aiProvider",
    "googleCloudProject",
    "googleCloudLocation",
    "googleApplicationCredentials",
    "backendUrl",
    "useProxy",
}
SITE_SCOPED_SETTING_KEYS = set(SettingsPayload.model_fields.keys()) - GLOBAL_SETTING_KEYS
_AUTH_SESSIONS: dict[str, dict[str, Any]] = {}
_REQUEST_VAULT_KEY: contextvars.ContextVar[Optional[bytes]] = contextvars.ContextVar(
    "seo_wp_sync_request_vault_key",
    default=None,
)


def _auth_b64encode(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).decode("ascii").rstrip("=")


def _auth_b64decode(value: str) -> bytes:
    text = str(value or "")
    padding = "=" * ((4 - len(text) % 4) % 4)
    return base64.urlsafe_b64decode((text + padding).encode("ascii"))


def _auth_now_iso() -> str:
    return f"{datetime.utcnow().replace(microsecond=0).isoformat()}Z"


def _read_auth_record() -> dict[str, Any]:
    if not AUTH_FILE.exists():
        return {}
    try:
        data = json.loads(AUTH_FILE.read_text(encoding="utf-8"))
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def _write_auth_record(data: dict[str, Any]) -> dict[str, Any]:
    AUTH_FILE.parent.mkdir(parents=True, exist_ok=True)
    AUTH_FILE.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")
    return data


def _auth_is_registered() -> bool:
    record = _read_auth_record()
    return bool(record.get("username") and record.get("passwordHash") and record.get("salt"))


def _auth_derive_bytes(password: str, salt_text: str, purpose: str) -> bytes:
    salt = _auth_b64decode(salt_text)
    purpose_salt = b"SeoWpSync:" + purpose.encode("utf-8") + b":" + salt
    return hashlib.pbkdf2_hmac(
        "sha256",
        str(password or "").encode("utf-8"),
        purpose_salt,
        AUTH_KDF_ITERATIONS,
        dklen=32,
    )


def _auth_password_hash(password: str, salt_text: str) -> str:
    return _auth_b64encode(_auth_derive_bytes(password, salt_text, "password"))


def _auth_vault_key(password: str, salt_text: str) -> bytes:
    return _auth_derive_bytes(password, salt_text, "vault")


def _auth_verify_password(record: dict[str, Any], password: str) -> Optional[bytes]:
    salt = str(record.get("salt") or "")
    expected = str(record.get("passwordHash") or "")
    if not salt or not expected:
        return None
    actual = _auth_password_hash(password, salt)
    if not hmac.compare_digest(actual, expected):
        return None
    return _auth_vault_key(password, salt)


def _auth_stream(key: bytes, nonce: bytes, length: int) -> bytes:
    out = bytearray()
    counter = 0
    while len(out) < length:
        out.extend(hmac.new(key, nonce + counter.to_bytes(8, "big"), hashlib.sha256).digest())
        counter += 1
    return bytes(out[:length])


def _encrypt_secret_text(value: str, key: bytes) -> str:
    text = str(value or "")
    if not text or text.startswith(AUTH_SECRET_PREFIX):
        return text
    nonce = secrets.token_bytes(16)
    plain = text.encode("utf-8")
    stream = _auth_stream(key, nonce, len(plain))
    cipher = bytes(a ^ b for a, b in zip(plain, stream))
    tag = hmac.new(key, b"settings-secret-v1" + nonce + cipher, hashlib.sha256).digest()
    payload = {
        "n": _auth_b64encode(nonce),
        "c": _auth_b64encode(cipher),
        "t": _auth_b64encode(tag),
    }
    packed = json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    return AUTH_SECRET_PREFIX + _auth_b64encode(packed)


def _decrypt_secret_text(value: str, key: bytes) -> str:
    text = str(value or "")
    if not text.startswith(AUTH_SECRET_PREFIX):
        return text
    try:
        payload = json.loads(_auth_b64decode(text[len(AUTH_SECRET_PREFIX):]).decode("utf-8"))
        nonce = _auth_b64decode(str(payload.get("n") or ""))
        cipher = _auth_b64decode(str(payload.get("c") or ""))
        expected = _auth_b64decode(str(payload.get("t") or ""))
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Stored secret is unreadable: {exc}")
    actual = hmac.new(key, b"settings-secret-v1" + nonce + cipher, hashlib.sha256).digest()
    if not hmac.compare_digest(actual, expected):
        raise HTTPException(status_code=401, detail="Stored secret cannot be decrypted with the current login.")
    stream = _auth_stream(key, nonce, len(cipher))
    plain = bytes(a ^ b for a, b in zip(cipher, stream))
    return plain.decode("utf-8")


def _vault_key_from_seed(seed: str) -> bytes:
    return hashlib.sha256(str(seed or "").encode("utf-8")).digest()


def _machine_vault_key() -> bytes:
    env_seed = (
        os.getenv("SEO_WP_SYNC_VAULT_KEY", "").strip()
        or os.getenv("SEOWPSYNC_VAULT_KEY", "").strip()
    )
    if env_seed:
        return _vault_key_from_seed(env_seed)

    try:
        if VAULT_KEY_FILE.exists():
            stored_seed = VAULT_KEY_FILE.read_text(encoding="utf-8").strip()
            if stored_seed:
                return _vault_key_from_seed(stored_seed)
        VAULT_KEY_FILE.parent.mkdir(parents=True, exist_ok=True)
        stored_seed = secrets.token_urlsafe(48)
        VAULT_KEY_FILE.write_text(stored_seed, encoding="utf-8")
        try:
            VAULT_KEY_FILE.chmod(0o600)
        except OSError:
            pass
        return _vault_key_from_seed(stored_seed)
    except OSError:
        fallback_seed = f"{APP_NAME}:vault:{USER_DATA_DIR.expanduser()}:{Path.home()}"
        return _vault_key_from_seed(fallback_seed)


def _current_vault_key() -> Optional[bytes]:
    return _REQUEST_VAULT_KEY.get() or _machine_vault_key()


def _decrypt_settings_secrets(data: dict[str, Any], key: Optional[bytes]) -> dict[str, Any]:
    if not key:
        return data
    decrypted = dict(data)
    for field in SECRET_SETTING_KEYS:
        value = decrypted.get(field)
        if isinstance(value, str):
            try:
                decrypted[field] = _decrypt_secret_text(value, key)
            except HTTPException:
                decrypted[field] = ""
    return decrypted


def _encrypt_settings_secrets(data: dict[str, Any], key: Optional[bytes]) -> dict[str, Any]:
    if not key:
        return data
    encrypted = dict(data)
    for field in SECRET_SETTING_KEYS:
        value = encrypted.get(field)
        if isinstance(value, str) and value:
            encrypted[field] = _encrypt_secret_text(value, key)
    return encrypted


def _create_auth_session(username: str, vault_key: bytes) -> str:
    token = secrets.token_urlsafe(32)
    _AUTH_SESSIONS[token] = {
        "username": username,
        "vaultKey": vault_key,
        "createdAt": _auth_now_iso(),
    }
    return token


def _auth_token_from_request(request: Request) -> str:
    auth = str(request.headers.get("authorization") or "").strip()
    if auth.lower().startswith("bearer "):
        return auth[7:].strip()
    return str(request.headers.get("x-seo-wp-sync-session") or "").strip()


def _auth_session_for_token(token: str) -> Optional[dict[str, Any]]:
    if not token:
        return None
    return _AUTH_SESSIONS.get(token)


def _auth_path_is_public(path: str) -> bool:
    if path in AUTH_PUBLIC_PATHS:
        return True
    return any(path == prefix.rstrip("/") or path.startswith(prefix) for prefix in AUTH_PUBLIC_PATH_PREFIXES)


@app.middleware("http")
async def _local_auth_middleware(request: Request, call_next):
    path = request.url.path
    if _auth_path_is_public(path):
        return await call_next(request)

    session = _auth_session_for_token(_auth_token_from_request(request))
    if not session:
        return await call_next(request)

    context_token = _REQUEST_VAULT_KEY.set(session["vaultKey"])
    try:
        return await call_next(request)
    finally:
        _REQUEST_VAULT_KEY.reset(context_token)


def _parse_origins() -> list[str]:
    value = os.getenv("CORS_ORIGINS", "*").strip()
    if value == "*":
        return ["*"]
    return [o.strip() for o in value.split(",") if o.strip()]


app.add_middleware(
    CORSMiddleware,
    allow_origins=_parse_origins(),
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)


def _read_settings_raw() -> dict[str, Any]:
    if not SETTINGS_FILE.exists():
        return {}
    try:
        data = json.loads(SETTINGS_FILE.read_text(encoding="utf-8"))
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def _read_settings() -> dict[str, Any]:
    return _decrypt_settings_secrets(_read_settings_raw(), _current_vault_key())


def _write_settings(data: dict[str, Any]) -> dict[str, Any]:
    SETTINGS_FILE.parent.mkdir(parents=True, exist_ok=True)
    stored = _encrypt_settings_secrets(data, _current_vault_key())
    SETTINGS_FILE.write_text(
        json.dumps(stored, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    return data


def _is_desktop_runtime() -> bool:
    value = os.getenv("SEO_WP_SYNC_DESKTOP_RUNTIME", "").strip().lower()
    if value in {"1", "true", "yes", "on"}:
        return True
    return bool(
        os.getenv("SEO_WP_SYNC_BACKEND_URL", "").strip()
        and os.getenv("SEO_WP_SYNC_BACKEND_PORT", "").strip()
    )


def _settings_backend_url(value: Any = "") -> str:
    if _is_desktop_runtime():
        return "/api"
    return str(value or "").strip() or os.getenv("SEO_WP_SYNC_BACKEND_URL", "").strip() or "/api"


PROFILE_TEMPLATE_KEYS = {
    "productSlug",
    "productShortDescription",
    "productFullDescription",
    "tagNames",
    "imageSeo",
    "blogStandard",
    "blogExhibition",
    "blogCertificate",
    "blogProject",
    "pagePlanner",
    "brandVoice",
    "enabledProductFields",
    "customProductFields",
}

PRODUCT_PROFILE_FIELD_KEYS = {
    "slug",
    "short_description",
    "description",
    "acf_seo_extra_info",
    "aioseo_title",
    "aioseo_description",
    "tag_names",
}

DEFAULT_PROFILE_PRODUCT_FIELDS = [
    "slug",
    "short_description",
    "description",
    "aioseo_title",
    "aioseo_description",
    "tag_names",
]

KNOWLEDGE_ARTIFACT_KINDS = {
    "company",
    "product",
    "keyword",
    "field_rules",
    "general",
}

RULE_PACK_TASK_CONTEXT_KEYS = {
    "productPage",
    "blog",
    "imageSeo",
    "pagePlanner",
    "pageSeo",
    "seoAuditRepair",
}


def _profile_secret_key() -> bytes:
    seed = os.getenv("SEO_WP_SYNC_PROFILE_SECRET", "").strip()
    if seed:
        return _vault_key_from_seed(seed)
    request_key = _REQUEST_VAULT_KEY.get()
    if request_key:
        return request_key
    return _machine_vault_key()


def _legacy_profile_secret_key() -> bytes:
    return _vault_key_from_seed(f"{APP_NAME}:{USER_DATA_DIR.expanduser()}:{Path.home()}")


def _profile_secret_key_candidates() -> list[bytes]:
    candidates = [_profile_secret_key(), _legacy_profile_secret_key()]
    unique: list[bytes] = []
    for key in candidates:
        if not any(hmac.compare_digest(key, existing) for existing in unique):
            unique.append(key)
    return unique


def _profile_slug(value: str, fallback: str = "profile") -> str:
    raw = str(value or "").strip().lower()
    slug = re.sub(r"[^a-z0-9]+", "-", raw).strip("-")
    return slug or fallback


def _unique_profile_id(base: str, existing_ids: set[str]) -> str:
    root = _profile_slug(base)
    candidate = root
    index = 2
    while candidate in existing_ids:
        candidate = f"{root}-{index}"
        index += 1
    return candidate


def _split_profile_settings(settings: dict[str, Any]) -> tuple[dict[str, Any], dict[str, str]]:
    public_settings: dict[str, Any] = {}
    secrets_map: dict[str, str] = {}
    key = _profile_secret_key()
    allowed = SITE_SCOPED_SETTING_KEYS
    for field, value in dict(settings or {}).items():
        if field not in allowed:
            continue
        if field in SECRET_SETTING_KEYS:
            text = str(value or "")
            if text:
                secrets_map[field] = _encrypt_secret_text(text, key)
            continue
        public_settings[field] = value
    return public_settings, secrets_map


def _merge_profile_settings(profile: dict[str, Any], updates: dict[str, Any]) -> dict[str, Any]:
    public_updates, secret_updates = _split_profile_settings(updates)
    current_settings = dict(profile.get("settings") or {})
    current_settings.update(public_updates)
    profile["settings"] = current_settings
    secrets_map = dict(profile.get("secrets") or {})
    secrets_map.update(secret_updates)
    profile["secrets"] = secrets_map
    return profile


def _normalize_template_pack(template_pack: dict[str, Any]) -> dict[str, str]:
    normalized: dict[str, str] = {}
    for key, value in dict(template_pack or {}).items():
        if key in PROFILE_TEMPLATE_KEYS and isinstance(value, str):
            normalized[key] = value.strip()
    return normalized


def _normalize_product_field_list(value: Any) -> list[str]:
    if isinstance(value, list):
        raw_items = value
    else:
        raw_items = re.split(r"[\n,;|]+", str(value or ""))
    out: list[str] = []
    for raw in raw_items:
        key = str(raw or "").strip()
        if key in PRODUCT_PROFILE_FIELD_KEYS and key not in out:
            out.append(key)
    return out


def _enabled_product_fields_from_template_pack(template_pack: dict[str, Any]) -> list[str]:
    pack = dict(template_pack or {})
    if "enabledProductFields" not in pack:
        return list(DEFAULT_PROFILE_PRODUCT_FIELDS)
    return _normalize_product_field_list(pack.get("enabledProductFields"))


def _custom_product_meta_keys_from_template_pack(template_pack: dict[str, Any]) -> list[str]:
    pack = dict(template_pack or {})
    if "acf_seo_extra_info" not in _enabled_product_fields_from_template_pack(pack):
        return []
    out: list[str] = []
    for raw in re.split(r"[\n,;|]+", str(pack.get("customProductFields") or "")):
        key = str(raw or "").strip()
        if not key or key in out:
            continue
        if re.fullmatch(r"[A-Za-z0-9_:\-.]{1,96}", key):
            out.append(key)
    return out


def _active_profile_product_fields() -> list[str]:
    try:
        store = _load_client_profile_store(create=False)
        if not store.get("profiles"):
            return list(DEFAULT_PROFILE_PRODUCT_FIELDS)
        profile = _active_client_profile(store)
        return _enabled_product_fields_from_template_pack(profile.get("templatePack") or {})
    except Exception:
        return list(DEFAULT_PROFILE_PRODUCT_FIELDS)


def _active_profile_custom_product_meta_keys() -> list[str]:
    try:
        store = _load_client_profile_store(create=False)
        if not store.get("profiles"):
            return []
        profile = _active_client_profile(store)
        return _custom_product_meta_keys_from_template_pack(profile.get("templatePack") or {})
    except Exception:
        return []


def _active_profile_product_field_set() -> set[str]:
    return set(_active_profile_product_fields())


def _product_profile_field_enabled(field: str) -> bool:
    return field in _active_profile_product_field_set()


def _normalize_profile_knowledge_source(source: dict[str, Any]) -> dict[str, Any]:
    source_id = str(source.get("id") or "").strip()
    filename = str(source.get("filename") or "").strip()
    stored_name = str(source.get("storedName") or "").strip()
    if not source_id or not filename or not stored_name:
        return {}
    text_stored_name = str(source.get("textStoredName") or source.get("text_stored_name") or "").strip()
    artifact_ids = [
        str(item).strip()
        for item in (source.get("artifactIds") if isinstance(source.get("artifactIds"), list) else [])
        if str(item).strip()
    ]
    extraction_status = str(source.get("extractionStatus") or "pending").strip().lower()
    if extraction_status not in {"pending", "extracted", "failed", "skipped"}:
        extraction_status = "pending"
    review_status = str(source.get("reviewStatus") or "unreviewed").strip().lower()
    if review_status not in {"unreviewed", "needs_review", "reviewed", "rejected"}:
        review_status = "unreviewed"
    return {
        "id": source_id,
        "label": str(source.get("label") or filename).strip() or filename,
        "sourceType": str(source.get("sourceType") or "general").strip() or "general",
        "filename": filename,
        "storedName": stored_name,
        "textStoredName": text_stored_name,
        "contentType": str(source.get("contentType") or "text/plain"),
        "size": int(source.get("size") or 0),
        "chars": int(source.get("chars") or 0),
        "enabled": _settings_bool(source.get("enabled", True), True),
        "extractionStatus": extraction_status,
        "artifactIds": artifact_ids,
        "reviewStatus": review_status,
        "createdAt": str(source.get("createdAt") or ""),
    }


def _profile_knowledge_public(source: dict[str, Any]) -> dict[str, Any]:
    return {
        "id": source["id"],
        "label": source.get("label", source["filename"]),
        "sourceType": source.get("sourceType", "general"),
        "filename": source["filename"],
        "contentType": source.get("contentType", "text/plain"),
        "size": source.get("size", 0),
        "chars": source.get("chars", 0),
        "enabled": source.get("enabled", True),
        "extractionStatus": source.get("extractionStatus", "pending"),
        "artifactIds": list(source.get("artifactIds") or []),
        "reviewStatus": source.get("reviewStatus", "unreviewed"),
        "createdAt": source.get("createdAt", ""),
    }


def _should_include_legacy_skill_sources(profile: dict[str, Any]) -> bool:
    return str(profile.get("id") or "").strip() == "default"


def _legacy_skill_source_id(relative_path: str) -> str:
    cleaned = re.sub(r"[^a-z0-9]+", "-", relative_path.lower()).strip("-")
    return f"builtin-skills-{cleaned}"


def _legacy_skill_source_from_path(relative_path: str, source_type: str) -> dict[str, Any]:
    path = SKILLS_DIR / relative_path
    try:
        text = path.read_text(encoding="utf-8")
        size = path.stat().st_size
    except Exception:
        return {}
    filename = path.name
    return {
        "id": _legacy_skill_source_id(relative_path),
        "label": filename,
        "sourceType": source_type,
        "filename": filename,
        "storedName": f"{LEGACY_SKILLS_STORED_PREFIX}{relative_path}",
        "contentType": "text/markdown",
        "size": int(size),
        "chars": len(text),
        "enabled": True,
        "createdAt": "",
    }


def _legacy_skill_profile_sources() -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    seen: set[str] = set()
    for relative_path, source_type in LEGACY_SKILLS_PROFILE_SOURCE_FILES:
        source = _legacy_skill_source_from_path(relative_path, source_type)
        if source and source["id"] not in seen:
            rows.append(source)
            seen.add(source["id"])

    for path in sorted(SKILLS_DIR.glob(LEGACY_SKILLS_KEYWORD_GLOB)):
        if path.name == "README.md":
            continue
        try:
            relative_path = path.relative_to(SKILLS_DIR).as_posix()
        except ValueError:
            continue
        source = _legacy_skill_source_from_path(relative_path, "keyword")
        if source and source["id"] not in seen:
            rows.append(source)
            seen.add(source["id"])
    return rows


def _profile_knowledge_sources(profile: dict[str, Any]) -> list[dict[str, Any]]:
    sources = list(profile.get("knowledgeSources") or [])
    if not _should_include_legacy_skill_sources(profile):
        return sources

    seen = {str(source.get("id") or "") for source in sources if isinstance(source, dict)}
    for source in _legacy_skill_profile_sources():
        if source["id"] in seen:
            continue
        sources.append(source)
        seen.add(source["id"])
    return sources


def _normalize_artifact_kind(value: Any) -> str:
    cleaned = str(value or "general").strip().lower().replace("-", "_").replace(" ", "_")
    aliases = {
        "company_info": "company",
        "company_information": "company",
        "product_info": "product",
        "product_information": "product",
        "keywords": "keyword",
        "product_keywords": "keyword",
        "fieldrules": "field_rules",
        "field_rule": "field_rules",
        "rules": "field_rules",
        "rule_pack": "field_rules",
    }
    cleaned = aliases.get(cleaned, cleaned)
    return cleaned if cleaned in KNOWLEDGE_ARTIFACT_KINDS else "general"


def _normalize_artifact_status(value: Any) -> str:
    cleaned = str(value or "draft").strip().lower()
    if cleaned in {"reviewed", "approved", "published"}:
        return "reviewed"
    if cleaned in {"rejected", "reject", "declined", "denied", "failed"}:
        return "rejected"
    if cleaned in {"archived", "disabled"}:
        return "archived"
    return "draft"


def _normalize_knowledge_markdown(value: Any) -> str:
    markdown = str(value or "").strip()
    if not markdown:
        return ""
    markdown = re.sub(r"<br\s*/?>", "\n", markdown, flags=re.I)
    markdown = re.sub(r"\n{3,}", "\n\n", markdown)
    return markdown.strip()


def _normalize_knowledge_artifact(artifact: dict[str, Any], fallback_source_ids: Optional[list[str]] = None) -> dict[str, Any]:
    now = _utc_now_iso()
    source_ids = artifact.get("sourceIds") or artifact.get("source_ids") or fallback_source_ids or []
    if isinstance(source_ids, str):
        source_ids = re.split(r"[\n,;|]+", source_ids)
    normalized_source_ids = [
        str(item).strip()
        for item in (source_ids if isinstance(source_ids, list) else [])
        if str(item).strip()
    ]
    title = str(artifact.get("title") or artifact.get("filename") or "").strip()
    kind = _normalize_artifact_kind(artifact.get("kind") or artifact.get("type"))
    if not title:
        title = {
            "company": "company.md",
            "product": "products/general.md",
            "keyword": "keywords/general.md",
            "field_rules": "field-rules.md",
        }.get(kind, "general.md")
    return {
        "id": str(artifact.get("id") or uuid.uuid4().hex),
        "kind": kind,
        "title": title[:180],
        "markdown": _normalize_knowledge_markdown(artifact.get("markdown") or artifact.get("content") or ""),
        "sourceIds": normalized_source_ids,
        "status": _normalize_artifact_status(artifact.get("status")),
        "createdAt": str(artifact.get("createdAt") or now),
        "updatedAt": str(artifact.get("updatedAt") or now),
    }


def _knowledge_artifact_public(artifact: dict[str, Any]) -> dict[str, Any]:
    normalized = _normalize_knowledge_artifact(artifact)
    return {
        "id": normalized["id"],
        "kind": normalized["kind"],
        "title": normalized["title"],
        "markdown": normalized["markdown"],
        "sourceIds": list(normalized.get("sourceIds") or []),
        "status": normalized["status"],
        "createdAt": normalized.get("createdAt", ""),
        "updatedAt": normalized.get("updatedAt", ""),
    }


def _normalize_profile_knowledge_artifacts(raw_artifacts: Any) -> list[dict[str, Any]]:
    if not isinstance(raw_artifacts, list):
        return []
    artifacts: list[dict[str, Any]] = []
    seen: set[str] = set()
    for raw in raw_artifacts:
        if not isinstance(raw, dict):
            continue
        artifact = _normalize_knowledge_artifact(raw)
        if artifact["status"] in {"rejected", "archived"}:
            continue
        if not artifact["markdown"] or artifact["id"] in seen:
            continue
        seen.add(artifact["id"])
        artifacts.append(artifact)
    return artifacts


def _normalize_rule_text_map(value: Any, allowed_keys: Optional[set[str]] = None) -> dict[str, str]:
    if not isinstance(value, dict):
        return {}
    out: dict[str, str] = {}
    for key, raw_value in value.items():
        cleaned_key = str(key or "").strip()
        if not cleaned_key:
            continue
        if allowed_keys is not None and cleaned_key not in allowed_keys:
            continue
        if isinstance(raw_value, (dict, list)):
            text = json.dumps(raw_value, ensure_ascii=False)
        else:
            text = str(raw_value or "").strip()
        if text:
            out[cleaned_key] = text
    return out


def _normalize_rule_pack(value: Any) -> dict[str, Any]:
    raw = value if isinstance(value, dict) else {}
    source_artifact_ids = raw.get("sourceArtifactIds") or raw.get("source_artifact_ids") or []
    if isinstance(source_artifact_ids, str):
        source_artifact_ids = re.split(r"[\n,;|]+", source_artifact_ids)
    version = int(raw.get("version") or 0)
    updated_at = str(raw.get("updatedAt") or raw.get("updated_at") or "")
    return {
        "version": max(0, version),
        "fieldRules": _normalize_rule_text_map(raw.get("fieldRules") or raw.get("field_rules")),
        "taskContexts": _normalize_rule_text_map(raw.get("taskContexts") or raw.get("task_contexts"), RULE_PACK_TASK_CONTEXT_KEYS),
        "sourceArtifactIds": [str(item).strip() for item in source_artifact_ids if str(item).strip()],
        "status": str(raw.get("status") or "draft").strip().lower() or "draft",
        "updatedAt": updated_at,
    }


def _rule_pack_public(rule_pack: Any) -> dict[str, Any]:
    return _normalize_rule_pack(rule_pack)


def _normalize_output_version(raw: Any, fallback_version: int = 1) -> dict[str, Any]:
    item = raw if isinstance(raw, dict) else {}
    output = item.get("output") if isinstance(item.get("output"), dict) else {}
    return {
        "version": max(1, int(item.get("version") or fallback_version)),
        "output": dict(output),
        "feedback": str(item.get("feedback") or "").strip(),
        "createdAt": str(item.get("createdAt") or _utc_now_iso()),
    }


def _normalize_generation_session(raw: Any) -> dict[str, Any]:
    session = raw if isinstance(raw, dict) else {}
    selected_fields = session.get("selectedFields") or session.get("selected_fields") or []
    if isinstance(selected_fields, str):
        selected_fields = re.split(r"[\n,;|]+", selected_fields)
    output_versions = []
    for index, item in enumerate(session.get("outputVersions") if isinstance(session.get("outputVersions"), list) else []):
        if isinstance(item, dict):
            output_versions.append(_normalize_output_version(item, index + 1))
    feedback_rows = []
    for item in session.get("feedback") if isinstance(session.get("feedback"), list) else []:
        if isinstance(item, dict):
            text = str(item.get("text") or item.get("feedback") or "").strip()
            if text:
                feedback_rows.append({
                    "id": str(item.get("id") or uuid.uuid4().hex),
                    "text": text,
                    "createdAt": str(item.get("createdAt") or _utc_now_iso()),
                })
    return {
        "id": str(session.get("id") or uuid.uuid4().hex),
        "targetType": str(session.get("targetType") or session.get("target_type") or "").strip(),
        "targetId": str(session.get("targetId") or session.get("target_id") or "").strip(),
        "selectedFields": [str(item).strip() for item in selected_fields if str(item).strip()],
        "promptInputs": dict(session.get("promptInputs") or session.get("prompt_inputs") or {}),
        "outputVersions": output_versions,
        "feedback": feedback_rows,
        "acceptedVersion": int(session.get("acceptedVersion") or session.get("accepted_version") or 0),
        "syncStatus": str(session.get("syncStatus") or session.get("sync_status") or "draft").strip() or "draft",
        "createdAt": str(session.get("createdAt") or _utc_now_iso()),
        "updatedAt": str(session.get("updatedAt") or _utc_now_iso()),
    }


def _generation_session_public(session: dict[str, Any]) -> dict[str, Any]:
    return _normalize_generation_session(session)


def _normalize_profile_generation_sessions(raw_sessions: Any) -> list[dict[str, Any]]:
    if not isinstance(raw_sessions, list):
        return []
    sessions: list[dict[str, Any]] = []
    seen: set[str] = set()
    for raw in raw_sessions:
        if not isinstance(raw, dict):
            continue
        session = _normalize_generation_session(raw)
        if session["id"] in seen:
            continue
        seen.add(session["id"])
        sessions.append(session)
    return sessions


def _profile_source_text_path(profile: dict[str, Any], source: dict[str, Any]) -> Path:
    stored_name = str(source.get("textStoredName") or source.get("storedName") or "")
    if stored_name.startswith(LEGACY_SKILLS_STORED_PREFIX):
        relative_path = stored_name[len(LEGACY_SKILLS_STORED_PREFIX):].lstrip("/\\")
        return SKILLS_DIR / relative_path
    return _site_knowledge_path(profile["id"]) / stored_name


def _profile_source_original_path(profile: dict[str, Any], source: dict[str, Any]) -> Path:
    stored_name = str(source.get("storedName") or "")
    if stored_name.startswith(LEGACY_SKILLS_STORED_PREFIX):
        relative_path = stored_name[len(LEGACY_SKILLS_STORED_PREFIX):].lstrip("/\\")
        return SKILLS_DIR / relative_path
    return _site_knowledge_path(profile["id"]) / stored_name


