def _coerce_number(value: Any, default: float) -> float:
    try:
        number = float(value)
    except (TypeError, ValueError):
        return default
    return number if number == number else default


def _normalize_typography_scale(value: Any, defaults: dict[str, Any]) -> dict[str, Any]:
    raw = value if isinstance(value, dict) else {}
    return {
        "h1": int(_coerce_number(raw.get("h1"), defaults["h1"])),
        "h2": int(_coerce_number(raw.get("h2"), defaults["h2"])),
        "h3": int(_coerce_number(raw.get("h3"), defaults["h3"])),
        "body": int(_coerce_number(raw.get("body"), defaults["body"])),
        "lineHeight": round(_coerce_number(raw.get("lineHeight"), defaults["lineHeight"]), 2),
    }


def _normalize_site_style_kit(value: Any) -> dict[str, Any]:
    defaults = _default_site_style_kit()
    raw = value if isinstance(value, dict) else {}
    colors = dict(defaults["colors"])
    for key, item in dict(raw.get("colors") or {}).items():
        if isinstance(item, str) and item.strip():
            colors[str(key)] = item.strip()

    roles = dict(defaults["roles"])
    for key in roles:
        item = (raw.get("roles") or {}).get(key) if isinstance(raw.get("roles"), dict) else None
        if isinstance(item, str) and item.strip():
            roles[key] = item.strip()

    raw_typography = raw.get("typography") if isinstance(raw.get("typography"), dict) else {}
    typography = {
        "headingFont": str(raw_typography.get("headingFont") or defaults["typography"]["headingFont"]).strip(),
        "bodyFont": str(raw_typography.get("bodyFont") or defaults["typography"]["bodyFont"]).strip(),
        "headingWeight": int(_coerce_number(raw_typography.get("headingWeight"), defaults["typography"]["headingWeight"])),
        "bodyWeight": int(_coerce_number(raw_typography.get("bodyWeight"), defaults["typography"]["bodyWeight"])),
        "baseSize": int(_coerce_number(raw_typography.get("baseSize"), defaults["typography"]["baseSize"])),
        "desktopScale": round(_coerce_number(raw_typography.get("desktopScale"), defaults["typography"]["desktopScale"]), 3),
        "mobileScale": round(_coerce_number(raw_typography.get("mobileScale"), defaults["typography"]["mobileScale"]), 3),
        "desktop": _normalize_typography_scale(raw_typography.get("desktop"), defaults["typography"]["desktop"]),
        "mobile": _normalize_typography_scale(raw_typography.get("mobile"), defaults["typography"]["mobile"]),
    }
    if not typography["headingFont"]:
        typography["headingFont"] = defaults["typography"]["headingFont"]
    if not typography["bodyFont"]:
        typography["bodyFont"] = defaults["typography"]["bodyFont"]

    raw_buttons = raw.get("buttons") if isinstance(raw.get("buttons"), dict) else {}
    buttons = {
        "radius": int(_coerce_number(raw_buttons.get("radius"), defaults["buttons"]["radius"])),
        "height": int(_coerce_number(raw_buttons.get("height"), defaults["buttons"]["height"])),
        "fontWeight": int(_coerce_number(raw_buttons.get("fontWeight"), defaults["buttons"]["fontWeight"])),
    }
    return {"colors": colors, "roles": roles, "typography": typography, "buttons": buttons}


STYLE_KIT_GENERIC_FONTS = {
    "sans-serif",
    "serif",
    "monospace",
    "system-ui",
    "ui-sans-serif",
    "ui-serif",
    "arial",
    "helvetica",
    "verdana",
    "georgia",
    "times new roman",
}


def _normalize_style_hex(value: str) -> str:
    raw = str(value or "").strip().lower()
    if re.fullmatch(r"#[0-9a-f]{3}", raw):
        return "#" + "".join(ch * 2 for ch in raw[1:])
    if re.fullmatch(r"#[0-9a-f]{6}", raw):
        return raw
    return ""


def _style_color_luminance(hex_color: str) -> float:
    color = _normalize_style_hex(hex_color).lstrip("#")
    if len(color) != 6:
        return 1
    values = [int(color[i:i + 2], 16) / 255 for i in (0, 2, 4)]
    linear = [
        value / 12.92 if value <= 0.03928 else ((value + 0.055) / 1.055) ** 2.4
        for value in values
    ]
    return 0.2126 * linear[0] + 0.7152 * linear[1] + 0.0722 * linear[2]


def _extract_style_colors(css: str, source: str = "css") -> list[dict[str, Any]]:
    counts: dict[str, int] = {}
    for match in re.findall(r"#[0-9a-fA-F]{3}(?:[0-9a-fA-F]{3})?\b", css or ""):
        normalized = _normalize_style_hex(match)
        if normalized:
            counts[normalized] = counts.get(normalized, 0) + 1
    return [
        {"value": value, "count": count, "source": source}
        for value, count in sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    ]


def _font_family_from_value(value: str) -> str:
    for item in str(value or "").split(","):
        family = item.strip().strip("'\"")
        if family and family.lower() not in STYLE_KIT_GENERIC_FONTS:
            return family
    return ""


def _extract_style_fonts(css: str, source: str = "css") -> tuple[list[dict[str, Any]], str, str]:
    counts: dict[str, int] = {}
    heading_candidates: list[str] = []
    body_candidates: list[str] = []
    for raw_value in re.findall(r"font-family\s*:\s*([^;}]+)", css or "", flags=re.IGNORECASE):
        family = _font_family_from_value(raw_value)
        if family:
            counts[family] = counts.get(family, 0) + 1
    for selector, block in re.findall(r"([^{}]+)\{([^{}]+)\}", css or "", flags=re.DOTALL):
        raw_match = re.search(r"font-family\s*:\s*([^;}]+)", block, flags=re.IGNORECASE)
        family = _font_family_from_value(raw_match.group(1) if raw_match else "")
        if not family:
            continue
        selector_text = selector.lower()
        if re.search(r"\bh[1-6]\b|heading|title|hero", selector_text):
            heading_candidates.append(family)
        if re.search(r"\bbody\b|\.body|content|paragraph|p\b", selector_text):
            body_candidates.append(family)
    fonts = [
        {"family": family, "count": count, "source": source}
        for family, count in sorted(counts.items(), key=lambda item: (-item[1], item[0].lower()))
    ]
    heading = heading_candidates[0] if heading_candidates else (fonts[0]["family"] if fonts else "")
    body = body_candidates[0] if body_candidates else (fonts[1]["family"] if len(fonts) > 1 else heading)
    return fonts, heading, body


def _extract_blog_style_metrics(css: str) -> dict[str, Any]:
    metrics: dict[str, Any] = {}
    for selector, block in re.findall(r"([^{}]+)\{([^{}]+)\}", css or "", flags=re.DOTALL):
        selector_text = re.sub(r"\s+", " ", selector).strip().lower()
        size_match = re.search(r"font-size\s*:\s*([0-9.]+)px", block, flags=re.I)
        line_match = re.search(r"line-height\s*:\s*([0-9.]+)(?:\s|;|$)", block, flags=re.I)
        width_match = re.search(r"max-width\s*:\s*([0-9.]+)px", block, flags=re.I)
        is_h2 = bool(re.search(r"(?:^|[\s>,+~])h2(?:[\s:.,#>+~]|$)", selector_text))
        is_h3 = bool(re.search(r"(?:^|[\s>,+~])h3(?:[\s:.,#>+~]|$)", selector_text))
        is_content = bool(re.search(r"entry-content|post-content|article-content|blog-content|\.content\b", selector_text))
        if is_h2 and size_match and "h2FontSizeDesktop" not in metrics:
            metrics["h2FontSizeDesktop"] = max(18, min(56, int(float(size_match.group(1)))))
        elif is_h3 and size_match and "h3FontSizeDesktop" not in metrics:
            metrics["h3FontSizeDesktop"] = max(16, min(48, int(float(size_match.group(1)))))
        elif is_content:
            if size_match and "bodyFontSizeDesktop" not in metrics:
                metrics["bodyFontSizeDesktop"] = max(12, min(32, int(float(size_match.group(1)))))
            if line_match and "bodyLineHeight" not in metrics:
                metrics["bodyLineHeight"] = max(1.2, min(2.2, round(float(line_match.group(1)), 2)))
            if width_match and "contentMaxWidth" not in metrics:
                metrics["contentMaxWidth"] = max(640, min(1200, int(float(width_match.group(1)))))
    return metrics


def _merge_style_evidence(items: list[dict[str, Any]], key: str) -> list[dict[str, Any]]:
    merged: dict[str, dict[str, Any]] = {}
    for item in items:
        value = str(item.get(key) or "").strip()
        if not value:
            continue
        existing = merged.setdefault(value.lower(), {**item, key: value, "count": 0})
        existing["count"] = int(existing.get("count") or 0) + int(item.get("count") or 0)
    return sorted(merged.values(), key=lambda item: (-int(item.get("count") or 0), str(item.get(key) or "").lower()))


def _extract_logo_url(html: str, base_url: str) -> str:
    for match in re.finditer(r"<img\b[^>]*>", html or "", flags=re.IGNORECASE):
        tag = match.group(0)
        if not re.search(r"logo|brand", tag, flags=re.IGNORECASE):
            continue
        src_match = re.search(r"\bsrc=['\"]([^'\"]+)['\"]", tag, flags=re.IGNORECASE)
        if src_match:
            return urljoin(base_url, src_match.group(1))
    icon_match = re.search(r"<link\b[^>]*rel=['\"][^'\"]*(?:icon|apple-touch-icon)[^'\"]*['\"][^>]*href=['\"]([^'\"]+)['\"]", html or "", flags=re.IGNORECASE)
    return urljoin(base_url, icon_match.group(1)) if icon_match else ""


def _fetch_style_kit_css_documents(html: str, base_url: str) -> list[tuple[str, str]]:
    documents = [("html", html or "")]
    for href in re.findall(r"<link\b[^>]*rel=['\"][^'\"]*stylesheet[^'\"]*['\"][^>]*href=['\"]([^'\"]+)['\"]", html or "", flags=re.IGNORECASE):
        css_url = urljoin(base_url, href)
        try:
            response = _http_request_with_proxy_fallback("GET", css_url, timeout=12, follow_redirects=True)
            if response.status_code == 200 and not _is_cloudflare_challenge_response(response):
                documents.append((css_url, response.text))
        except Exception:
            continue
    return documents


def _build_imported_style_kit(current: dict[str, Any], source_url: str, html: str) -> dict[str, Any]:
    style_kit = _normalize_site_style_kit(current)
    color_evidence: list[dict[str, Any]] = []
    font_evidence: list[dict[str, Any]] = []
    heading_font = ""
    body_font = ""
    blog_metrics: dict[str, Any] = {}
    for source, css in _fetch_style_kit_css_documents(html, source_url):
        color_evidence.extend(_extract_style_colors(css, source))
        fonts, heading_candidate, body_candidate = _extract_style_fonts(css, source)
        font_evidence.extend(fonts)
        heading_font = heading_font or heading_candidate
        body_font = body_font or body_candidate
        for key, value in _extract_blog_style_metrics(css).items():
            blog_metrics.setdefault(key, value)

    colors = _merge_style_evidence(color_evidence, "value")
    fonts = _merge_style_evidence(font_evidence, "family")
    usable_colors = [
        item["value"]
        for item in colors
        if _normalize_style_hex(str(item.get("value") or ""))
        and str(item.get("value")).lower() not in {"#ffffff", "#000000"}
    ]
    dark_colors = [color for color in usable_colors if _style_color_luminance(color) < 0.22]
    light_colors = [color for color in usable_colors if _style_color_luminance(color) > 0.78]
    primary = usable_colors[0] if usable_colors else style_kit["colors"]["primary"]
    primary_dark = dark_colors[0] if dark_colors else style_kit["colors"].get("primaryDark", primary)
    accent = usable_colors[1] if len(usable_colors) > 1 else style_kit["colors"].get("accent", primary)
    text = primary_dark if _style_color_luminance(primary_dark) < 0.35 else style_kit["roles"]["text"]

    style_kit["colors"] = {
        **style_kit["colors"],
        "primary": primary,
        "primaryDark": primary_dark,
        "accent": accent,
        "neutral": text,
    }
    style_kit["roles"] = {
        **style_kit["roles"],
        "pageBg": light_colors[0] if light_colors else style_kit["roles"]["pageBg"],
        "sectionBg": "#eef6ff",
        "text": text,
        "link": primary,
        "internalLink": accent if accent != primary else style_kit["roles"]["internalLink"],
        "primaryButtonBg": primary,
        "primaryButtonText": "#ffffff",
        "ctaBg": "#e8f3ff",
    }
    style_kit["typography"] = {
        **style_kit["typography"],
        "headingFont": heading_font or style_kit["typography"]["headingFont"],
        "bodyFont": body_font or heading_font or style_kit["typography"]["bodyFont"],
        "desktop": {
            **style_kit["typography"]["desktop"],
            "body": blog_metrics.get("bodyFontSizeDesktop", style_kit["typography"]["desktop"]["body"]),
            "h2": blog_metrics.get("h2FontSizeDesktop", style_kit["typography"]["desktop"]["h2"]),
            "h3": blog_metrics.get("h3FontSizeDesktop", style_kit["typography"]["desktop"]["h3"]),
            "lineHeight": blog_metrics.get("bodyLineHeight", style_kit["typography"]["desktop"]["lineHeight"]),
        },
    }
    return {
        "styleKit": _normalize_site_style_kit(style_kit),
        "evidence": {
            "sourceUrl": source_url,
            "logoUrl": _extract_logo_url(html, source_url),
            "colors": colors[:12],
            "fonts": fonts[:8],
            "blogMetrics": blog_metrics,
        },
        "warnings": [
            *([] if colors else ["未从网站样式中识别到可用品牌色。"]),
            *([] if fonts else ["未从网站样式中识别到字体声明。"]),
        ],
    }


def _blog_framework_template_note(template_pack: dict[str, str], key: str) -> str:
    text = str(template_pack.get(key) or "").strip()
    return f"\nMigrated legacy template guidance:\n{text}" if text else ""


def _blog_framework_metadata(article_type: str) -> dict[str, Any]:
    presets: dict[str, dict[str, Any]] = {
        "standard": {
            "contentGoal": "Answer the topic's search intent with useful, verified information from the current site and brief.",
            "funnelStage": "mixed",
            "targetAudience": "The audience defined by the current site context and article brief",
            "wordCount": {"min": 1200, "max": 1800},
        },
        "exhibition": {
            "contentGoal": "Turn verified event facts into a useful recap for the audience named in the brief.",
            "funnelStage": "awareness-consideration",
            "targetAudience": "Event attendees and readers interested in the confirmed event topic",
            "wordCount": {"min": 900, "max": 1400},
        },
        "certificate": {
            "contentGoal": "Explain the verified scope and relevance of a certificate without overstating coverage.",
            "funnelStage": "mixed",
            "targetAudience": "Readers who need to understand the confirmed certificate scope",
            "wordCount": {"min": 900, "max": 1400},
        },
        "project": {
            "contentGoal": "Show how a verified project requirement was addressed without exposing or inventing client facts.",
            "funnelStage": "mixed",
            "targetAudience": "The project audience defined by the supplied facts and site context",
            "wordCount": {"min": 1000, "max": 1600},
        },
        "video": {
            "contentGoal": "Turn verified video facts into a searchable article that helps the intended audience.",
            "funnelStage": "awareness-consideration",
            "targetAudience": "Viewers interested in the confirmed video topic",
            "wordCount": {"min": 800, "max": 1300},
        },
        "custom": {
            "contentGoal": "Answer the target audience's search intent with verified, useful guidance.",
            "funnelStage": "mixed",
            "targetAudience": "The audience defined for the current site and article type",
            "wordCount": {"min": 1000, "max": 1600},
        },
    }
    base = presets.get(article_type, presets["custom"])
    return {
        **base,
        "defaultLanguage": "English",
        "voiceRules": [
            "Use a professional but accessible tone and explain technical terms in plain language.",
            "Prefer active voice, varied sentence length, compact paragraphs, and logical transitions.",
            "Do not force casual filler, rhetorical questions, or emotional language into technical sections.",
            "Avoid stock AI phrases such as in today's world, dive into, unlock, and unleash.",
        ],
        "evidenceRules": [
            "Use approved site materials, product or event facts, approved FAQs, and indexed URLs as evidence.",
            "Mark a source gap instead of inventing models, certification, performance, price, lead time, or customer facts.",
            "Create comparison tables only when verified comparable data exists.",
        ],
        "preflightChecks": [
            "The opening directly answers the reader's primary question.",
            "Every factual claim is supported by available site evidence.",
            "Internal links come from the validated index and approved FAQs remain factually unchanged.",
            "Include a CTA only when the site context or brief provides a verified next action.",
        ],
    }


