def _normalize_outline_block(value: Any) -> dict[str, Any]:
    raw = value if isinstance(value, dict) else {}
    return {
        "heading": str(raw.get("heading") or "").strip() or "Section",
        "intent": str(raw.get("intent") or "").strip(),
        "required": raw.get("required") is not False,
        "contentRules": str(raw.get("contentRules") or "").strip(),
    }


def _normalize_blog_frameworks(value: Any, template_pack: Optional[dict[str, str]] = None) -> list[dict[str, Any]]:
    raw_items = value if isinstance(value, list) else []
    items: list[dict[str, Any]] = []
    seen: set[str] = set()
    valid_article_types = {"standard", "exhibition", "certificate", "project", "video", "custom"}
    for index, raw in enumerate(raw_items):
        if not isinstance(raw, dict):
            continue
        framework_id = _profile_slug(str(raw.get("id") or raw.get("label") or f"framework-{index + 1}"), f"framework-{index + 1}")
        if framework_id in seen:
            continue
        seen.add(framework_id)
        article_type = str(raw.get("articleType") or "custom").strip().lower()
        if article_type not in valid_article_types:
            article_type = "custom"
        required_inputs = raw.get("requiredInputs") if isinstance(raw.get("requiredInputs"), list) else []
        outline_blocks = [_normalize_outline_block(item) for item in raw.get("outlineBlocks") or [] if isinstance(item, dict)]
        metadata = _blog_framework_metadata(article_type)
        raw_word_count = raw.get("wordCount") if isinstance(raw.get("wordCount"), dict) else {}
        minimum = max(300, min(5000, int(_coerce_number(raw_word_count.get("min"), metadata["wordCount"]["min"]))))
        maximum = max(minimum, min(8000, int(_coerce_number(raw_word_count.get("max"), metadata["wordCount"]["max"]))))

        def framework_rules(key: str) -> list[str]:
            candidate = raw.get(key) if isinstance(raw.get(key), list) else metadata[key]
            return [str(item).strip() for item in candidate if str(item).strip()][:30]

        items.append({
            "id": framework_id,
            "label": str(raw.get("label") or framework_id.replace("-", " ").title()).strip(),
            "articleType": article_type,
            "contentGoal": str(raw.get("contentGoal") or metadata["contentGoal"]).strip()[:1200],
            "funnelStage": str(raw.get("funnelStage") or metadata["funnelStage"]).strip()[:80],
            "defaultLanguage": str(raw.get("defaultLanguage") or metadata["defaultLanguage"]).strip()[:80],
            "targetAudience": str(raw.get("targetAudience") or metadata["targetAudience"]).strip()[:1200],
            "wordCount": {"min": minimum, "max": maximum},
            "voiceRules": framework_rules("voiceRules"),
            "evidenceRules": framework_rules("evidenceRules"),
            "preflightChecks": framework_rules("preflightChecks"),
            "requiredInputs": [str(item).strip() for item in required_inputs if str(item).strip()],
            "outlineBlocks": outline_blocks or [{"heading": "Main Guidance", "intent": "", "required": True, "contentRules": ""}],
            "faqRules": str(raw.get("faqRules") or "").strip(),
            "ctaRules": str(raw.get("ctaRules") or "").strip(),
            "internalLinkRules": str(raw.get("internalLinkRules") or "").strip(),
            "mediaRules": str(raw.get("mediaRules") or "").strip(),
            "seoRules": str(raw.get("seoRules") or "").strip(),
            "prohibitedClaims": [str(item).strip() for item in raw.get("prohibitedClaims") or [] if str(item).strip()],
        })
    return items or _default_blog_frameworks(template_pack)


def _normalize_blog_framework_standard(
    value: Any,
    *,
    legacy_frameworks: Any = None,
    template_pack: Optional[dict[str, str]] = None,
) -> dict[str, Any]:
    raw = value if isinstance(value, dict) else {}
    explicit_standard = bool(raw)
    raw_frameworks = raw.get("frameworks") if isinstance(raw.get("frameworks"), list) else []
    legacy = legacy_frameworks if isinstance(legacy_frameworks, list) else []
    configured = str(raw.get("status") or "") == "configured" or (not explicit_standard and bool(legacy))
    source_frameworks = raw_frameworks if configured and raw_frameworks else (legacy if configured else [])
    return {
        "status": "configured" if configured else "default",
        "version": max(1, int(_coerce_number(raw.get("version"), 1))) if configured else 0,
        "basePresetVersion": max(1, int(_coerce_number(raw.get("basePresetVersion"), 1))) if configured else 2,
        "name": str(raw.get("name") or "站点博客撰写框架").strip()[:100],
        "frameworks": _normalize_blog_frameworks(source_frameworks, template_pack),
        "updatedAt": str(raw.get("updatedAt") or ""),
    }


FAQ_SCENARIOS = {"selection", "installation", "maintenance", "certification", "delivery", "after_sales"}
FAQ_STATUSES = {"pending", "approved", "draft"}


def _normalize_faq_item(value: Any, index: int = 0) -> dict[str, Any]:
    raw = value if isinstance(value, dict) else {}
    raw_status = str(raw.get("status") or "pending").strip().lower()
    if raw_status in {"approved", "reviewed", "published"}:
        status = "approved"
    elif raw_status == "draft":
        status = "draft"
    elif raw_status in {"pending", "disabled", "rejected"}:
        status = "pending"
    else:
        status = "pending"
    scenarios = [
        scenario
        for scenario in (str(item).strip().lower() for item in raw.get("scenarios") or [])
        if scenario in FAQ_SCENARIOS
    ]
    question = str(raw.get("question") or "").strip()
    answer = str(raw.get("answer") or "").strip()
    return {
        "id": _profile_slug(str(raw.get("id") or question or f"faq-{index + 1}"), f"faq-{index + 1}"),
        "question": question,
        "answer": answer,
        "productCategories": [str(item).strip() for item in raw.get("productCategories") or [] if str(item).strip()],
        "scenarios": scenarios,
        "keywords": [str(item).strip() for item in raw.get("keywords") or [] if str(item).strip()],
        "sourceIds": [str(item).strip() for item in raw.get("sourceIds") or [] if str(item).strip()],
        "status": status,
        "updatedAt": str(raw.get("updatedAt") or _utc_now_iso()),
    }


def _normalize_faqs(value: Any) -> list[dict[str, Any]]:
    if not isinstance(value, list):
        return []
    items: list[dict[str, Any]] = []
    seen: set[str] = set()
    for index, raw in enumerate(value):
        item = _normalize_faq_item(raw, index)
        if not item["question"] or not item["answer"] or item["id"] in seen:
            continue
        seen.add(item["id"])
        items.append(item)
    return items


def _default_internal_link_settings() -> dict[str, Any]:
    return {
        "enabled": True,
        "intervalDays": 7,
        "includeTypes": ["page", "post", "product", "category"],
        "excludePatterns": ["/cart", "/checkout", "/my-account"],
        "lastRunAt": "",
        "lastRunStatus": "",
        "lastError": "",
    }


def _normalize_internal_link_settings(value: Any) -> dict[str, Any]:
    defaults = _default_internal_link_settings()
    raw = value if isinstance(value, dict) else {}
    include_types = raw.get("includeTypes") if isinstance(raw.get("includeTypes"), list) else defaults["includeTypes"]
    exclude_patterns = raw.get("excludePatterns") if isinstance(raw.get("excludePatterns"), list) else defaults["excludePatterns"]
    return {
        "enabled": raw.get("enabled") is not False,
        "intervalDays": max(1, int(_coerce_number(raw.get("intervalDays"), defaults["intervalDays"]))),
        "includeTypes": [str(item).strip() for item in include_types if str(item).strip()],
        "excludePatterns": [str(item).strip() for item in exclude_patterns if str(item).strip()],
        "lastRunAt": str(raw.get("lastRunAt") or ""),
        "lastRunStatus": str(raw.get("lastRunStatus") or ""),
        "lastError": str(raw.get("lastError") or ""),
    }


BULK_BLOG_FORMAT_VARIANTS = ("standard", "exhibition", "certificate", "project", "video")

BLOG_FORMAT_STANDARD_TOKEN_KEYS = (
    "contentMaxWidth", "bodyFontFamily", "headingFontFamily", "bodyFontSizeDesktop",
    "bodyFontSizeMobile", "bodyLineHeight", "h2FontSizeDesktop", "h2FontSizeMobile",
    "h3FontSizeDesktop", "h3FontSizeMobile", "paragraphSpacing", "textColor", "linkColor",
    "tableHeaderBg", "tableHeaderText", "tableBorderColor", "tableCellPadding",
    "imageRadius", "ctaBg", "ctaText",
)


def _default_bulk_blog_format() -> dict[str, Any]:
    labels = {
        "standard": "普通 Blog",
        "exhibition": "展会 Blog",
        "certificate": "证书 Blog",
        "project": "项目 Blog",
        "video": "产品视频 Blog",
    }
    keywords = {
        "standard": [],
        "exhibition": ["exhibition", "trade show", "expo", "booth"],
        "certificate": ["certificate", "certification", "ce", "rohs", "iso"],
        "project": ["project", "case study", "installation"],
        "video": ["video", "youtube", "watch"],
    }
    return {
        "status": "default",
        "version": 0,
        "updatedAt": "",
        "visualStyle": {
            "contentMaxWidth": 820,
            "bodyFontFamily": "Inter, Arial, Helvetica, sans-serif",
            "headingFontFamily": "Inter, Arial, Helvetica, sans-serif",
            "bodyFontSizeDesktop": 17,
            "bodyFontSizeMobile": 16,
            "bodyLineHeight": 1.75,
            "h2FontSizeDesktop": 32,
            "h2FontSizeMobile": 26,
            "h3FontSizeDesktop": 23,
            "h3FontSizeMobile": 21,
            "textColor": "#334155",
            "linkColor": "#1476d8",
            "tableHeaderBg": "#12344d",
            "tableHeaderText": "#ffffff",
            "tableBorderColor": "#dbe5ec",
            "imageRadius": 8,
            "ctaBg": "#e8f3ff",
            "ctaText": "#172033",
        },
        "variants": {
            key: {
                "label": labels[key],
                "detectionKeywords": keywords[key],
                "tocMinHeadings": 3,
                "maxInternalLinks": 6,
                "ctaText": "",
                "factRules": "Preserve existing facts and do not invent unsupported claims.",
                "prohibitedClaims": [],
            }
            for key in BULK_BLOG_FORMAT_VARIANTS
        },
        "plugin": {
            "styleVersion": "default",
            "status": "unknown",
            "installedVersion": "",
            "lastVerifiedAt": "",
            "warning": "",
        },
    }


def _normalize_bulk_blog_format(value: Any, *, configured: Optional[bool] = None) -> dict[str, Any]:
    defaults = _default_bulk_blog_format()
    raw = value if isinstance(value, dict) else {}
    is_configured = configured if configured is not None else str(raw.get("status") or "default") == "configured"
    if not is_configured:
        raw = {}
    raw_visual = raw.get("visualStyle") if isinstance(raw.get("visualStyle"), dict) else {}
    visual = dict(defaults["visualStyle"])
    text_fields = {
        "bodyFontFamily", "headingFontFamily", "textColor", "linkColor", "tableHeaderBg",
        "tableHeaderText", "tableBorderColor", "ctaBg", "ctaText",
    }
    for key in visual:
        if key in text_fields:
            candidate = str(raw_visual.get(key) or "").strip()
            if candidate:
                visual[key] = candidate[:180]
        elif key in raw_visual:
            visual[key] = _coerce_number(raw_visual.get(key), visual[key])
    visual["contentMaxWidth"] = max(640, min(1200, int(visual["contentMaxWidth"])))
    visual["bodyLineHeight"] = max(1.2, min(2.2, float(visual["bodyLineHeight"])))
    for key in ("bodyFontSizeDesktop", "bodyFontSizeMobile", "h2FontSizeDesktop", "h2FontSizeMobile", "h3FontSizeDesktop", "h3FontSizeMobile"):
        visual[key] = max(12, min(72, int(visual[key])))
    visual["imageRadius"] = max(0, min(40, int(visual["imageRadius"])))

    raw_variants = raw.get("variants") if isinstance(raw.get("variants"), dict) else {}
    variants: dict[str, dict[str, Any]] = {}
    for key in BULK_BLOG_FORMAT_VARIANTS:
        base = defaults["variants"][key]
        candidate = raw_variants.get(key) if isinstance(raw_variants.get(key), dict) else {}
        detection = candidate.get("detectionKeywords") if isinstance(candidate.get("detectionKeywords"), list) else base["detectionKeywords"]
        prohibited = candidate.get("prohibitedClaims") if isinstance(candidate.get("prohibitedClaims"), list) else base["prohibitedClaims"]
        variants[key] = {
            "label": str(candidate.get("label") or base["label"]).strip()[:80],
            "detectionKeywords": [str(item).strip().lower() for item in detection if str(item).strip()][:30],
            "tocMinHeadings": max(2, min(12, int(_coerce_number(candidate.get("tocMinHeadings"), base["tocMinHeadings"])))),
            "maxInternalLinks": max(0, min(20, int(_coerce_number(candidate.get("maxInternalLinks"), base["maxInternalLinks"])))),
            "ctaText": str(candidate.get("ctaText") or base["ctaText"]).strip()[:1000],
            "factRules": str(candidate.get("factRules") or base["factRules"]).strip()[:2000],
            "prohibitedClaims": [str(item).strip() for item in prohibited if str(item).strip()][:30],
        }
    version = max(0, int(_coerce_number(raw.get("version"), 0)))
    plugin = raw.get("plugin") if isinstance(raw.get("plugin"), dict) else {}
    return {
        "status": "configured" if is_configured else "default",
        "version": version,
        "updatedAt": str(raw.get("updatedAt") or ""),
        "visualStyle": visual,
        "variants": variants,
        "plugin": {
            "styleVersion": str(plugin.get("styleVersion") or (f"v{version}" if version else "default")),
            "status": str(plugin.get("status") or "unknown"),
            "installedVersion": str(plugin.get("installedVersion") or ""),
            "lastVerifiedAt": str(plugin.get("lastVerifiedAt") or ""),
            "warning": str(plugin.get("warning") or ""),
        },
    }


def _default_blog_format_standard(
    style_kit: Optional[dict[str, Any]] = None,
    bulk_format: Optional[dict[str, Any]] = None,
    *,
    source_url: str = "",
) -> dict[str, Any]:
    style = _normalize_site_style_kit(style_kit or {})
    bulk = _normalize_bulk_blog_format(bulk_format or {})
    visual = bulk["visualStyle"]
    values: dict[str, Any] = {
        **visual,
        "bodyFontFamily": style["typography"]["bodyFont"] or visual["bodyFontFamily"],
        "headingFontFamily": style["typography"]["headingFont"] or visual["headingFontFamily"],
        "bodyFontSizeDesktop": style["typography"]["desktop"]["body"],
        "bodyFontSizeMobile": style["typography"]["mobile"]["body"],
        "bodyLineHeight": style["typography"]["desktop"]["lineHeight"],
        "h2FontSizeDesktop": style["typography"]["desktop"]["h2"],
        "h2FontSizeMobile": style["typography"]["mobile"]["h2"],
        "h3FontSizeDesktop": style["typography"]["desktop"]["h3"],
        "h3FontSizeMobile": style["typography"]["mobile"]["h3"],
        "textColor": style["roles"]["text"],
        "linkColor": style["roles"]["link"],
        "ctaBg": style["roles"]["ctaBg"],
        "paragraphSpacing": 18,
        "tableCellPadding": 14,
    }
    return {
        "status": "default",
        "version": 0,
        "name": "站点博客标准",
        "updatedAt": "",
        "source": {
            "sourceUrl": source_url,
            "capturedAt": "",
            "confidence": "fallback",
            "evidence": ["站点品牌样式", "历史博客修复格式"],
        },
        "tokens": {
            key: {"mode": "inherit", "value": values[key]}
            for key in BLOG_FORMAT_STANDARD_TOKEN_KEYS
        },
    }


def _normalize_blog_format_standard(
    value: Any,
    *,
    style_kit: Optional[dict[str, Any]] = None,
    bulk_format: Optional[dict[str, Any]] = None,
    source_url: str = "",
) -> dict[str, Any]:
    defaults = _default_blog_format_standard(style_kit, bulk_format, source_url=source_url)
    raw = value if isinstance(value, dict) else {}
    raw_tokens = raw.get("tokens") if isinstance(raw.get("tokens"), dict) else {}
    tokens: dict[str, dict[str, Any]] = {}
    for key, fallback in defaults["tokens"].items():
        candidate = raw_tokens.get(key) if isinstance(raw_tokens.get(key), dict) else {}
        mode = "managed" if str(candidate.get("mode") or "") == "managed" else "inherit"
        value_candidate = candidate.get("value", fallback["value"])
        if isinstance(fallback["value"], (int, float)):
            value_candidate = _coerce_number(value_candidate, fallback["value"])
            if isinstance(fallback["value"], int):
                value_candidate = int(value_candidate)
        else:
            value_candidate = str(value_candidate or fallback["value"]).strip()[:180]
        tokens[key] = {"mode": mode, "value": value_candidate}
    source = raw.get("source") if isinstance(raw.get("source"), dict) else {}
    evidence = source.get("evidence") if isinstance(source.get("evidence"), list) else defaults["source"]["evidence"]
    status = str(raw.get("status") or "default")
    if status not in {"default", "draft", "configured"}:
        status = "default"
    return {
        "status": status,
        "version": max(0, int(_coerce_number(raw.get("version"), 0))),
        "name": str(raw.get("name") or defaults["name"]).strip()[:100],
        "updatedAt": str(raw.get("updatedAt") or ""),
        "source": {
            "sourceUrl": str(source.get("sourceUrl") or defaults["source"]["sourceUrl"]),
            "capturedAt": str(source.get("capturedAt") or defaults["source"]["capturedAt"]),
            "confidence": str(source.get("confidence") or defaults["source"]["confidence"]),
            "evidence": [str(item).strip() for item in evidence if str(item).strip()][:20],
        },
        "tokens": tokens,
    }


def _blog_format_standard_diagnosis(standard: dict[str, Any]) -> list[str]:
    tokens = standard["tokens"]
    body_size = int(tokens["bodyFontSizeDesktop"]["value"])
    line_height = float(tokens["bodyLineHeight"]["value"])
    h2_size = int(tokens["h2FontSizeDesktop"]["value"])
    findings = []
    findings.append("正文偏小，建议提高到 17-18px。" if body_size < 17 else "正文字号处于常用可读范围。")
    findings.append("正文行距偏紧，长文章可能显得拥挤。" if line_height < 1.6 else "正文行距适合长篇阅读。")
    findings.append("H2 与正文层级不够明显。" if h2_size < body_size * 1.55 else "H2 与正文层级清晰。")
    return findings


def _apply_blog_format_instruction(standard: dict[str, Any], message: str) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    draft = _normalize_blog_format_standard(standard)
    draft["status"] = "draft"
    text = str(message or "").strip().lower()
    changes: list[dict[str, Any]] = []

    def manage(key: str, value: Any, label: str) -> None:
        before = draft["tokens"][key]
        draft["tokens"][key] = {"mode": "managed", "value": value}
        changes.append({"token": key, "label": label, "before": before["value"], "after": value})

    if any(term in text for term in ("正文大", "字体大", "字号大", "larger body", "bigger body")):
        current = int(draft["tokens"]["bodyFontSizeDesktop"]["value"])
        manage("bodyFontSizeDesktop", min(22, max(18, current + 1)), "正文桌面字号")
        manage("bodyFontSizeMobile", 16, "正文移动字号")
    if any(term in text for term in ("标题不要太夸张", "标题收敛", "标题小", "smaller heading")):
        manage("h2FontSizeDesktop", 30, "H2 桌面字号")
        manage("h3FontSizeDesktop", 22, "H3 桌面字号")
    if any(term in text for term in ("行距", "松一点", "更好读", "易读", "readable")):
        manage("bodyLineHeight", 1.75, "正文行高")
        manage("paragraphSpacing", 18, "段落间距")
    if any(term in text for term in ("表格简洁", "表格简单", "light table", "simple table")):
        manage("tableHeaderBg", "#f3f4f6", "表头背景")
        manage("tableHeaderText", "#1f2937", "表头文字")
        manage("tableBorderColor", "#dbe3ea", "表格边框")
    if any(term in text for term in ("专业", "b2b", "professional")):
        if not any(item["token"] == "bodyLineHeight" for item in changes):
            manage("bodyLineHeight", 1.72, "正文行高")
        manage("contentMaxWidth", 820, "正文内容宽度")
    return draft, changes


def _blog_format_managed_value(standard: dict[str, Any], key: str) -> Any:
    token = (standard.get("tokens") or {}).get(key) if isinstance(standard.get("tokens"), dict) else None
    return token.get("value") if isinstance(token, dict) and token.get("mode") == "managed" else None


def _merge_html_style_attribute(attrs: str, declarations: list[str]) -> str:
    clean = [item.strip().rstrip(";") for item in declarations if str(item).strip()]
    if not clean:
        return attrs
    style_match = re.search(r'\sstyle=(["\'])(.*?)\1', attrs, flags=re.I | re.S)
    if style_match:
        existing = style_match.group(2).strip().rstrip(";")
        merged = ";".join([item for item in [existing, *clean] if item])
        return attrs[:style_match.start()] + f' style="{merged}"' + attrs[style_match.end():]
    return f'{attrs} style="{";".join(clean)}"'


def _merge_wp_block_typography(comment_json: str, typography: dict[str, str]) -> str:
    try:
        attrs = json.loads(comment_json) if comment_json.strip() else {}
    except json.JSONDecodeError:
        attrs = {}
    style = attrs.get("style") if isinstance(attrs.get("style"), dict) else {}
    current_typography = style.get("typography") if isinstance(style.get("typography"), dict) else {}
    attrs["style"] = {**style, "typography": {**current_typography, **typography}}
    return json.dumps(attrs, ensure_ascii=False, separators=(",", ":"))


def _apply_blog_format_standard_to_html(html: str, standard: dict[str, Any]) -> tuple[str, list[str]]:
    normalized = _normalize_blog_format_standard(standard)
    source = str(html or "")
    changed_tokens: list[str] = []

    paragraph_typography: dict[str, str] = {}
    paragraph_css: list[str] = []
    body_size = _blog_format_managed_value(normalized, "bodyFontSizeDesktop")
    if body_size is not None:
        paragraph_typography["fontSize"] = f"{int(body_size)}px"
        paragraph_css.append(f"font-size:{int(body_size)}px")
        changed_tokens.append("bodyFontSizeDesktop")
    body_line_height = _blog_format_managed_value(normalized, "bodyLineHeight")
    if body_line_height is not None:
        line_height = f"{float(body_line_height):g}"
        paragraph_typography["lineHeight"] = line_height
        paragraph_css.append(f"line-height:{line_height}")
        changed_tokens.append("bodyLineHeight")
    body_font = _blog_format_managed_value(normalized, "bodyFontFamily")
    if body_font is not None:
        clean_font = _bulk_blog_css_font(body_font, "Arial, sans-serif")
        paragraph_typography["fontFamily"] = clean_font
        paragraph_css.append(f"font-family:{clean_font}")
        changed_tokens.append("bodyFontFamily")

    if paragraph_typography:
        paragraph_pattern = re.compile(
            r'<!--\s*wp:paragraph(?:\s+(?P<json>\{.*?\}))?\s*-->\s*<p(?P<attrs>[^>]*)>',
            flags=re.I | re.S,
        )

        def replace_paragraph(match: re.Match[str]) -> str:
            block_json = _merge_wp_block_typography(match.group("json") or "", paragraph_typography)
            tag_attrs = _merge_html_style_attribute(match.group("attrs") or "", paragraph_css)
            return f'<!-- wp:paragraph {block_json} -->\n<p{tag_attrs}>'

        source = paragraph_pattern.sub(replace_paragraph, source)

    heading_font = _blog_format_managed_value(normalized, "headingFontFamily")
    heading_pattern = re.compile(
        r'<!--\s*wp:heading(?:\s+(?P<json>\{.*?\}))?\s*-->\s*<h(?P<level>[23])(?P<attrs>[^>]*)>',
        flags=re.I | re.S,
    )

    def replace_heading(match: re.Match[str]) -> str:
        level = match.group("level")
        size_key = "h2FontSizeDesktop" if level == "2" else "h3FontSizeDesktop"
        size = _blog_format_managed_value(normalized, size_key)
        typography: dict[str, str] = {}
        css: list[str] = []
        if size is not None:
            typography["fontSize"] = f"{int(size)}px"
            css.append(f"font-size:{int(size)}px")
            changed_tokens.append(size_key)
        if heading_font is not None:
            clean_font = _bulk_blog_css_font(heading_font, "Arial, sans-serif")
            typography["fontFamily"] = clean_font
            css.append(f"font-family:{clean_font}")
            if "headingFontFamily" not in changed_tokens:
                changed_tokens.append("headingFontFamily")
        if not typography:
            return match.group(0)
        block_json = _merge_wp_block_typography(match.group("json") or "", typography)
        tag_attrs = _merge_html_style_attribute(match.group("attrs") or "", css)
        return f'<!-- wp:heading {block_json} -->\n<h{level}{tag_attrs}>'

    source = heading_pattern.sub(replace_heading, source)
    return source, list(dict.fromkeys(changed_tokens))


def _normalize_client_profile(profile: dict[str, Any], fallback_id: str = "default") -> dict[str, Any]:
    profile_id = _profile_slug(str(profile.get("id") or fallback_id), fallback_id)
    settings = dict(profile.get("settings") or {})
    site_url = str(profile.get("siteUrl") or settings.get("wpUrl") or "").strip()
    raw_site_name = str(profile.get("siteName") or "").strip()
    raw_name = str(profile.get("name") or "").strip()
    if not raw_name or raw_name == "Default Customer":
        raw_name = raw_site_name or _site_name_from_url(site_url) or "默认站点"
    settings = dict(profile.get("settings") or {})
    secrets_map = {str(k): str(v) for k, v in dict(profile.get("secrets") or {}).items() if str(v)}
    knowledge_sources = [
        normalized
        for normalized in (_normalize_profile_knowledge_source(row) for row in profile.get("knowledgeSources") or [])
        if normalized
    ]
    template_pack = _normalize_template_pack(profile.get("templatePack") or {})
    framework_standard = _normalize_blog_framework_standard(
        profile.get("blogFrameworkStandard") or {},
        legacy_frameworks=profile.get("blogFrameworks") or [],
        template_pack=template_pack,
    )
    return {
        "id": profile_id,
        "name": raw_name,
        "siteName": raw_site_name or raw_name,
        "siteUrl": site_url,
        "brandName": str(profile.get("brandName") or "").strip(),
        "settings": {key: value for key, value in settings.items() if key in SettingsPayload.model_fields},
        "secrets": {key: value for key, value in secrets_map.items() if key in SECRET_SETTING_KEYS},
        "knowledgeSources": knowledge_sources,
        "knowledgeArtifacts": _normalize_profile_knowledge_artifacts(profile.get("knowledgeArtifacts") or []),
        "templatePack": template_pack,
        "styleKit": _normalize_site_style_kit(profile.get("styleKit") or {}),
        "blogFrameworks": framework_standard["frameworks"],
        "blogFrameworkStandard": framework_standard,
        "bulkBlogFormat": _normalize_bulk_blog_format(profile.get("bulkBlogFormat") or {}),
        "blogFormatStandard": _normalize_blog_format_standard(
            profile.get("blogFormatStandard") or {},
            style_kit=profile.get("styleKit") or {},
            bulk_format=profile.get("bulkBlogFormat") or {},
            source_url=site_url,
        ),
        "faqs": _normalize_faqs(profile.get("faqs") or []),
        "internalLinkSettings": _normalize_internal_link_settings(profile.get("internalLinkSettings") or {}),
        "rulePack": _normalize_rule_pack(profile.get("rulePack") or {}),
        "generationSessions": _normalize_profile_generation_sessions(profile.get("generationSessions") or []),
        "skillPacks": _normalize_profile_skill_packs(profile.get("skillPacks") or [], profile),
        "activeSkillPackId": str(profile.get("activeSkillPackId") or "").strip(),
        "createdAt": str(profile.get("createdAt") or _utc_now_iso()),
        "updatedAt": str(profile.get("updatedAt") or _utc_now_iso()),
    }


def _default_profile_from_settings(settings: dict[str, Any]) -> dict[str, Any]:
    public_settings, secrets_map = _split_profile_settings(settings)
    site_url = str(settings.get("wpUrl") or "").strip()
    site_name = _site_name_from_url(site_url) or "默认站点"
    return _normalize_client_profile({
        "id": "default",
        "name": site_name,
        "siteName": site_name,
        "siteUrl": site_url,
        "brandName": "",
        "settings": public_settings,
        "secrets": secrets_map,
        "knowledgeSources": [],
        "knowledgeArtifacts": [],
        "templatePack": {},
        "rulePack": {},
        "generationSessions": [],
        "skillPacks": [],
        "activeSkillPackId": "",
        "createdAt": _utc_now_iso(),
        "updatedAt": _utc_now_iso(),
    })


def _read_client_profile_store_raw() -> dict[str, Any]:
    if not CLIENT_PROFILES_FILE.exists():
        return {}
    try:
        data = json.loads(CLIENT_PROFILES_FILE.read_text(encoding="utf-8"))
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def _client_profile_store_payload(data: dict[str, Any]) -> dict[str, Any]:
    active_value = data.get("activeProfileId") if "activeProfileId" in data else data.get("activeSiteId")
    active_id = str(active_value or "").strip()
    profiles = data.get("profiles") if "profiles" in data else data.get("sites")
    return {
        # Kept as an empty compatibility object for clients from before site-scoped
        # identity. UI identity now comes only from the active site.
        "company": {"name": ""},
        "activeSiteId": active_id,
        "sites": profiles,
    }


def _write_client_profile_store(data: dict[str, Any]) -> dict[str, Any]:
    CLIENT_PROFILES_FILE.parent.mkdir(parents=True, exist_ok=True)
    temporary_file = CLIENT_PROFILES_FILE.with_name(f".{CLIENT_PROFILES_FILE.name}.{uuid.uuid4().hex}.tmp")
    temporary_file.write_text(
        json.dumps(_client_profile_store_payload(data), ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    temporary_file.replace(CLIENT_PROFILES_FILE)
    data["company"] = {"name": ""}
    return data


def _load_client_profile_store(create: bool = True) -> dict[str, Any]:
    raw = _read_client_profile_store_raw()
    has_explicit_profile_collection = isinstance(raw, dict) and ("sites" in raw or "profiles" in raw)
    raw_profiles = (raw.get("sites") or raw.get("profiles")) if isinstance(raw, dict) else []
    profiles = [
        profile
        for profile in (
            _normalize_client_profile(row, fallback_id=f"profile-{index + 1}")
            for index, row in enumerate(raw_profiles or [])
            if isinstance(row, dict)
        )
        if profile
    ]
    active_id = str(raw.get("activeSiteId") or raw.get("activeProfileId") or "").strip()
    company = {"name": ""}

    if not profiles and create and not has_explicit_profile_collection:
        profiles = [_default_profile_from_settings(_read_settings())]
        active_id = "default"

    ids = {profile["id"] for profile in profiles}
    if active_id not in ids and profiles:
        active_id = profiles[0]["id"]
    store = {
        "company": company,
        "activeProfileId": active_id,
        "profiles": profiles,
        "activeSiteId": active_id,
        "sites": profiles,
    }
    if create and _client_profile_store_payload(store) != raw:
        _write_client_profile_store(store)
    return store


def _client_profile_public(profile: dict[str, Any], active_id: str) -> dict[str, Any]:
    secrets_map = dict(profile.get("secrets") or {})
    framework_standard = _normalize_blog_framework_standard(
        profile.get("blogFrameworkStandard") or {},
        legacy_frameworks=profile.get("blogFrameworks") or [],
        template_pack=profile.get("templatePack") or {},
    )
    return {
        "id": profile["id"],
        "name": profile["name"],
        "siteName": _display_site_name(profile),
        "siteUrl": profile.get("siteUrl", ""),
        "brandName": profile.get("brandName", ""),
        "active": profile["id"] == active_id,
        "settings": dict(profile.get("settings") or {}),
        "secretRefs": {key: bool(secrets_map.get(key)) for key in SECRET_SETTING_KEYS},
        "knowledgeSources": [_profile_knowledge_public(source) for source in _profile_knowledge_sources(profile)],
        "knowledgeArtifacts": [_knowledge_artifact_public(artifact) for artifact in profile.get("knowledgeArtifacts") or []],
        "templatePack": dict(profile.get("templatePack") or {}),
        "styleKit": _normalize_site_style_kit(profile.get("styleKit") or {}),
        "blogFrameworks": framework_standard["frameworks"],
        "blogFrameworkStandard": framework_standard,
        "bulkBlogFormat": _normalize_bulk_blog_format(profile.get("bulkBlogFormat") or {}),
        "blogFormatStandard": _normalize_blog_format_standard(
            profile.get("blogFormatStandard") or {},
            style_kit=profile.get("styleKit") or {},
            bulk_format=profile.get("bulkBlogFormat") or {},
            source_url=str(profile.get("siteUrl") or ""),
        ),
        "faqs": _normalize_faqs(profile.get("faqs") or []),
        "internalLinkSettings": _normalize_internal_link_settings(profile.get("internalLinkSettings") or {}),
        "rulePack": _rule_pack_public(profile.get("rulePack") or {}),
        "generationSessions": [_generation_session_public(session) for session in profile.get("generationSessions") or []],
        "skillPacks": [_skill_pack_public(pack) for pack in profile.get("skillPacks") or []],
        "activeSkillPackId": profile.get("activeSkillPackId", ""),
        "createdAt": profile.get("createdAt", ""),
        "updatedAt": profile.get("updatedAt", ""),
    }


def _load_client_profiles() -> dict[str, Any]:
    store = _load_client_profile_store(create=True)
    active_id = store.get("activeProfileId", "")
    return {
        "activeProfileId": active_id,
        "profiles": [_client_profile_public(profile, active_id) for profile in store.get("profiles") or []],
    }


def _site_profile_public(profile: dict[str, Any], active_id: str) -> dict[str, Any]:
    payload = _client_profile_public(profile, active_id)
    payload["siteName"] = _display_site_name(profile)
    return payload


def _site_profile_summary_public(profile: dict[str, Any], active_id: str) -> dict[str, Any]:
    secrets_map = dict(profile.get("secrets") or {})
    return {
        "id": profile["id"],
        "name": profile["name"],
        "siteName": _display_site_name(profile),
        "siteUrl": profile.get("siteUrl", ""),
        "brandName": profile.get("brandName", ""),
        "active": profile["id"] == active_id,
        "settings": dict(profile.get("settings") or {}),
        "secretRefs": {key: bool(secrets_map.get(key)) for key in SECRET_SETTING_KEYS},
        "activeSkillPackId": profile.get("activeSkillPackId", ""),
        "createdAt": profile.get("createdAt", ""),
        "updatedAt": profile.get("updatedAt", ""),
        "counts": {
            "knowledgeSources": len(profile.get("knowledgeSources") or []),
            "knowledgeArtifacts": len(profile.get("knowledgeArtifacts") or []),
            "generationSessions": len(profile.get("generationSessions") or []),
            "skillPacks": len(profile.get("skillPacks") or []),
            "faqs": len(profile.get("faqs") or []),
        },
    }


def _load_site_profiles() -> dict[str, Any]:
    store = _load_client_profile_store(create=True)
    active_id = str(store.get("activeProfileId") or "")
    return {
        "company": _normalize_company_profile(store.get("company")),
        "activeSiteId": active_id,
        "sites": [_site_profile_public(profile, active_id) for profile in store.get("profiles") or []],
    }


def _load_site_profile_summaries() -> dict[str, Any]:
    store = _load_client_profile_store(create=True)
    active_id = str(store.get("activeProfileId") or "")
    return {
        "company": _normalize_company_profile(store.get("company")),
        "activeSiteId": active_id,
        "sites": [_site_profile_summary_public(profile, active_id) for profile in store.get("profiles") or []],
    }


def _find_client_profile(store: dict[str, Any], profile_id: str) -> dict[str, Any]:
    clean_id = _profile_slug(profile_id)
    for profile in store.get("profiles") or []:
        if profile.get("id") == clean_id:
            return profile
    raise HTTPException(status_code=404, detail=f"Client profile not found: {profile_id}")


def _active_client_profile(store: Optional[dict[str, Any]] = None) -> dict[str, Any]:
    data = store or _load_client_profile_store(create=True)
    return _find_client_profile(data, str(data.get("activeProfileId") or ""))


def _resolve_request_generation_context(
    *,
    site_id: str,
    task_type: str,
    core_keyword: str = "",
    keyword_category: str = "",
    target_text: str = "",
    selected_fields: Iterable[str] = (),
    legacy_keyword_context: str = "",
    legacy_company_context: str = "",
) -> dict[str, Any]:
    """Resolve new site references while keeping historical queued payloads readable."""
    clean_site_id = str(site_id or "").strip()
    if clean_site_id:
        store = _load_client_profile_store(create=True)
        profile = _find_client_profile(store, clean_site_id)
        return generation_context.resolve_generation_context(
            profile,
            task_type=task_type,
            core_keyword=core_keyword,
            keyword_category=keyword_category,
            target_text=target_text,
            selected_fields=selected_fields,
        )
    return {
        "siteId": "",
        "taskType": task_type,
        "coreKeyword": str(core_keyword or "").strip(),
        "keywordCategory": str(keyword_category or "").strip(),
        "keywordContext": str(legacy_keyword_context or "").strip(),
        "companyContext": str(legacy_company_context or "").strip(),
        "supportingKeywords": knowledge_plan.extract_keyword_candidates(legacy_keyword_context)[:12],
        "templateValues": {},
        "summary": {
            "coreKeyword": str(core_keyword or "").strip(),
            "keywordCategory": str(keyword_category or "").strip(),
            "supportingKeywords": knowledge_plan.extract_keyword_candidates(legacy_keyword_context)[:12],
            "sourceArtifacts": [],
            "appliedRules": [],
            "appliedTemplates": [],
            "usedKeywords": [],
            "warnings": [],
        },
    }


def _generation_summary_with_usage(context: dict[str, Any], usage: Optional[dict[str, Any]] = None) -> dict[str, Any]:
    summary = dict(context.get("summary") or {})
    usage = usage if isinstance(usage, dict) else {}
    summary["usedKeywords"] = list(usage.get("usedKeywords") or [])
    summary["warnings"] = list(dict.fromkeys([
        *list(summary.get("warnings") or []),
        *list(usage.get("warnings") or []),
    ]))
    return summary


def _decrypt_profile_settings(profile: dict[str, Any]) -> dict[str, Any]:
    settings = dict(profile.get("settings") or {})
    for field, encrypted in dict(profile.get("secrets") or {}).items():
        if field in SECRET_SETTING_KEYS and isinstance(encrypted, str):
            for key in _profile_secret_key_candidates():
                try:
                    settings[field] = _decrypt_secret_text(encrypted, key)
                    break
                except HTTPException:
                    continue
            else:
                settings[field] = ""
    return settings


def _settings_for_client_profile(profile: dict[str, Any]) -> dict[str, Any]:
    global_settings = _read_settings()
    global_settings_for_profile = {
        key: value
        for key, value in global_settings.items()
        if key in GLOBAL_SETTING_KEYS
    }
    profile_settings = _decrypt_profile_settings(profile)
    legacy_global_from_profile = {
        key: value
        for key, value in profile_settings.items()
        if key in GLOBAL_SETTING_KEYS and str(value or "").strip() and not str(global_settings.get(key) or "").strip()
    }
    site_settings = {key: value for key, value in profile_settings.items() if key in SITE_SCOPED_SETTING_KEYS}
    return {**global_settings_for_profile, **legacy_global_from_profile, **site_settings}


def _client_profile_settings_by_id(site_id: str) -> dict[str, Any]:
    clean_id = str(site_id or "").strip()
    if not clean_id:
        raise HTTPException(status_code=400, detail="siteId is required")
    store = _load_client_profile_store(create=True)
    profile = _find_client_profile(store, clean_id)
    return _settings_for_client_profile(profile)


def _active_client_profile_settings() -> Optional[dict[str, Any]]:
    if not CLIENT_PROFILES_FILE.exists():
        return None
    store = _load_client_profile_store(create=False)
    if not store.get("profiles"):
        return None
    return _settings_for_client_profile(_active_client_profile(store))


def _effective_settings() -> dict[str, Any]:
    return _active_client_profile_settings() or _read_settings()


def _save_active_client_profile_settings(settings: dict[str, Any]) -> Optional[dict[str, Any]]:
    if not CLIENT_PROFILES_FILE.exists():
        return None
    store = _load_client_profile_store(create=False)
    global_updates = {
        key: value
        for key, value in dict(settings or {}).items()
        if key in GLOBAL_SETTING_KEYS
    }
    if global_updates:
        current_global = _read_settings()
        _write_settings({**current_global, **global_updates})
    if not store.get("profiles"):
        return _read_settings()
    profile = _active_client_profile(store)
    _merge_profile_settings(profile, settings)
    profile["siteUrl"] = str(profile.get("siteUrl") or settings.get("wpUrl") or "").strip()
    profile["updatedAt"] = _utc_now_iso()
    _write_client_profile_store(store)
    return _active_client_profile_settings()


def _settings_secret_refs(settings: dict[str, Any]) -> dict[str, bool]:
    return {
        key: bool(str(settings.get(key) or "").strip())
        for key in SECRET_SETTING_KEYS
    }


def _public_settings_payload(settings: dict[str, Any]) -> dict[str, Any]:
    payload = SettingsPayload(**settings).model_dump()
    for key in SECRET_SETTING_KEYS:
        payload[key] = ""
    payload["secretRefs"] = _settings_secret_refs(settings)
    return payload


def _active_profile_template_pack() -> dict[str, str]:
    if not CLIENT_PROFILES_FILE.exists():
        return {}
    try:
        store = _load_client_profile_store(create=False)
        if not store.get("profiles"):
            return {}
        return dict(_active_client_profile(store).get("templatePack") or {})
    except HTTPException:
        return {}


def _active_profile_knowledge_context_text() -> str:
    if not CLIENT_PROFILES_FILE.exists():
        return ""
    try:
        store = _load_client_profile_store(create=False)
        if not store.get("profiles"):
            return ""
        profile = _active_client_profile(store)
    except HTTPException:
        return ""
    blocks: list[str] = []
    total = 0
    for source in _profile_knowledge_sources(profile):
        if not source.get("enabled", True):
            continue
        path = _profile_source_text_path(profile, source)
        if not path.exists():
            continue
        try:
            text = path.read_text(encoding="utf-8")
        except Exception:
            continue
        remaining = MAX_CUSTOM_KNOWLEDGE_CONTEXT_CHARS - total
        if remaining <= 0:
            break
        clipped = text[:remaining]
        total += len(clipped)
        label = source.get("label") or source["filename"]
        source_type = source.get("sourceType") or "general"
        blocks.append(f"## {label} ({source_type})\n\n{clipped}")
    if not blocks:
        return ""
    return "# 当前站点知识库\n\n" + "\n\n---\n\n".join(blocks)


def _active_profile_keyword_context_text() -> str:
    if not CLIENT_PROFILES_FILE.exists():
        return ""
    try:
        store = _load_client_profile_store(create=False)
        if not store.get("profiles"):
            return ""
        profile = _active_client_profile(store)
    except HTTPException:
        return ""
    blocks: list[str] = []
    total = 0
    for source in _profile_knowledge_sources(profile):
        source_type = str(source.get("sourceType") or "").lower()
        if "keyword" not in source_type and "关键词" not in str(source.get("label") or ""):
            continue
        path = _profile_source_text_path(profile, source)
        if not path.exists():
            continue
        try:
            text = path.read_text(encoding="utf-8")
        except Exception:
            continue
        remaining = MAX_CUSTOM_KNOWLEDGE_CONTEXT_CHARS - total
        if remaining <= 0:
            break
        clipped = text[:remaining]
        total += len(clipped)
        blocks.append(f"## {source.get('label') or source['filename']}\n\n{clipped}")
    if not blocks:
        return ""
    return "# 当前站点关键词库\n\n" + "\n\n---\n\n".join(blocks)


def _profile_product_template_text(template_pack: dict[str, str]) -> str:
    short_template = str(template_pack.get("productShortDescription") or "").strip()
    full_template = str(template_pack.get("productFullDescription") or "").strip()
    tag_names = str(template_pack.get("tagNames") or "").strip()
    if not any([short_template, full_template, tag_names]):
        return ""
    sections = ["Client profile template pack:"]
    if short_template:
        sections.append(f"Short description structure and examples:\n{short_template}")
    if full_template:
        sections.append(f"Full description structure and examples:\n{full_template}")
    if tag_names:
        sections.append(f"WooCommerce product tag structure and examples:\n{tag_names}")
    return "\n\n".join(sections)


def _read_profile_source_text(profile: dict[str, Any], source: dict[str, Any], max_chars: int = 20000) -> str:
    path = _profile_source_text_path(profile, source)
    if not path.exists():
        return ""
    try:
        return path.read_text(encoding="utf-8")[:max_chars].strip()
    except Exception:
        return ""


def _read_or_restore_profile_source_text(
    store: dict[str, Any],
    profile: dict[str, Any],
    source: dict[str, Any],
    *,
    max_chars: int,
) -> str:
    text = _read_profile_source_text(profile, source, max_chars=max_chars)
    if text:
        return text

    stored_name = str(source.get("storedName") or "").strip()
    if not stored_name or stored_name.startswith(LEGACY_SKILLS_STORED_PREFIX):
        return ""
    filename = str(source.get("filename") or stored_name)
    extension = Path(filename).suffix.lower()
    if extension not in SUPPORTED_KNOWLEDGE_EXTENSIONS or extension == ".pdf":
        return ""
    original_path = _profile_source_original_path(profile, source)
    if not original_path.exists() or not original_path.is_file():
        return ""

    restored_text = _decode_knowledge_file(filename, original_path.read_bytes()).strip()
    if not restored_text:
        return ""
    text_stored_name = Path(str(source.get("textStoredName") or f"{source['id']}.txt")).name
    text_path = _site_knowledge_path(profile["id"]) / text_stored_name
    text_path.parent.mkdir(parents=True, exist_ok=True)
    text_path.write_text(restored_text, encoding="utf-8")
    source["textStoredName"] = text_stored_name
    source["chars"] = len(restored_text)
    profile["knowledgeSources"] = [
        source if str(item.get("id") or "") == str(source.get("id") or "") else item
        for item in profile.get("knowledgeSources") or []
    ]
    profile["updatedAt"] = _utc_now_iso()
    _write_client_profile_store(store)
    return restored_text[:max_chars]


def _profile_sources_by_skill_bucket(profile: dict[str, Any]) -> dict[str, list[dict[str, Any]]]:
    grouped: dict[str, list[dict[str, Any]]] = {
        "company": [],
        "product": [],
        "keyword": [],
        "general": [],
    }
    for source in _profile_knowledge_sources(profile):
        if not source.get("enabled", True):
            continue
        text = _read_profile_source_text(profile, source)
        if not text:
            continue
        public = _profile_knowledge_public(source)
        public["text"] = text
        grouped.setdefault(_skill_source_bucket(source.get("sourceType", "")), []).append(public)
    return grouped


def _format_skill_source_group(title: str, sources: list[dict[str, Any]]) -> str:
    if not sources:
        return f"{title}\n(no uploaded sources)"
    blocks = [title]
    for source in sources:
        blocks.append(
            f"## {source.get('label') or source.get('filename')} "
            f"({source.get('sourceType') or 'general'}, {source.get('filename')})\n"
            f"{source.get('text') or ''}"
        )
    return "\n\n".join(blocks)


def _build_client_skill_pack_prompt(profile: dict[str, Any], grouped: dict[str, list[dict[str, Any]]]) -> str:
    return f"""
You are building a reusable Gemini Skill Pack for an SEO and WordPress operations app.

Customer workspace:
- Client name: {profile.get('name') or ''}
- Site URL: {profile.get('siteUrl') or ''}
- Brand name: {profile.get('brandName') or ''}

Separate the uploaded materials carefully:
- Company information controls brand identity, verified company facts, allowed claims, and forbidden claims.
- Product information controls product facts, models, categories, specifications, use cases, and audience questions.
- Product keywords control SEO language only. Do not treat keywords as product facts or company capabilities.

Return ONLY valid JSON with this exact top-level shape:
{{
  "companySkill": {{
    "summary": "short customer/company summary",
    "brandVoice": "writing tone and positioning",
    "allowedClaims": ["verified claim"],
    "forbiddenClaims": ["unsupported claim to avoid"]
  }},
  "productSkill": {{
    "categories": ["category name"],
    "models": ["model code"],
    "factRules": "rules for grounding product copy in product sources"
  }},
  "keywordSkill": {{
    "libraries": [{{"name": "library name", "keywords": ["keyword"]}}],
    "priorityRules": "how to use core, long-tail, and scenario keywords",
    "excludedTerms": ["term to avoid"]
  }},
  "taskSkills": {{
    "blog": "blog writing rules",
    "productPage": "product page rules",
    "imageSeo": "image SEO rules",
    "pagePlanner": "page planning rules",
    "seoAuditRepair": "SEO audit repair rules"
  }}
}}

{_format_skill_source_group('COMPANY INFORMATION SOURCES', grouped.get('company', []))}

{_format_skill_source_group('PRODUCT INFORMATION SOURCES', grouped.get('product', []))}

{_format_skill_source_group('PRODUCT KEYWORD SOURCES', grouped.get('keyword', []))}

{_format_skill_source_group('GENERAL SUPPORTING SOURCES', grouped.get('general', []))}
""".strip()


def _source_file_summaries(grouped: dict[str, list[dict[str, Any]]]) -> list[dict[str, Any]]:
    summaries: list[dict[str, Any]] = []
    for source_group in grouped.values():
        for source in source_group:
            item = {key: value for key, value in source.items() if key != "text"}
            summaries.append(item)
    return summaries


def _skill_pack_from_ai_payload(profile: dict[str, Any], payload: dict[str, Any], grouped: dict[str, list[dict[str, Any]]]) -> dict[str, Any]:
    return _normalize_skill_pack({
        "id": uuid.uuid4().hex,
        "clientName": profile.get("name", ""),
        "siteUrl": profile.get("siteUrl", ""),
        "status": "draft",
        "version": 0,
        "companySkill": payload.get("companySkill") if isinstance(payload, dict) else {},
        "productSkill": payload.get("productSkill") if isinstance(payload, dict) else {},
        "keywordSkill": payload.get("keywordSkill") if isinstance(payload, dict) else {},
        "taskSkills": payload.get("taskSkills") if isinstance(payload, dict) else {},
        "sourceFiles": _source_file_summaries(grouped),
        "createdAt": _utc_now_iso(),
        "updatedAt": _utc_now_iso(),
    }, profile)


def _generate_client_skill_pack(profile: dict[str, Any]) -> dict[str, Any]:
    grouped = _profile_sources_by_skill_bucket(profile)
    if not any(grouped.values()):
        raise HTTPException(status_code=400, detail="Upload customer company, product, or keyword sources before generating a Skill Pack.")
    if not _ai_configured():
        raise HTTPException(status_code=400, detail=_ai_missing_detail())
    prompt = _build_client_skill_pack_prompt(profile, grouped)
    raw = _gemini_generate_text(_get_gemini_api_key(), prompt, _ai_pro_model(), timeout=180)
    payload = _parse_ai_json_object(raw)
    if not isinstance(payload, dict):
        raise HTTPException(status_code=502, detail="AI did not return a valid Skill Pack JSON object")
    return _skill_pack_from_ai_payload(profile, payload, grouped)


def _path_string(path: Path) -> str:
    return str(path.expanduser())


def _desktop_paths_payload() -> dict[str, str]:
    database_path = DB_PATH.legacy_path if isinstance(DB_PATH, _SiteScopedFile) else DB_PATH
    return {
        "dataDir": _path_string(USER_DATA_DIR),
        "settingsFile": _path_string(SETTINGS_FILE),
        "database": _path_string(database_path),
        "logsDir": _path_string(LOG_DIR),
        "cacheOriginalDir": _path_string(CACHE_ORIGINAL_DIR),
        "cacheOptimizedDir": _path_string(CACHE_OPTIMIZED_DIR),
    }


def _read_package_version() -> str:
    env_version = os.getenv("SEO_WP_SYNC_APP_VERSION", "").strip()
    if env_version:
        return env_version
    package_json = PROJECT_ROOT / "package.json"
    try:
        data = json.loads(package_json.read_text(encoding="utf-8"))
    except Exception:
        return "0.0.0"
    version = str(data.get("version", "")).strip()
    return version or "0.0.0"


def _desktop_version_payload() -> dict[str, Any]:
    app_version = _read_package_version()
    node_cli_path = COMPILED_NODE_CLI
    return {
        "appName": APP_NAME,
        "appVersion": app_version,
        "backendVersion": app_version,
        "nodeCli": {
            "path": _path_string(node_cli_path),
            "exists": node_cli_path.exists(),
            "runtime": os.getenv("SEO_WP_SYNC_NODE_RUNTIME", "node").strip() or "node",
        },
    }


def _desktop_license_payload() -> dict[str, str]:
    status = os.getenv("SEO_WP_SYNC_LICENSE_STATUS", "").strip().lower() or "unlicensed"
    if status not in {"active", "inactive", "unlicensed", "expired", "blocked"}:
        status = "unlicensed"
    return {"status": status}


