@app.put("/settings")
def save_settings(payload: SettingsPayload):
    existing = _effective_settings()
    updates = payload.model_dump(exclude_unset=True)
    for field in SECRET_SETTING_KEYS:
        if (
            field in updates
            and not str(updates.get(field) or "").strip()
            and str(existing.get(field) or "").strip()
        ):
            updates.pop(field, None)
    data = {**existing, **updates}
    allowed_keys = set(SettingsPayload.model_fields.keys())
    data = {key: value for key, value in data.items() if key in allowed_keys}
    data["sftpPort"] = _settings_int(data.get("sftpPort", 22), 22)
    data["useProxy"] = _settings_bool(data.get("useProxy", True), True)
    data["aiProvider"] = _settings_ai_provider(data.get("aiProvider", "gemini"))
    data["backendUrl"] = _settings_backend_url(data.get("backendUrl", ""))
    data["productAutoScanEnabled"] = _settings_bool(data.get("productAutoScanEnabled", False), False)
    data["productAutoScanStaleDays"] = _settings_clamped_int(data.get("productAutoScanStaleDays", 7), 7, 1, 365)
    data["productAutoScanCheckMinutes"] = _settings_clamped_int(data.get("productAutoScanCheckMinutes", 60), 60, 5, 1440)
    data["seoHealthAutoScanEnabled"] = _settings_bool(data.get("seoHealthAutoScanEnabled", True), True)
    data["seoHealthAutoScanTime"] = _settings_hhmm(data.get("seoHealthAutoScanTime", "18:00"), "18:00")
    data["seoHealthAutoScanTimezone"] = _settings_timezone(
        data.get("seoHealthAutoScanTimezone", "Asia/Shanghai"),
        "Asia/Shanghai",
    )
    saved = _save_active_client_profile_settings(data)
    if saved is None:
        saved = _write_settings(data)
    return {"ok": True, "settings": {**_public_settings_payload(saved), **_seo_health_auto_scan_status_fields()}}


