def _create_client_profile(payload: ClientProfilePayload, *, activate_new: bool = False):
    store = _load_client_profile_store(create=True)
    existing_ids = {profile["id"] for profile in store.get("profiles") or []}
    requested_id = _profile_slug(payload.id or payload.siteName or payload.name or payload.siteUrl or "site")
    profile_id = _unique_profile_id(requested_id, existing_ids)
    requested_settings = dict(payload.settings or {})
    if not existing_ids:
        legacy_settings = {
            key: value
            for key, value in _read_settings().items()
            if key in SITE_SCOPED_SETTING_KEYS
        }
        requested_settings = {
            **legacy_settings,
            **{
                key: value
                for key, value in requested_settings.items()
                if not (
                    isinstance(value, str)
                    and not value.strip()
                    and str(legacy_settings.get(key) or "").strip()
                )
            },
        }
    public_settings, secrets_map = _split_profile_settings(requested_settings)
    site_name = (payload.siteName or payload.name or "").strip()
    site_url = payload.siteUrl.strip() or str(public_settings.get("wpUrl") or "").strip()
    if payload.siteUrl.strip():
        public_settings["wpUrl"] = payload.siteUrl.strip()
        public_settings["gscSiteUrl"] = payload.siteUrl.strip()
    profile = _normalize_client_profile({
        "id": profile_id,
        "name": site_name or _site_name_from_url(site_url) or profile_id,
        "siteName": site_name,
        "siteUrl": site_url,
        "brandName": payload.brandName.strip(),
        "settings": public_settings,
        "secrets": secrets_map,
        "knowledgeSources": [],
        "templatePack": _normalize_template_pack(payload.templatePack or {}),
        "createdAt": _utc_now_iso(),
        "updatedAt": _utc_now_iso(),
    })
    store.setdefault("profiles", []).append(profile)
    if activate_new or not store.get("activeProfileId"):
        store["activeProfileId"] = profile_id
        store["activeSiteId"] = profile_id
    _write_client_profile_store(store)
    return {"ok": True, "profile": _client_profile_public(profile, str(store.get("activeProfileId") or ""))}


