    store = _load_client_profile_store(create=True)
    profile = _find_client_profile(store, profile_id)
    site_name = (payload.siteName or payload.name or "").strip()
    if site_name:
        profile["name"] = site_name
        profile["siteName"] = site_name
    if payload.siteUrl.strip():
        profile["siteUrl"] = payload.siteUrl.strip()
    if payload.brandName.strip():
        profile["brandName"] = payload.brandName.strip()
    if payload.settings:
        _merge_profile_settings(profile, payload.settings)
    if payload.templatePack:
        template_pack = dict(profile.get("templatePack") or {})
        template_pack.update(_normalize_template_pack(payload.templatePack))
        profile["templatePack"] = template_pack
    profile["updatedAt"] = _utc_now_iso()
    _write_client_profile_store(store)
    return {"ok": True, "profile": _client_profile_public(profile, str(store.get("activeProfileId") or ""))}


