@app.post("/client-profiles/{profile_id}/templates/generate-draft-with-assets")
async def generate_client_profile_template_draft_with_assets(
    profile_id: str,
    templateKey: str = Form("productShortDescription"),
    currentTemplate: str = Form(""),
    feedback: str = Form(""),
    files: list[UploadFile] = File(default=[]),
):
    store = _load_client_profile_store(create=True)
    profile = _find_client_profile(store, profile_id)
    payload = ClientProfileTemplateDraftPayload(
        templateKey=templateKey,
        currentTemplate=currentTemplate,
        feedback=feedback,
    )
    extra_reference_blocks: list[str] = []
    with tempfile.TemporaryDirectory(prefix="template-assets-") as temp_dir:
        file_sources: list[dict[str, str]] = []
        for index, upload in enumerate((files or [])[:6]):
            filename = _safe_knowledge_filename(upload.filename or f"reference-{index + 1}.txt")
            data = await upload.read()
            if not data:
                continue
            content_type = _pick_file_mime(filename)
            extension = Path(filename).suffix.lower()
            if extension in SUPPORTED_KNOWLEDGE_EXTENSIONS and not str(content_type).startswith("image/"):
                try:
                    text = _decode_knowledge_file(filename, data)
                    if text.strip():
                        extra_reference_blocks.append(f"## {filename}\n{text[:12000]}")
                except HTTPException:
                    if extension != ".pdf":
                        raise
                if extension != ".pdf":
                    continue
            temp_path = Path(temp_dir) / filename
            temp_path.write_bytes(data)
            file_sources.append({"path": str(temp_path), "contentType": content_type})
        key, template = _generate_client_template_draft_text(
            profile,
            payload,
            extra_reference_context="\n\n".join(extra_reference_blocks),
            file_sources=file_sources,
        )
    return {"ok": True, "templateKey": key, "template": template}


@app.post("/client-profiles/{profile_id}/knowledge/import")
async def import_client_profile_knowledge(
    profile_id: str,
    file: UploadFile = File(...),
    sourceType: str = Form("general"),
    label: str = Form(""),
):
    store = _load_client_profile_store(create=True)
    profile = _find_client_profile(store, profile_id)
    filename = _safe_knowledge_filename(file.filename or "knowledge.txt")
    data = await file.read()
    _validate_knowledge_file_upload(filename, data)
    text = ""
    ext = Path(filename).suffix.lower() or ".txt"
    if ext in EXCEL_KNOWLEDGE_EXTENSIONS or ext in LEGACY_EXCEL_KNOWLEDGE_EXTENSIONS:
        text = _decode_knowledge_file(filename, data)
    else:
        try:
            text = _decode_knowledge_file(filename, data)
        except Exception:
            text = ""
    source_id = uuid.uuid4().hex
    stored_name = f"{source_id}.source{ext}"
    text_stored_name = f"{source_id}.txt" if text else ""
    target_dir = _site_knowledge_path(profile["id"])
    target_dir.mkdir(parents=True, exist_ok=True)
    (target_dir / stored_name).write_bytes(data)
    if text_stored_name:
        (target_dir / text_stored_name).write_text(text, encoding="utf-8")
    source = _normalize_profile_knowledge_source({
        "id": source_id,
        "label": label.strip() or filename,
        "sourceType": sourceType.strip() or "general",
        "filename": filename,
        "storedName": stored_name,
        "textStoredName": text_stored_name,
        "contentType": _pick_file_mime(filename),
        "size": len(data),
        "chars": len(text),
        "enabled": True,
        "createdAt": _utc_now_iso(),
    })
    profile.setdefault("knowledgeSources", []).append(source)
    profile["updatedAt"] = _utc_now_iso()
    _write_client_profile_store(store)
    return {"ok": True, "source": _profile_knowledge_public(source)}


