def _delete_stored_profile_source_file(profile: dict[str, Any], source: dict[str, Any]) -> None:
    stored_names = [
        str(source.get("storedName") or "").strip(),
        str(source.get("textStoredName") or "").strip(),
    ]
    source_dir = _site_knowledge_path(profile["id"])
    for stored_name in dict.fromkeys(stored_names):
        if not stored_name or stored_name.startswith(LEGACY_SKILLS_STORED_PREFIX):
            continue
        try:
            source_path = (source_dir / stored_name).resolve()
            source_path.relative_to(source_dir.resolve())
        except Exception:
            continue
        try:
            source_path.unlink(missing_ok=True)
        except Exception:
            api_logger.warning("[knowledge] Could not delete stored source file: %s", source_path)


def _clear_client_profile_knowledge(profile_id: str, source_type: str):
    clean_type = str(source_type or "").strip()
    if not clean_type:
        raise HTTPException(status_code=400, detail="sourceType is required.")
    target_bucket = _skill_source_bucket(clean_type)
    store = _load_client_profile_store(create=True)
    profile = _find_client_profile(store, profile_id)
    kept_sources: list[dict[str, Any]] = []
    removed_sources: list[dict[str, Any]] = []
    for source in profile.get("knowledgeSources") or []:
        if _skill_source_bucket(str(source.get("sourceType") or "general")) == target_bucket:
            removed_sources.append(source)
        else:
            kept_sources.append(source)
    removed_source_ids = {str(source.get("id") or "") for source in removed_sources if str(source.get("id") or "")}
    for source in removed_sources:
        _delete_stored_profile_source_file(profile, source)

    removed_artifact_ids: set[str] = set()
    next_artifacts: list[dict[str, Any]] = []
    for artifact in _normalize_profile_knowledge_artifacts(profile.get("knowledgeArtifacts") or []):
        source_ids = [str(source_id).strip() for source_id in artifact.get("sourceIds") or [] if str(source_id).strip()]
        remaining_source_ids = [source_id for source_id in source_ids if source_id not in removed_source_ids]
        if source_ids and not remaining_source_ids:
            removed_artifact_ids.add(str(artifact.get("id") or ""))
            continue
        if len(remaining_source_ids) != len(source_ids):
            artifact = {**artifact, "sourceIds": remaining_source_ids, "updatedAt": _utc_now_iso()}
        next_artifacts.append(artifact)

    if removed_artifact_ids:
        rule_pack = _normalize_rule_pack(profile.get("rulePack") or {})
        rule_pack["sourceArtifactIds"] = [
            artifact_id
            for artifact_id in rule_pack.get("sourceArtifactIds") or []
            if str(artifact_id) not in removed_artifact_ids
        ]
        profile["rulePack"] = rule_pack

    profile["knowledgeSources"] = kept_sources
    profile["knowledgeArtifacts"] = next_artifacts
    profile["updatedAt"] = _utc_now_iso()
    _write_client_profile_store(store)
    return {
        "ok": True,
        "cleared": len(removed_sources),
        "sources": [_profile_knowledge_public(source) for source in _profile_knowledge_sources(profile)],
        "artifacts": [_knowledge_artifact_public(artifact) for artifact in next_artifacts],
    }


@app.delete("/client-profiles/{profile_id}/knowledge")
def clear_client_profile_knowledge(profile_id: str, sourceType: str = ""):
    return _clear_client_profile_knowledge(profile_id, sourceType)


def _find_profile_source(profile: dict[str, Any], source_id: str) -> dict[str, Any]:
    clean_id = str(source_id or "").strip()
    for source in profile.get("knowledgeSources") or []:
        if str(source.get("id") or "") == clean_id:
            return source
    for source in _legacy_skill_profile_sources() if _should_include_legacy_skill_sources(profile) else []:
        if str(source.get("id") or "") == clean_id:
            return source
    raise HTTPException(status_code=404, detail=f"Knowledge source not found: {source_id}")


def _knowledge_unreadable_detail() -> str:
    return (
        "资料没有提炼出可用内容。请确认上传的是可复制文字的 PDF、DOCX、TXT、MD、CSV、HTML 或 Excel；"
        "如果是扫描件、图片版 PDF 或导出乱码，请先 OCR 或另存为可复制文字后再上传。"
    )


def _knowledge_text_readability_issue(text: str) -> str:
    clean = str(text or "").strip()
    if not clean:
        return "资料没有读取到正文内容。请换成可复制文字的文件后再上传。"

    sample = clean[:8000]
    visible_chars = [char for char in sample if not char.isspace()]
    if not visible_chars:
        return "资料没有读取到正文内容。请换成可复制文字的文件后再上传。"

    replacement_count = sample.count("\ufffd")
    if replacement_count >= 12 and replacement_count / max(len(sample), 1) > 0.01:
        return _knowledge_unreadable_detail()

    control_count = sum(1 for char in sample if ord(char) < 32 and char not in "\n\r\t")
    if control_count >= 8 and control_count / max(len(sample), 1) > 0.01:
        return _knowledge_unreadable_detail()

    wordish_count = len(re.findall(r"[A-Za-z0-9\u4e00-\u9fff]", sample))
    if len(sample) >= 300 and wordish_count / max(len(visible_chars), 1) < 0.08:
        return _knowledge_unreadable_detail()

    return ""


def _ensure_readable_knowledge_text(text: str) -> str:
    issue = _knowledge_text_readability_issue(text)
    if issue:
        raise HTTPException(status_code=400, detail=issue)
    return text


UNREADABLE_KNOWLEDGE_AI_PATTERNS = (
    "unreadable source material",
    "source material appears to be corrupted",
    "unsupported binary format",
    "not human-readable",
    "no information could be extracted",
    "please provide a valid, readable",
    "uninterpretable characters",
    "impossible to extract any meaningful information",
    "without decipherable text",
)


def _knowledge_artifact_looks_like_unreadable_ai_response(artifact: dict[str, Any]) -> bool:
    text = f"{artifact.get('title') or ''}\n{artifact.get('markdown') or ''}".lower()
    matches = sum(1 for pattern in UNREADABLE_KNOWLEDGE_AI_PATTERNS if pattern in text)
    has_unreadable_heading = (
        "unreadable source material" in text
        or "source_material_analysis" in text
        or "unreadable" in str(artifact.get("title") or "").lower()
    )
    return (has_unreadable_heading and matches >= 1) or matches >= 3


def _mark_profile_source_extraction_failed(
    store: dict[str, Any],
    profile: dict[str, Any],
    source: dict[str, Any],
) -> None:
    source["extractionStatus"] = "failed"
    source["artifactIds"] = []
    profile["knowledgeSources"] = [
        source if str(item.get("id") or "") == str(source.get("id") or "") else item
        for item in profile.get("knowledgeSources") or []
    ]
    profile["updatedAt"] = _utc_now_iso()
    _write_client_profile_store(store)


def _normalize_vertex_model_name(model_name: str) -> str:
    cleaned = str(model_name or "").strip()
    aliases = {
        "gemini-3.1-pro": "gemini-3.1-pro-preview",
    }
    return aliases.get(cleaned, cleaned)


def _knowledge_extraction_model() -> str:
    explicit_model = os.getenv("KNOWLEDGE_EXTRACTION_MODEL", "").strip()
    if explicit_model:
        return _normalize_vertex_model_name(explicit_model) if _use_vertex_ai() else explicit_model
    if _use_vertex_ai():
        return _normalize_vertex_model_name(os.getenv("GENAI_PRO_MODEL", "").strip() or "gemini-3.1-pro-preview")
    return _ai_pro_model()


def _profile_source_ai_file_sources(profile: dict[str, Any], source: dict[str, Any]) -> list[dict[str, str]]:
    stored_name = str(source.get("storedName") or "").strip()
    if not stored_name or stored_name.startswith(LEGACY_SKILLS_STORED_PREFIX):
        return []
    original_path = _profile_source_original_path(profile, source)
    if not original_path.exists() or not original_path.is_file():
        return []
    content_type = _pick_file_mime(str(source.get("filename") or original_path.name))
    if not _is_supported_ai_inline_file_mime(content_type):
        return []
    return [
        {
            "path": str(original_path),
            "filename": str(source.get("filename") or original_path.name),
            "contentType": content_type,
        }
    ]


