@app.get("/client-profiles/{profile_id}/rules")
def get_client_profile_rules(profile_id: str):
    store = _load_client_profile_store(create=True)
    profile = _find_client_profile(store, profile_id)
    return {"ok": True, "rulePack": _rule_pack_public(profile.get("rulePack") or {})}


@app.put("/client-profiles/{profile_id}/rules")
def save_client_profile_rules(profile_id: str, payload: ClientRulePackPayload):
    store = _load_client_profile_store(create=True)
    profile = _find_client_profile(store, profile_id)
    existing = _normalize_rule_pack(profile.get("rulePack") or {})
    incoming = _normalize_rule_pack(payload.rulePack)
    if incoming["version"] <= 0:
        incoming["version"] = max(1, existing.get("version", 0))
    incoming["updatedAt"] = _utc_now_iso()
    profile["rulePack"] = incoming
    profile["updatedAt"] = incoming["updatedAt"]
    _write_client_profile_store(store)
    return {"ok": True, "rulePack": _rule_pack_public(profile.get("rulePack") or {})}


@app.post("/client-profiles/{profile_id}/rules/generate")
def generate_client_profile_rules(profile_id: str):
    store = _load_client_profile_store(create=True)
    profile = _find_client_profile(store, profile_id)
    if not _ai_configured():
        raise HTTPException(status_code=400, detail=_ai_missing_detail())
    try:
        raw = _gemini_generate_text(
            _get_gemini_api_key(),
            _build_rule_pack_prompt(profile),
            _ai_pro_model(),
            timeout=180,
        )
        parsed = _parse_ai_json_object(raw)
    except Exception as exc:
        _raise_ai_error(exc)
    existing = _normalize_rule_pack(profile.get("rulePack") or {})
    rule_pack = _normalize_rule_pack(parsed)
    rule_pack["version"] = int(existing.get("version") or 0) + 1
    rule_pack["sourceArtifactIds"] = [artifact["id"] for artifact in _reviewed_or_all_artifacts(profile)]
    rule_pack["updatedAt"] = _utc_now_iso()
    profile["rulePack"] = rule_pack
    profile["updatedAt"] = rule_pack["updatedAt"]
    _write_client_profile_store(store)
    return {"ok": True, "rulePack": _rule_pack_public(rule_pack)}


@app.post("/client-profiles/{profile_id}/generation-sessions")
def create_generation_session(profile_id: str, payload: GenerationSessionPayload):
    store = _load_client_profile_store(create=True)
    profile = _find_client_profile(store, profile_id)
    session = _normalize_generation_session({
        "targetType": payload.targetType,
        "targetId": payload.targetId,
        "selectedFields": payload.selectedFields,
        "promptInputs": payload.promptInputs,
        "syncStatus": payload.syncStatus,
        "outputVersions": [{"version": 1, "output": payload.output, "createdAt": _utc_now_iso()}] if payload.output else [],
    })
    if not session["targetType"]:
        raise HTTPException(status_code=400, detail="Generation session targetType is required.")
    profile.setdefault("generationSessions", []).append(session)
    profile["updatedAt"] = _utc_now_iso()
    _write_client_profile_store(store)
    return {"ok": True, "session": _generation_session_public(session)}


def _find_generation_session(profile: dict[str, Any], session_id: str) -> dict[str, Any]:
    clean_id = str(session_id or "").strip()
    for session in profile.get("generationSessions") or []:
        if str(session.get("id") or "") == clean_id:
            return session
    raise HTTPException(status_code=404, detail=f"Generation session not found: {session_id}")


def _build_generation_feedback_prompt(profile: dict[str, Any], session: dict[str, Any], feedback: str) -> str:
    latest = (session.get("outputVersions") or [{}])[-1]
    return f"""
You are revising an AI-generated SEO/WooCommerce output after operator feedback.
Return ONLY valid JSON with this shape:
{{"output": {{"fieldName": "revised value"}}}}

Customer Rule Pack:
{json.dumps(_rule_pack_public(profile.get("rulePack") or {}), ensure_ascii=False, indent=2)}

Generation session:
{json.dumps(_generation_session_public(session), ensure_ascii=False, indent=2)}

Latest output:
{json.dumps(latest.get("output") or {}, ensure_ascii=False, indent=2)}

Operator feedback:
{feedback}
""".strip()


@app.post("/client-profiles/{profile_id}/generation-sessions/{session_id}/feedback")
def add_generation_session_feedback(profile_id: str, session_id: str, payload: GenerationSessionFeedbackPayload):
    store = _load_client_profile_store(create=True)
    profile = _find_client_profile(store, profile_id)
    session = _find_generation_session(profile, session_id)
    feedback = str(payload.feedback or "").strip()
    if not feedback:
        raise HTTPException(status_code=400, detail="Feedback text is required.")
    output = dict(payload.output or {})
    if not output:
        if not _ai_configured():
            raise HTTPException(status_code=400, detail=_ai_missing_detail())
        try:
            raw = _gemini_generate_text(
                _get_gemini_api_key(),
                _build_generation_feedback_prompt(profile, session, feedback),
                _ai_pro_model(),
                timeout=120,
            )
            parsed = _parse_ai_json_object(raw)
            output = dict(parsed.get("output") if isinstance(parsed, dict) and isinstance(parsed.get("output"), dict) else parsed)
        except Exception as exc:
            _raise_ai_error(exc)
    if not output:
        raise HTTPException(status_code=502, detail="Generation feedback did not produce revised output.")
    now = _utc_now_iso()
    session.setdefault("feedback", []).append({"id": uuid.uuid4().hex, "text": feedback, "createdAt": now})
    next_version = max([int(item.get("version") or 0) for item in session.get("outputVersions") or []] or [0]) + 1
    session.setdefault("outputVersions", []).append({
        "version": next_version,
        "output": output,
        "feedback": feedback,
        "createdAt": now,
    })
    session["updatedAt"] = now
    profile["updatedAt"] = now
    _write_client_profile_store(store)
    return {"ok": True, "session": _generation_session_public(session)}


