@app.put("/client-profiles/{profile_id}/skill-packs/{pack_id}")
def update_client_skill_pack(profile_id: str, pack_id: str, payload: ClientSkillPackUpdatePayload):
    store = _load_client_profile_store(create=True)
    profile = _find_client_profile(store, profile_id)
    pack = _find_skill_pack(profile, pack_id)
    if pack.get("status") == "published":
        raise HTTPException(status_code=400, detail="Published Skill Packs cannot be edited. Generate or edit a draft instead.")
    updates = payload.model_dump(exclude_unset=True)
    for key in ("companySkill", "productSkill", "keywordSkill"):
        if key in updates:
            pack[key] = _normalize_skill_pack_dict(updates[key])
    if "taskSkills" in updates:
        pack["taskSkills"] = _normalize_task_skills(updates["taskSkills"])
    pack["updatedAt"] = _utc_now_iso()
    profile["updatedAt"] = _utc_now_iso()
    _write_client_profile_store(store)
    return {"ok": True, "skillPack": _skill_pack_public(_normalize_skill_pack(pack, profile))}


@app.post("/client-profiles/{profile_id}/skill-packs/{pack_id}/publish")
def publish_client_skill_pack(profile_id: str, pack_id: str):
    store = _load_client_profile_store(create=True)
    profile = _find_client_profile(store, profile_id)
    pack = _find_skill_pack(profile, pack_id)
    next_version = max([int(item.get("version") or 0) for item in profile.get("skillPacks") or []] or [0]) + 1
    now = _utc_now_iso()
    pack["status"] = "published"
    pack["version"] = next_version
    pack["publishedAt"] = now
    pack["updatedAt"] = now
    profile["activeSkillPackId"] = pack["id"]
    profile["updatedAt"] = now
    _write_client_profile_store(store)
    return {"ok": True, "skillPack": _skill_pack_public(_normalize_skill_pack(pack, profile))}


