@app.post("/site-profiles/{site_id}/style-kit/import")
def import_site_style_kit(site_id: str, payload: SiteStyleKitImportPayload):
    store = _load_client_profile_store(create=True)
    profile = _find_client_profile(store, site_id)
    raw_url = str(payload.siteUrl or profile.get("siteUrl") or "").strip()
    if not raw_url:
        raise HTTPException(status_code=400, detail="siteUrl is required")
    source_url = raw_url if re.match(r"^https?://", raw_url, flags=re.IGNORECASE) else f"https://{raw_url}"
    try:
        response = _http_request_with_proxy_fallback("GET", source_url, timeout=30, follow_redirects=True)
        if _is_cloudflare_challenge_response(response):
            raise HTTPException(status_code=502, detail="目标网页触发了 Cloudflare challenge，无法从服务器抓取品牌样式。")
        if response.status_code != 200:
            raise HTTPException(status_code=response.status_code, detail=_response_detail(response, "Failed to fetch site style"))
        result = _build_imported_style_kit(profile.get("styleKit") or {}, source_url, response.text)
        return {"ok": True, **result}
    except HTTPException:
        raise
    except Exception as exc:
        raise HTTPException(status_code=500, detail=str(exc))


