@app.put("/site-profiles/{site_id}/blog-framework-standard")
def save_site_blog_framework_standard(site_id: str, payload: SiteBlogFrameworkStandardPayload):
    store = _load_client_profile_store(create=True)
    profile = _find_client_profile(store, site_id)
    current = _normalize_blog_framework_standard(
        profile.get("blogFrameworkStandard") or {},
        legacy_frameworks=profile.get("blogFrameworks") or [],
        template_pack=profile.get("templatePack") or {},
    )
    incoming_value = dict(payload.standard or {})
    # A user save is the boundary where an editable default draft becomes a
    # configured site standard. Preserve the submitted v2 draft instead of
    # treating it as stale persisted default data that needs migration.
    incoming_value["status"] = "configured"
    incoming = _normalize_blog_framework_standard(
        incoming_value,
        template_pack=profile.get("templatePack") or {},
    )
    updated_at = _utc_now_iso()
    saved = {
        **incoming,
        "status": "configured",
        "version": current["version"] + 1,
        "basePresetVersion": current["basePresetVersion"],
        "updatedAt": updated_at,
    }
    profile["blogFrameworkStandard"] = saved
    profile["blogFrameworks"] = saved["frameworks"]
    profile["updatedAt"] = updated_at
    _write_client_profile_store(store)
    return {"ok": True, "standard": saved, "presets": _default_blog_frameworks(profile.get("templatePack") or {})}


BLOG_FRAMEWORK_CHANGE_LABELS = {
    "contentGoal": "文章目标",
    "funnelStage": "营销漏斗阶段",
    "defaultLanguage": "默认语言",
    "targetAudience": "目标读者",
    "wordCount": "建议篇幅",
    "requiredInputs": "写前资料",
    "voiceRules": "语气与可读性",
    "evidenceRules": "证据规则",
    "outlineBlocks": "文章结构",
    "faqRules": "FAQ 规则",
    "ctaRules": "CTA 规则",
    "internalLinkRules": "内链规则",
    "mediaRules": "媒体规则",
    "seoRules": "SEO 规则",
    "prohibitedClaims": "禁止编造项",
    "preflightChecks": "发布前检查",
}


def _blog_framework_assistant_prompt(
    profile: dict[str, Any],
    framework: dict[str, Any],
    message: str,
    conversation: list[dict[str, str]],
) -> str:
    history = [
        {"role": str(item.get("role") or "")[:20], "content": str(item.get("content") or "")[:3000]}
        for item in conversation[-12:]
        if isinstance(item, dict) and str(item.get("content") or "").strip()
    ]
    return f"""
你是站点级博客撰写框架编辑助手。请根据用户反馈，只修改当前选中的一个长期框架。
这是给后续 Blog AI 使用的写作施工图，不是成品文章，也不是当前文章大纲。

严格要求：
- 返回一个完整 framework、简短中文 reply、warnings 数组，以及确有歧义时可选的 clarification。
- 保留 framework 的 id 和 articleType；不要修改其他框架、站点版本或系统内置基线。
- 框架必须覆盖：文章任务、写前证据、语气与可读性、按顺序的文章结构、SEO/媒体规则、发布前检查与禁止编造项。
- AIDA 只能作为 funnelStage 的主题规划背景，不得强制成为所有文章的大纲。
- 不固定 Flesch 80、FAQ 数量或统一字数；不要要求口头填充、题外话、故意的不完美或无依据的趋势。
- 只有用户明确要求时才改变默认语言、目标读者、建议字数或品牌语气。
- 若用户描述可能是“当前文章要求”而非“站点长期框架”，只通过 clarification 追问一次，不要自行扩大范围。
- 只返回有效 JSON，不要 Markdown。

返回结构：
{{
  "reply": "中文修改说明",
  "framework": {{完整框架对象}},
  "warnings": ["风险提示"],
  "clarification": "可选的一次性澄清问题"
}}

站点：{profile.get('siteName') or profile.get('name') or ''}
网址：{profile.get('siteUrl') or ''}
当前框架：
{json.dumps(framework, ensure_ascii=False, indent=2)}

最近对话：
{json.dumps(history, ensure_ascii=False, indent=2)}

用户本轮反馈：
{message}
""".strip()


def _blog_framework_changes(before: dict[str, Any], after: dict[str, Any]) -> list[dict[str, Any]]:
    changes: list[dict[str, Any]] = []
    for key in BLOG_FRAMEWORK_CHANGE_LABELS:
        if before.get(key) == after.get(key):
            continue
        changes.append({
            "path": key,
            "label": BLOG_FRAMEWORK_CHANGE_LABELS[key],
            "before": before.get(key),
            "after": after.get(key),
            "reason": "根据本轮用户反馈调整",
        })
    return changes


@app.post("/site-profiles/{site_id}/blog-framework-standard/assistant")
def revise_site_blog_framework_standard(
    site_id: str,
    payload: SiteBlogFrameworkStandardAssistantPayload,
):
    store = _load_client_profile_store(create=True)
    profile = _find_client_profile(store, site_id)
    message = str(payload.message or "").strip()
    if not message:
        raise HTTPException(status_code=400, detail="请先描述希望怎样调整当前博客撰写框架。")
    draft_value = dict(payload.standard or profile.get("blogFrameworkStandard") or {})
    # Revision operates on an in-memory user draft. Mark it configured only
    # for normalization so custom frameworks and unsaved edits are retained;
    # nothing is persisted until the explicit PUT endpoint is called.
    draft_value["status"] = "configured"
    standard = _normalize_blog_framework_standard(
        draft_value,
        legacy_frameworks=profile.get("blogFrameworks") or [],
        template_pack=profile.get("templatePack") or {},
    )
    framework_id = _profile_slug(str(payload.frameworkId or ""), "")
    selected_index = next(
        (index for index, item in enumerate(standard["frameworks"]) if item.get("id") == framework_id),
        -1,
    )
    if selected_index < 0:
        raise HTTPException(status_code=404, detail="未找到要修改的博客撰写框架。")
    if not _ai_configured():
        raise HTTPException(status_code=400, detail=_ai_missing_detail())

    selected = standard["frameworks"][selected_index]
    try:
        raw = _gemini_generate_text(
            _get_gemini_api_key(),
            _blog_framework_assistant_prompt(profile, selected, message, payload.conversation),
            _ai_pro_model(),
            timeout=120,
        )
        parsed = _parse_ai_json_object(raw)
    except HTTPException:
        raise
    except Exception as exc:
        _raise_ai_error(exc)
    if not isinstance(parsed.get("framework"), dict):
        raise HTTPException(status_code=502, detail="AI 未返回有效的博客框架草稿，请保留当前草稿后重试。")

    candidate_raw = {**parsed["framework"], "id": selected["id"], "articleType": selected["articleType"]}
    candidate = _normalize_blog_frameworks([candidate_raw], profile.get("templatePack") or {})[0]
    if not candidate.get("outlineBlocks") or not candidate.get("contentGoal"):
        raise HTTPException(status_code=502, detail="AI 返回的博客框架缺少必要结构，请重试。")
    draft = {**standard, "frameworks": list(standard["frameworks"])}
    draft["frameworks"][selected_index] = candidate
    clarification = str(parsed.get("clarification") or "").strip()
    already_clarified = any(
        str(item.get("role") or "") == "assistant" and str(item.get("content") or "").strip()
        for item in payload.conversation
        if isinstance(item, dict)
    )
    result = {
        "ok": True,
        "standard": draft,
        "reply": str(parsed.get("reply") or "已更新当前框架草稿；保存前不会影响 Blog AI。").strip(),
        "changes": _blog_framework_changes(selected, candidate),
        "warnings": [str(item).strip() for item in parsed.get("warnings") or [] if str(item).strip()][:20],
    }
    if clarification and not already_clarified:
        result["clarification"] = clarification
    return result


@app.post("/site-profiles/{site_id}/blog-frameworks/assistant")
def create_site_blog_framework_draft(site_id: str, payload: SiteBlogFrameworkAssistantPayload):
    store = _load_client_profile_store(create=True)
    profile = _find_client_profile(store, site_id)
    message = str(payload.message or "").strip()
    if not message:
        raise HTTPException(status_code=400, detail="请先描述希望怎样组织博客框架。")
    lower = message.lower()
    scope = "site" if any(term in lower for term in ("以后", "所有", "长期", "默认", "每篇", "site-wide")) else "article"
    article_type = "exhibition" if any(term in lower for term in ("展会", "exhibition", "trade show")) else "standard"
    label = "AI 展会复盘框架" if article_type == "exhibition" else "AI 通用文章框架"
    blocks = [
        {"heading": "直接答案", "intent": "在开头先回答读者的核心问题。", "required": True, "contentRules": "先给出可执行结论，再展开细节。"},
        {"heading": "核心信息与判断依据", "intent": "根据当前主题帮助目标读者理解和判断。", "required": True, "contentRules": "只使用站点资料和当前 brief 能支持的信息。"},
    ]
    if any(term in lower for term in ("维护", "安装", "maintenance", "installation")):
        blocks.append({"heading": "安装与维护", "intent": "说明使用和维护注意事项。", "required": True, "contentRules": "只使用站点资料中已确认的信息。"})
    if any(term in lower for term in ("faq", "常见问题", "问答")):
        blocks.append({"heading": "FAQ", "intent": "回答匹配主题的常见问题。", "required": False, "contentRules": "优先使用已审核 FAQ 库。"})
    framework = _normalize_blog_frameworks([{
        "id": f"ai-{article_type}",
        "label": label,
        "articleType": article_type,
        "requiredInputs": ["topic", "targetKeywords"],
        "outlineBlocks": blocks,
        "faqRules": "主题匹配时使用 3-5 个已审核 FAQ。",
        "ctaRules": "只有站点资料或当前 brief 提供真实下一步时才使用 CTA。",
        "internalLinkRules": "只使用内链索引中与当前主题相关的有效链接。",
        "mediaRules": "在能帮助读者理解内容的位置使用相关图片或视频。",
        "seoRules": "主关键词自然出现在标题、开头、标题层级和描述中。",
        "prohibitedClaims": ["不要编造认证、价格、交期、客户名称或性能数据。"],
    }], profile.get("templatePack") or {})[0]
    return {
        "ok": True,
        "scope": scope,
        "framework": framework,
        "reply": f"已生成{('站点长期' if scope == 'site' else '当前文章')}框架草稿；保存前不会影响现有框架。",
        "warnings": [],
    }


