@app.post("/site-profiles/{site_id}/blog-format-standard/scan")
def scan_site_blog_format_standard(site_id: str, payload: SiteBlogFormatStandardScanPayload):
    store = _load_client_profile_store(create=True)
    profile = _find_client_profile(store, site_id)
    style_kit = _normalize_site_style_kit(profile.get("styleKit") or {})
    source_url = str(profile.get("siteUrl") or (profile.get("settings") or {}).get("wpUrl") or "").strip()
    warnings: list[str] = []
    evidence = ["站点品牌样式", "历史博客修复格式"]
    confidence = "saved" if profile.get("blogFormatStandard") else "fallback"
    scanned_metrics: dict[str, Any] = {}
    if payload.refresh and source_url:
        try:
            response = _http_request_with_proxy_fallback("GET", source_url, timeout=20, follow_redirects=True)
            if response.status_code >= 400 or _is_cloudflare_challenge_response(response):
                raise RuntimeError(_response_detail(response, "无法读取网站样式"))
            imported = _build_imported_style_kit(style_kit, source_url, response.text)
            style_kit = imported["styleKit"]
            warnings.extend(imported.get("warnings") or [])
            scanned_metrics = dict(imported.get("evidence", {}).get("blogMetrics") or {})
            evidence = ["网站首页", *[str(item.get("source") or "") for item in imported["evidence"].get("fonts", [])[:3]]]
            confidence = "scanned"
        except Exception as exc:
            warnings.append(f"网站格式读取失败，已使用保存的站点样式：{_blog_warning_detail(exc)}")
    current = _normalize_blog_format_standard(
        profile.get("blogFormatStandard") or {},
        style_kit=style_kit,
        bulk_format=profile.get("bulkBlogFormat") or {},
        source_url=source_url,
    )
    current["status"] = "draft"
    for key, value in scanned_metrics.items():
        if key in current["tokens"]:
            current["tokens"][key] = {"mode": "inherit", "value": value}
    current["source"] = {
        "sourceUrl": source_url,
        "capturedAt": _utc_now_iso(),
        "confidence": confidence,
        "evidence": [item for item in evidence if item],
    }
    return {
        "ok": True,
        "standard": current,
        "diagnosis": _blog_format_standard_diagnosis(current),
        "warnings": warnings,
    }


@app.post("/site-profiles/{site_id}/blog-format-standard/assistant")
def revise_site_blog_format_standard(site_id: str, payload: SiteBlogFormatAssistantPayload):
    store = _load_client_profile_store(create=True)
    profile = _find_client_profile(store, site_id)
    message = str(payload.message or "").strip()
    if not message:
        raise HTTPException(status_code=400, detail="请先描述希望怎样调整博客格式。")
    current = _normalize_blog_format_standard(
        payload.standard or profile.get("blogFormatStandard") or {},
        style_kit=profile.get("styleKit") or {},
        bulk_format=profile.get("bulkBlogFormat") or {},
        source_url=str(profile.get("siteUrl") or ""),
    )
    draft, changes = _apply_blog_format_instruction(current, message)
    warnings: list[str] = []
    reply = (
        f"已根据反馈调整 {len(changes)} 项格式标准；右侧预览只展示草稿，保存前不会修改任何文章。"
        if changes else "这条反馈还没有匹配到可安全写回的格式项，请更具体地描述字号、标题、行距、表格或内容宽度。"
    )
    if _ai_configured():
        try:
            prompt = f"""你是博客排版设计助手。根据用户反馈修改结构化博客格式标准。
只允许更新这些 token：{', '.join(BLOG_FORMAT_STANDARD_TOKEN_KEYS)}。
只修改用户明确要求的项目；字体和品牌颜色只有用户明确要求时才能修改。
当前标准：{json.dumps(current, ensure_ascii=False)}
最近对话：{json.dumps(payload.conversation[-8:], ensure_ascii=False)}
用户反馈：{message}
返回 ONLY JSON：{{"reply":"中文说明","updates":[{{"token":"paragraphSpacing","value":20,"label":"段落间距"}}],"warnings":[]}}"""
            parsed = _parse_ai_json_object(_gemini_generate_text(
                _get_gemini_api_key(), prompt, _ai_flash_model(), timeout=90,
            ))
            ai_updates = parsed.get("updates") if isinstance(parsed.get("updates"), list) else []
            for update in ai_updates:
                if not isinstance(update, dict):
                    continue
                token_key = str(update.get("token") or "")
                if token_key not in BLOG_FORMAT_STANDARD_TOKEN_KEYS:
                    continue
                before = draft["tokens"][token_key]["value"]
                candidate = update.get("value")
                fallback_value = current["tokens"][token_key]["value"]
                if isinstance(fallback_value, (int, float)):
                    candidate = _coerce_number(candidate, fallback_value)
                    if isinstance(fallback_value, int):
                        candidate = int(candidate)
                else:
                    candidate = str(candidate or fallback_value).strip()[:180]
                draft["tokens"][token_key] = {"mode": "managed", "value": candidate}
                changes = [item for item in changes if item.get("token") != token_key]
                changes.append({
                    "token": token_key,
                    "label": str(update.get("label") or token_key)[:80],
                    "before": before,
                    "after": candidate,
                })
            reply = str(parsed.get("reply") or reply).strip()
            ai_warnings = parsed.get("warnings") if isinstance(parsed.get("warnings"), list) else []
            warnings.extend(str(item).strip() for item in ai_warnings if str(item).strip())
        except Exception as exc:
            warnings.append(f"AI 语意解析暂不可用，已使用安全规则处理：{_blog_warning_detail(exc)}")
    if not changes and not warnings:
        warnings.append(reply)
    return {"ok": True, "standard": draft, "reply": reply, "changes": changes, "warnings": warnings}


