def _bulk_blog_css_color(value: Any, fallback: str) -> str:
    text = str(value or "").strip()
    return text if re.fullmatch(r"#[0-9a-fA-F]{3}(?:[0-9a-fA-F]{3})?", text) else fallback


def _bulk_blog_css_font(value: Any, fallback: str) -> str:
    text = re.sub(r"[^a-zA-Z0-9 ,.'\"_-]", "", str(value or "")).strip()
    return text[:180] or fallback


def _bulk_blog_format_css(profile: dict[str, Any], *, editor: bool = False) -> str:
    config = _normalize_bulk_blog_format(profile.get("bulkBlogFormat") or {})
    style = config["visualStyle"]
    root = ".editor-styles-wrapper" if editor else ".single-post .entry-content"
    return f"""/* Generated by 独立站 AI; style {config['plugin']['styleVersion']} */
{root} {{
  max-width: {int(style['contentMaxWidth'])}px;
  color: {_bulk_blog_css_color(style['textColor'], '#334155')};
  font-family: {_bulk_blog_css_font(style['bodyFontFamily'], 'Inter, Arial, sans-serif')};
  font-size: {int(style['bodyFontSizeDesktop'])}px;
  line-height: {float(style['bodyLineHeight']):g};
}}
{root} h2, {root} h3 {{ font-family: {_bulk_blog_css_font(style['headingFontFamily'], 'Inter, Arial, sans-serif')}; }}
{root} h2 {{ font-size: {int(style['h2FontSizeDesktop'])}px; }}
{root} h3 {{ font-size: {int(style['h3FontSizeDesktop'])}px; }}
{root} a {{ color: {_bulk_blog_css_color(style['linkColor'], '#1476d8')}; }}
{root} table th {{ background: {_bulk_blog_css_color(style['tableHeaderBg'], '#12344d')}; color: {_bulk_blog_css_color(style['tableHeaderText'], '#ffffff')}; }}
{root} table th, {root} table td {{ border-color: {_bulk_blog_css_color(style['tableBorderColor'], '#dbe5ec')}; }}
{root} img {{ border-radius: {int(style['imageRadius'])}px; }}
{root} .blog-cta {{ background: {_bulk_blog_css_color(style['ctaBg'], '#e8f3ff')}; color: {_bulk_blog_css_color(style['ctaText'], '#172033')}; }}
@media (max-width: 782px) {{
  {root} {{ font-size: {int(style['bodyFontSizeMobile'])}px; }}
  {root} h2 {{ font-size: {int(style['h2FontSizeMobile'])}px; }}
  {root} h3 {{ font-size: {int(style['h3FontSizeMobile'])}px; }}
}}
"""


def _bulk_blog_format_plugin_zip(profile: dict[str, Any]) -> bytes:
    config = _normalize_bulk_blog_format(profile.get("bulkBlogFormat") or {})
    site_id = str(profile.get("id") or "default")
    style_version = config["plugin"]["styleVersion"]
    status_json = json.dumps({"siteId": site_id, "styleVersion": style_version}, ensure_ascii=False, separators=(",", ":"))
    php = f"""<?php
/**
 * Plugin Name: Site Blog Format
 * Description: Generated Blog typography for {escape(_display_site_name(profile))}.
 * Version: {style_version.removeprefix('v') or '1'}
 */
if (!defined('ABSPATH')) {{ exit; }}
function seo_wp_sync_blog_format_frontend() {{ wp_enqueue_style('seo-wp-sync-blog-format', plugin_dir_url(__FILE__) . 'assets/blog-format.css', array(), '{style_version}'); }}
function seo_wp_sync_blog_format_editor() {{ wp_enqueue_style('seo-wp-sync-blog-format-editor', plugin_dir_url(__FILE__) . 'assets/editor-blog-format.css', array(), '{style_version}'); }}
add_action('wp_enqueue_scripts', 'seo_wp_sync_blog_format_frontend', 20);
add_action('enqueue_block_editor_assets', 'seo_wp_sync_blog_format_editor', 20);
add_action('rest_api_init', function () {{
  register_rest_route('seo-wp-sync/v1', '/blog-format-status', array(
    'methods' => 'GET', 'permission_callback' => '__return_true',
    'callback' => function () {{ return rest_ensure_response(json_decode('{status_json}', true)); }}
  ));
}});
"""
    output = io.BytesIO()
    with zipfile.ZipFile(output, "w", compression=zipfile.ZIP_DEFLATED) as archive:
        archive.writestr("site-blog-format/site-blog-format.php", php)
        archive.writestr("site-blog-format/assets/blog-format.css", _bulk_blog_format_css(profile))
        archive.writestr("site-blog-format/assets/editor-blog-format.css", _bulk_blog_format_css(profile, editor=True))
    return output.getvalue()


@app.get("/site-profiles/{site_id}/bulk-blog-format/plugin")
def download_site_bulk_blog_format_plugin(site_id: str):
    store = _load_client_profile_store(create=True)
