@app.post("/site-profiles/{site_id}/faqs/generate")
def generate_site_faqs(site_id: str):
    store = _load_client_profile_store(create=True)
    profile = _find_client_profile(store, site_id)
    artifacts = _faq_generation_artifacts(profile)
    if not artifacts:
        raise HTTPException(status_code=422, detail="请先在 Markdown 产物里保留并保存公司信息或产品资料，再单独生成 FAQ。")
    if not _ai_configured():
        raise HTTPException(status_code=400, detail=_ai_missing_detail())
    source_ids = sorted({
        str(source_id)
        for artifact in artifacts
        for source_id in (artifact.get("sourceIds") or [])
        if str(source_id).strip()
    })
    try:
        raw = _gemini_generate_text(
            _get_gemini_api_key(),
            _build_site_faq_generation_prompt(profile, artifacts),
            _knowledge_extraction_model(),
            timeout=120,
        )
        parsed = _parse_ai_json_object(raw)
        generated = _faq_items_from_ai_payload(parsed, source_ids)
    except HTTPException:
        raise
    except Exception as exc:
        _raise_ai_error(exc)
    if not generated:
        raise HTTPException(status_code=422, detail="AI 没有从已保留资料中找到可生成 FAQ 的信息。")
    existing = _normalize_faqs(profile.get("faqs") or [])
    profile["faqs"] = _merge_generated_faqs(existing, generated)
    profile["updatedAt"] = _utc_now_iso()
    _write_client_profile_store(store)
    return {"ok": True, "faqs": _normalize_faqs(profile.get("faqs") or [])}


