@app.put("/site-profiles/{site_id}/internal-link-settings")
def save_site_internal_link_settings(site_id: str, payload: SiteInternalLinkSettingsPayload):
    store = _load_client_profile_store(create=True)
    profile = _find_client_profile(store, site_id)
    profile["internalLinkSettings"] = _normalize_internal_link_settings(payload.internalLinkSettings or {})
    profile["updatedAt"] = _utc_now_iso()
    _write_client_profile_store(store)
    return {"ok": True, "internalLinkSettings": _normalize_internal_link_settings(profile.get("internalLinkSettings") or {})}


def _wp_request(url: str, timeout: int = 20):
    return httpx.get(url, timeout=timeout, follow_redirects=True, verify=_WP_SSL_CTX)


def _link_index_file(site_id: str) -> Path:
    clean_id = _profile_slug(site_id, "site")
    target = _site_cache_path(clean_id) / "link-index.json"
    legacy = LINK_INDEX_DIR / f"{clean_id}.json"
    if not target.exists() and legacy.exists():
        target.parent.mkdir(parents=True, exist_ok=True)
        legacy.replace(target)
    target.parent.mkdir(parents=True, exist_ok=True)
    return target


def _load_link_index(site_id: str) -> dict[str, Any]:
    path = _link_index_file(site_id)
    if not path.exists():
        return {"items": [], "lastRunAt": "", "warnings": []}
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
        return data if isinstance(data, dict) else {"items": [], "lastRunAt": "", "warnings": []}
    except Exception:
        return {"items": [], "lastRunAt": "", "warnings": ["Could not read existing link index cache."]}


def _clean_link_index_url(value: Any) -> str:
    text = str(value or "").strip()
    if not text or not re.match(r"^https?://", text, re.I):
        return ""
    return text.split("#", 1)[0].strip()


def _infer_link_index_type(url: str) -> str:
    path = urlparse(url).path.lower()
    if "/product/" in path or "/products/" in path:
        return "product"
    if "/product-category/" in path or "/category/" in path or "/collections/" in path:
        return "category"
    if "/blog/" in path or re.search(r"/20\d{2}/\d{2}/", path):
        return "post"
    return "page"


def _title_from_link_url(url: str) -> str:
    path = urlparse(url).path.strip("/")
    if not path:
        host = urlparse(url).netloc
        return host or url
    leaf = path.rstrip("/").split("/")[-1]
    title = re.sub(r"[-_]+", " ", leaf).strip()
    return title.title() if title else url


def _sitemap_locations(xml_text: str) -> tuple[str, list[str]]:
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise HTTPException(status_code=400, detail=f"Invalid sitemap XML: {exc}")
    root_type = root.tag.rsplit("}", 1)[-1].lower()
    locations: list[str] = []
    for node in root.iter():
        if node.tag.rsplit("}", 1)[-1].lower() == "loc" and node.text:
            url = _clean_link_index_url(node.text)
            if url:
                locations.append(url)
    return root_type, locations


def _collect_sitemap_urls(sitemap_url: str, max_nested: int = 20) -> list[str]:
    response = _wp_request(sitemap_url, timeout=20)
    status_code = int(getattr(response, "status_code", 200) or 200)
    if status_code >= 400:
        raise HTTPException(status_code=400, detail=f"Sitemap request failed: HTTP {status_code}")
    root_type, locations = _sitemap_locations(str(getattr(response, "text", "") or ""))
    if root_type != "sitemapindex":
        return locations
    urls: list[str] = []
    for nested_url in locations[:max_nested]:
        try:
            nested = _wp_request(nested_url, timeout=20)
            if int(getattr(nested, "status_code", 200) or 200) >= 400:
                continue
            nested_type, nested_locations = _sitemap_locations(str(getattr(nested, "text", "") or ""))
            if nested_type != "sitemapindex":
                urls.extend(nested_locations)
        except Exception:
            continue
    return urls


def _rest_title_from_row(row: dict[str, Any], fallback: str) -> str:
    title = row.get("title")
    if isinstance(title, dict):
        for key in ("rendered", "raw"):
            text = str(title.get(key) or "").strip()
            if text:
                return unescape(re.sub(r"<[^>]+>", " ", text)).strip()
    text = str(row.get("name") or row.get("title") or "").strip()
    return unescape(re.sub(r"<[^>]+>", " ", text)).strip() or fallback


def _site_rest_base_url(profile: dict[str, Any]) -> str:
    return str(profile.get("siteUrl") or (profile.get("settings") or {}).get("wpUrl") or "").strip().rstrip("/")


def _site_rest_get(profile: dict[str, Any], path: str, params: Optional[dict[str, Any]] = None, *, woo: bool = False) -> Any:
    settings = _decrypt_profile_settings(profile)
    base_url = _site_rest_base_url(profile)
    if not base_url:
        return None
    request_params = dict(params or {})
    auth: Optional[tuple[str, str]] = None
    wp_user = str(settings.get("wpUser") or "").strip()
    wp_pass = _normalize_wp_app_pass(str(settings.get("wpAppPass") or ""))
    wc_key = str(settings.get("wcConsumerKey") or "").strip()
    wc_secret = str(settings.get("wcConsumerSecret") or "").strip()
    if woo:
        if wc_key and wc_secret:
            request_params.setdefault("consumer_key", wc_key)
            request_params.setdefault("consumer_secret", wc_secret)
        elif wp_user and wp_pass:
            auth = (wp_user, wp_pass)
        else:
            return None
    elif wp_user and wp_pass:
        auth = (wp_user, wp_pass)
    else:
        return None
    try:
        response = httpx.get(
            f"{base_url}/wp-json{path}",
            params=request_params,
            auth=auth,
            timeout=20,
            follow_redirects=True,
            verify=_WP_SSL_CTX,
        )
        if response.status_code >= 400:
            return None
        return response.json()
    except Exception:
        return None


def _collect_rest_link_index_items(profile: dict[str, Any]) -> list[dict[str, Any]]:
    items: list[dict[str, Any]] = []
    for path, link_type in (
        ("/wp/v2/pages", "page"),
        ("/wp/v2/posts", "post"),
        ("/wp/v2/categories", "category"),
        ("/wp/v2/product_cat", "category"),
    ):
        rows = _site_rest_get(profile, path, {"per_page": 100, "_fields": "link,title,name,slug"})
        if not isinstance(rows, list):
            continue
        for row in rows:
            if not isinstance(row, dict):
                continue
            link = _clean_link_index_url(row.get("link"))
            if not link and link_type == "category" and row.get("slug"):
                link = f"{_site_rest_base_url(profile)}/category/{str(row.get('slug')).strip('/')}/"
            if link:
                items.append({
                    "url": link,
                    "title": _rest_title_from_row(row, _title_from_link_url(link)),
                    "type": link_type,
                    "source": "wordpress_rest",
                    "keywords": [],
                })

    for path, link_type in (
        ("/wc/v3/products", "product"),
        ("/wc/v3/products/categories", "category"),
    ):
        rows = _site_rest_get(profile, path, {"per_page": 100}, woo=True)
        if not isinstance(rows, list):
            continue
        for row in rows:
            if not isinstance(row, dict):
                continue
            link = _clean_link_index_url(row.get("permalink") or row.get("link"))
            if not link and row.get("slug"):
                folder = "product" if link_type == "product" else "product-category"
                link = f"{_site_rest_base_url(profile)}/{folder}/{str(row.get('slug')).strip('/')}/"
            if link:
                items.append({
                    "url": link,
                    "title": _rest_title_from_row(row, _title_from_link_url(link)),
                    "type": link_type,
                    "source": "woocommerce_rest",
                    "keywords": [],
                })
    return items


def _refresh_site_link_index(profile: dict[str, Any]) -> dict[str, Any]:
    settings = _normalize_internal_link_settings(profile.get("internalLinkSettings") or {})
    base_url = str(profile.get("siteUrl") or (profile.get("settings") or {}).get("wpUrl") or "").strip().rstrip("/")
    if not base_url:
        raise HTTPException(status_code=400, detail="Site URL is required before refreshing the internal link index.")
    sitemap_url = f"{base_url}/sitemap.xml"
    include_types = set(settings.get("includeTypes") or [])
    exclude_patterns = [item.lower() for item in settings.get("excludePatterns") or []]
    seen: set[str] = set()
    items: list[dict[str, Any]] = []
    candidates = [
        {"url": url, "title": _title_from_link_url(url), "type": _infer_link_index_type(url), "source": "sitemap", "keywords": []}
        for url in _collect_sitemap_urls(sitemap_url)
    ]
    candidates.extend(_collect_rest_link_index_items(profile))
    for candidate in candidates:
        clean_url = _clean_link_index_url(candidate.get("url"))
        if not clean_url or clean_url in seen:
            continue
        path_lower = urlparse(clean_url).path.lower()
        if any(pattern and pattern.lower() in path_lower for pattern in exclude_patterns):
            continue
        link_type = str(candidate.get("type") or _infer_link_index_type(clean_url)).strip() or "page"
        if include_types and link_type not in include_types:
            continue
        seen.add(clean_url)
        items.append({
            "url": clean_url,
            "title": str(candidate.get("title") or "").strip() or _title_from_link_url(clean_url),
            "type": link_type,
            "source": str(candidate.get("source") or "sitemap").strip() or "sitemap",
            "keywords": [str(item).strip() for item in candidate.get("keywords") or [] if str(item).strip()],
        })
    now = _utc_now_iso()
    result = {"ok": True, "items": items, "lastRunAt": now, "warnings": []}
    LINK_INDEX_DIR.mkdir(parents=True, exist_ok=True)
    _link_index_file(profile["id"]).write_text(json.dumps(result, ensure_ascii=False, indent=2), encoding="utf-8")
    profile["internalLinkSettings"] = {
        **settings,
        "lastRunAt": now,
        "lastRunStatus": "ok",
        "lastError": "",
    }
    return result


@app.get("/site-profiles/{site_id}/link-index")
def get_site_link_index(site_id: str):
    store = _load_client_profile_store(create=True)
    profile = _find_client_profile(store, site_id)
    cached = _load_link_index(profile["id"])
    return {
        "ok": True,
        "items": cached.get("items") if isinstance(cached.get("items"), list) else [],
        "settings": _normalize_internal_link_settings(profile.get("internalLinkSettings") or {}),
        "lastRunAt": str(cached.get("lastRunAt") or ""),
        "warnings": cached.get("warnings") if isinstance(cached.get("warnings"), list) else [],
    }


@app.post("/site-profiles/{site_id}/link-index/refresh")
def refresh_site_link_index(site_id: str):
    store = _load_client_profile_store(create=True)
    profile = _find_client_profile(store, site_id)
    try:
        result = _refresh_site_link_index(profile)
    except Exception as exc:
        settings = _normalize_internal_link_settings(profile.get("internalLinkSettings") or {})
        profile["internalLinkSettings"] = {
            **settings,
            "lastRunAt": _utc_now_iso(),
            "lastRunStatus": "error",
            "lastError": str(getattr(exc, "detail", None) or exc),
        }
        profile["updatedAt"] = _utc_now_iso()
        _write_client_profile_store(store)
        raise
    profile["updatedAt"] = _utc_now_iso()
    _write_client_profile_store(store)
    return {
        **result,
        "settings": _normalize_internal_link_settings(profile.get("internalLinkSettings") or {}),
    }


link_index_auto_scan_scheduler_stop = threading.Event()
link_index_auto_scan_scheduler_thread: Optional[threading.Thread] = None


def _parse_link_index_run_at(value: Any) -> Optional[datetime]:
    text = str(value or "").strip()
    if not text:
        return None
    try:
        return datetime.fromisoformat(text.replace("Z", "+00:00"))
    except ValueError:
        return None


def _link_index_scan_due(settings: dict[str, Any], now: datetime) -> bool:
    if not settings.get("enabled", True):
        return False
    last_run = _parse_link_index_run_at(settings.get("lastRunAt"))
    if not last_run:
        return True
    if last_run.tzinfo is None:
        last_run = last_run.replace(tzinfo=timezone.utc)
    interval_days = max(1, int(settings.get("intervalDays") or 7))
    return now - last_run >= timedelta(days=interval_days)


def _run_due_link_index_auto_scan_once() -> None:
    if not CLIENT_PROFILES_FILE.exists():
        return
    store = _load_client_profile_store(create=False)
    profiles = store.get("profiles") or []
    if not profiles:
        return
    changed = False
    now = datetime.now(timezone.utc)
    for profile in profiles:
        settings = _normalize_internal_link_settings(profile.get("internalLinkSettings") or {})
        if not _link_index_scan_due(settings, now):
            continue
        if not str(profile.get("siteUrl") or (profile.get("settings") or {}).get("wpUrl") or "").strip():
            continue
        try:
            _refresh_site_link_index(profile)
            profile["updatedAt"] = _utc_now_iso()
            changed = True
        except Exception as exc:
            profile["internalLinkSettings"] = {
                **settings,
                "lastRunAt": _utc_now_iso(),
                "lastRunStatus": "error",
                "lastError": str(getattr(exc, "detail", None) or exc),
            }
            profile["updatedAt"] = _utc_now_iso()
            changed = True
            api_logger.warning("[link-index-scheduler] Failed to refresh %s: %s", profile.get("id"), exc)
    if changed:
        _write_client_profile_store(store)


def _link_index_auto_scan_scheduler_loop() -> None:
    while not link_index_auto_scan_scheduler_stop.wait(3600):
        try:
            _run_due_link_index_auto_scan_once()
        except Exception:
            api_logger.exception("[link-index-scheduler] Failed to evaluate scheduled refresh")


def _start_link_index_auto_scan_scheduler() -> None:
    global link_index_auto_scan_scheduler_thread
    if link_index_auto_scan_scheduler_thread and link_index_auto_scan_scheduler_thread.is_alive():
        return
    link_index_auto_scan_scheduler_stop.clear()
    link_index_auto_scan_scheduler_thread = threading.Thread(target=_link_index_auto_scan_scheduler_loop, daemon=True)
    link_index_auto_scan_scheduler_thread.start()


def _stop_link_index_auto_scan_scheduler() -> None:
    link_index_auto_scan_scheduler_stop.set()


