def _parse_wp_upload_seo_data(seo_data: str) -> dict[str, Any]:
    raw = str(seo_data or "").strip()
    if not raw:
        return {}
    try:
        parsed = json.loads(raw)
    except json.JSONDecodeError:
        raise HTTPException(status_code=400, detail="Invalid seoData JSON")
    if not isinstance(parsed, dict):
        raise HTTPException(status_code=400, detail="Invalid seoData JSON: expected object")
    return parsed


@app.post("/wp/upload")
async def wp_upload(
    file: UploadFile = File(...),
    seoData: str = Form(""),
    wpUrl: str = Form(""),
    wpUser: str = Form(""),
    wpAppPass: str = Form(""),
    siteId: str = Form(""),
):
    # Direct coroutine calls (unit tests) may receive the Form default object.
    clean_site_id = siteId.strip() if isinstance(siteId, str) else ""
    if clean_site_id:
        stored = _client_profile_settings_by_id(clean_site_id)
    else:
        stored = _effective_settings()
    wp_url = (
        wpUrl.strip()
        or _settings_or_env(stored, "wpUrl", "WP_URL", "WP_BASE_URL")
    )
    wp_user = wpUser.strip() or _settings_or_env(stored, "wpUser", "WP_USER")
    wp_app_pass = _normalize_wp_app_pass(_pick_value(
        wpAppPass,
        str(stored.get("wpAppPass", "")),
        "WP_APP_PASS",
    ) or os.getenv("WP_APP_PASSWORD", "").strip())

    if not wp_url or not wp_user or not wp_app_pass:
        raise HTTPException(
            status_code=400,
            detail=WP_CONFIG_REQUIRED_DETAIL,
        )
    _reject_placeholder_wp_url(wp_url)

    base_url = wp_url.rstrip("/")
    endpoint = f"{base_url}/wp-json/wp/v2/media"
    content_type = _validated_image_upload_content_type(file.filename or "file", file.content_type or "")

    seo = _parse_wp_upload_seo_data(seoData)
    filename = _normalize_ai_upload_filename(
        str(seo.get("filename") or file.filename or "image.webp"),
        file.filename or "image.webp",
        content_type or "image/webp",
    )
    title = seo.get("title") or ""
    caption = seo.get("caption") or ""
    alt_text = seo.get("alt") or seo.get("alt_text") or ""
    description = seo.get("description") or ""

    file_bytes = await file.read()
    if not file_bytes:
        raise HTTPException(status_code=400, detail="Empty file")

    files = {
        "file": (
            filename,
            file_bytes,
            content_type or "application/octet-stream",
        )
    }

    upload_res = await _http_async_request_with_proxy_fallback(
        "POST",
        endpoint,
        timeout=60,
        files=files,
        auth=(wp_user, wp_app_pass),
    )

    if upload_res.status_code >= 400:
        try:
            err = upload_res.json()
        except Exception:
            err = upload_res.text
        raise HTTPException(status_code=upload_res.status_code, detail=err)

    upload_data = upload_res.json()
    if not isinstance(upload_data, dict):
        raise HTTPException(status_code=502, detail="Invalid WordPress media upload response")

    try:
        media_id = int(upload_data.get("id") or 0)
    except (TypeError, ValueError):
        media_id = 0
    if media_id <= 0:
        raise HTTPException(status_code=502, detail="WordPress media ID missing from upload response")

    meta_payload = {}
    if title:
        meta_payload["title"] = title
    if caption:
        meta_payload["caption"] = caption
    if alt_text:
        meta_payload["alt_text"] = alt_text
    if description:
        meta_payload["description"] = description

    if media_id and meta_payload:
        update_res = await _http_async_request_with_proxy_fallback(
            "POST",
            f"{endpoint}/{media_id}",
            timeout=60,
            json=meta_payload,
            auth=(wp_user, wp_app_pass),
        )
        if update_res.status_code >= 400:
            detail = update_res.text or f"HTTP {update_res.status_code}"
            try:
                payload = update_res.json()
                if isinstance(payload, dict):
                    detail = payload.get("message") or payload.get("detail") or payload.get("error") or detail
            except Exception:
                pass
            raise HTTPException(status_code=502, detail=f"Metadata update failed: {detail}")

    return upload_data

