def _legacy_background_task_status() -> dict[str, Any]:
    is_running = False
    if "process" in running_tasks:
        process = running_tasks.get("process")
        if process is not None:
            poll_result = process.poll()
            if poll_result is None:
                is_running = True
            else:
                returncode = getattr(process, "returncode", poll_result)
                if returncode != 0:
                    error = f"Task exited with code {returncode}"
                    log_tail = _background_task_log_tail(str(running_tasks.get("log_path") or ""))
                    if log_tail:
                        error = f"{error}. Recent log:\n{log_tail}"
                    running_tasks["error"] = error
    return {
        "isRunning": is_running,
        "operation": running_tasks.get("operation"),
        "lastError": running_tasks.get("error"),
    }


def _current_background_task_status(
    *,
    site_id: str = "",
    scope: Optional[str] = None,
) -> dict[str, Any]:
    task = (
        background_task_manager.current(site_id=site_id, scope=scope)
        if site_id
        else background_task_manager.active()
    )
    if task is not None:
        return {
            "isRunning": task["status"] == "running",
            "isQueued": task["status"] == "queued",
            "operation": task["operation"],
            "taskId": task["id"],
            "runtimeId": task["runtimeId"],
            "queuePosition": task["queuePosition"],
            "lastError": task["lastError"],
            "lastWarning": task["lastWarning"],
        }
    legacy = _legacy_background_task_status()
    return {
        **legacy,
        "isQueued": False,
        "taskId": None,
        "runtimeId": background_task_manager.runtime_id,
        "queuePosition": 0,
        "lastWarning": None,
    }


