def _split_category_tokens(raw: str) -> list[str]:
    text = str(raw or "").strip()
    if not text:
        return []
    if text.startswith("|") and text.endswith("|"):
        return [p.strip() for p in text.strip("|").split("|") if p.strip()]
    if "|" in text:
        return [p.strip() for p in text.split("|") if p.strip()]
    return [p.strip() for p in text.split(",") if p.strip()]


def _product_category_name_slug(value: Any) -> str:
    return _blog_slugify(str(value or ""), fallback="category")


def _product_matches_category(item: dict[str, Any], category_slug: str) -> bool:
    target = str(category_slug or "").strip().lower()
    if not target:
        return True
    slugs = [slug.strip().lower() for slug in _split_category_tokens(item.get("category_slugs", ""))]
    if target in slugs:
        return True
    return any(_product_category_name_slug(name) == target for name in _split_category_tokens(item.get("category_names", "")))


def _get_product_tag_history(limit: int = 100, query: str = "") -> list[dict[str, Any]]:
    if not DB_PATH.exists():
        return []
    _ensure_product_category_columns()
    needle = str(query or "").strip().lower()
    counts: dict[str, dict[str, Any]] = {}
    try:
        with get_db_connection() as conn:
            rows = conn.execute("SELECT tag_names FROM product_items WHERE tag_names != ''").fetchall()
    except Exception:
        return []

    for row in rows:
        for name in _normalize_product_tag_names(row["tag_names"], limit=100):
            if needle and needle not in name.lower():
                continue
            key = name.lower()
            if key not in counts:
                counts[key] = {"name": name, "count": 0}
            counts[key]["count"] += 1

    items = list(counts.values())
    items.sort(key=lambda item: (-int(item["count"]), str(item["name"]).lower()))
    return items[: max(1, min(500, int(limit or 100)))]


PRODUCT_ISSUE_FLAG_KEYS = (
    "full_description_empty",
    "short_description_empty",
    "tag_names_empty",
    "acf_seo_extra_info_empty",
    "aioseo_title_missing_custom",
    "aioseo_description_missing_custom",
    "aioseo_title_uses_template_tag",
    "aioseo_description_uses_template_tag",
    "aioseo_title_is_default_or_empty",
    "aioseo_description_is_default_or_empty",
    "needs_attention",
    "generated_not_synced",
)
PRODUCT_CACHE_STALE_AFTER_SECONDS_DEFAULT = 24 * 60 * 60

PRODUCT_TEMPLATE_TOKEN_RE = re.compile(
    r"(#[a-z_][a-z0-9_-]*|%[a-z_][a-z0-9_-]*%|\{\{[^{}]+\}\}|\[[a-z_][a-z0-9_:-]*\])",
    re.IGNORECASE,
)


def _normalize_text(value: Any) -> str:
    return str(value or "").strip()


def _strip_html_for_issue_check(value: Any) -> str:
    text = unescape(str(value or ""))
    text = re.sub(r"<[^>]+>", " ", text)
    return re.sub(r"\s+", " ", text).strip()


def _product_cache_stale_after_seconds() -> int:
    raw = str(os.getenv("PRODUCT_CACHE_STALE_AFTER_SECONDS", "")).strip()
    if not raw:
        return PRODUCT_CACHE_STALE_AFTER_SECONDS_DEFAULT
    try:
        value = int(raw)
    except ValueError:
        return PRODUCT_CACHE_STALE_AFTER_SECONDS_DEFAULT
    return max(60, value)


def _parse_product_scan_timestamp(value: Any) -> Optional[datetime]:
    text = str(value or "").strip()
    if not text:
        return None
    try:
        parsed = datetime.fromisoformat(text.replace("Z", "+00:00"))
    except ValueError:
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)


def _format_product_scan_timestamp(value: datetime) -> str:
    return value.astimezone(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")


def _build_product_cache_info(
    items: Sequence[dict[str, Any]],
    *,
    now: Optional[datetime] = None,
    stale_after_seconds: Optional[int] = None,
) -> dict[str, Any]:
    current = (now or datetime.now(timezone.utc)).astimezone(timezone.utc)
    stale_after = (
        max(60, int(stale_after_seconds))
        if stale_after_seconds is not None
        else _product_cache_stale_after_seconds()
    )
    scanned_at = [
        parsed
        for parsed in (_parse_product_scan_timestamp(item.get("last_scanned_at")) for item in items)
        if parsed is not None
    ]
    missing_scanned_at_count = max(0, len(items) - len(scanned_at))
    if not scanned_at:
        return {
            "hasCache": False,
            "rowCount": len(items),
            "isStale": bool(items),
            "staleAfterSeconds": stale_after,
            "staleCount": 0,
            "missingScannedAtCount": missing_scanned_at_count,
            "latestLastScannedAt": "",
            "oldestLastScannedAt": "",
            "latestAgeSeconds": None,
            "oldestAgeSeconds": None,
        }

    latest = max(scanned_at)
    oldest = min(scanned_at)
    stale_count = sum(
        1
        for parsed in scanned_at
        if max(0, int((current - parsed).total_seconds())) > stale_after
    )
    latest_age = max(0, int((current - latest).total_seconds()))
    oldest_age = max(0, int((current - oldest).total_seconds()))
    return {
        "hasCache": True,
        "rowCount": len(items),
        "isStale": stale_count > 0 or missing_scanned_at_count > 0,
        "staleAfterSeconds": stale_after,
        "staleCount": stale_count,
        "missingScannedAtCount": missing_scanned_at_count,
        "latestLastScannedAt": _format_product_scan_timestamp(latest),
        "oldestLastScannedAt": _format_product_scan_timestamp(oldest),
        "latestAgeSeconds": latest_age,
        "oldestAgeSeconds": oldest_age,
    }


def _contains_template_tag_token(value: str) -> bool:
    text = _normalize_text(value)
    if not text:
        return False
    return PRODUCT_TEMPLATE_TOKEN_RE.search(text) is not None


def _extract_raw_aioseo_value(item: dict[str, Any], raw_key: str, fallback_key: str) -> tuple[str, bool]:
    # Raw columns expose AIOSEO template tags when the WooCommerce API returns them.
    # Some installs store custom values outside product meta, so the scanner may
    # only have the effective frontend value in the fallback column.
    raw_ready = int(item.get("raw_meta_scanned") or 0) == 1
    if raw_ready and raw_key in item:
        return _normalize_text(item.get(raw_key)), True
    # Backward compatibility for older DB schema: fallback to effective value.
    return _normalize_text(item.get(fallback_key)), False


def _aioseo_missing_custom_value(raw_value: str, has_raw_value: bool, effective_value: str) -> bool:
    if has_raw_value:
        return raw_value == "" and effective_value == ""
    return effective_value == ""


def _aioseo_uses_template_tag(raw_value: str, effective_value: str) -> bool:
    return _contains_template_tag_token(raw_value) or (
        raw_value == "" and _contains_template_tag_token(effective_value)
    )


def _build_product_issue_flags(item: dict[str, Any]) -> dict[str, bool]:
    enabled_fields = _active_profile_product_field_set()
    full_description_empty = _strip_html_for_issue_check(item.get("description")) == ""
    short_description_empty = _strip_html_for_issue_check(item.get("short_description")) == ""
    tag_names_empty = _strip_html_for_issue_check(item.get("tag_names")) == ""
    acf_seo_extra_info_empty = (
        "acf_seo_extra_info" in enabled_fields
        and _strip_html_for_issue_check(item.get("acf_seo_extra_info")) == ""
    )

    title_raw, has_title_raw = _extract_raw_aioseo_value(item, "aioseo_title_raw", "aioseo_title")
    desc_raw, has_desc_raw = _extract_raw_aioseo_value(item, "aioseo_description_raw", "aioseo_description")
    title_effective = _normalize_text(item.get("aioseo_title"))
    desc_effective = _normalize_text(item.get("aioseo_description"))

    aioseo_title_missing_custom = _aioseo_missing_custom_value(title_raw, has_title_raw, title_effective)
    aioseo_description_missing_custom = _aioseo_missing_custom_value(desc_raw, has_desc_raw, desc_effective)
    aioseo_title_uses_template_tag = _aioseo_uses_template_tag(title_raw, title_effective)
    aioseo_description_uses_template_tag = _aioseo_uses_template_tag(desc_raw, desc_effective)

    aioseo_title_is_default_or_empty = aioseo_title_missing_custom or aioseo_title_uses_template_tag
    aioseo_description_is_default_or_empty = (
        aioseo_description_missing_custom or aioseo_description_uses_template_tag
    )

    needs_attention = any(
        [
            "description" in enabled_fields and full_description_empty,
            "short_description" in enabled_fields and short_description_empty,
            "tag_names" in enabled_fields and tag_names_empty,
            acf_seo_extra_info_empty,
            "aioseo_title" in enabled_fields and aioseo_title_is_default_or_empty,
            "aioseo_description" in enabled_fields and aioseo_description_is_default_or_empty,
        ]
    )

    generated_not_synced = _normalize_text(item.get("status")) == "generated"

    return {
        "full_description_empty": "description" in enabled_fields and full_description_empty,
        "short_description_empty": "short_description" in enabled_fields and short_description_empty,
        "tag_names_empty": "tag_names" in enabled_fields and tag_names_empty,
        "acf_seo_extra_info_empty": acf_seo_extra_info_empty,
        "aioseo_title_missing_custom": "aioseo_title" in enabled_fields and aioseo_title_missing_custom,
        "aioseo_description_missing_custom": "aioseo_description" in enabled_fields and aioseo_description_missing_custom,
        "aioseo_title_uses_template_tag": "aioseo_title" in enabled_fields and aioseo_title_uses_template_tag,
        "aioseo_description_uses_template_tag": "aioseo_description" in enabled_fields and aioseo_description_uses_template_tag,
        "aioseo_title_is_default_or_empty": "aioseo_title" in enabled_fields and aioseo_title_is_default_or_empty,
        "aioseo_description_is_default_or_empty": "aioseo_description" in enabled_fields and aioseo_description_is_default_or_empty,
        "needs_attention": needs_attention,
        "generated_not_synced": generated_not_synced,
    }


def _annotate_product_issue_fields(item: dict[str, Any]) -> dict[str, Any]:
    out = dict(item)
    flags = _build_product_issue_flags(out)
    primary_group_order = [
        "full_description_empty",
        "short_description_empty",
        "tag_names_empty",
        "acf_seo_extra_info_empty",
        "aioseo_title_is_default_or_empty",
        "aioseo_description_is_default_or_empty",
        "aioseo_title_uses_template_tag",
        "aioseo_description_uses_template_tag",
    ]
    out["issue_flags"] = flags
    out["issue_groups"] = [k for k in primary_group_order if flags.get(k)]
    return out


