def _product_background_task_is_running() -> bool:
    try:
        site_id = _active_storage_site_id()
    except HTTPException:
        site_id = ""
    if site_id and background_task_manager.current(site_id=site_id, scope="product") is not None:
        return True
    proc = running_tasks.get("process")
    return bool(proc is not None and proc.poll() is None)


def _desktop_startup_grace_remaining_seconds() -> int:
    if not _truthy(os.getenv("SEO_WP_SYNC_DESKTOP_RUNTIME", "")):
        return 0
    raw = str(os.getenv("SEO_WP_SYNC_STARTUP_GRACE_SECONDS", "")).strip()
    try:
        grace_seconds = int(raw) if raw else DESKTOP_STARTUP_GRACE_SECONDS
    except ValueError:
        grace_seconds = DESKTOP_STARTUP_GRACE_SECONDS
    grace_seconds = max(0, grace_seconds)
    elapsed = max(0.0, time.monotonic() - APP_STARTED_AT_MONOTONIC)
    remaining = grace_seconds - elapsed
    return max(0, int(remaining + 0.999))


def _try_start_product_auto_scan_if_due(now: Optional[datetime] = None) -> dict[str, Any]:
    settings = _product_auto_scan_settings()
    if not settings["enabled"]:
        return {"started": False, "reason": "disabled", "settings": settings}
    startup_grace = _desktop_startup_grace_remaining_seconds()
    if startup_grace > 0:
        return {
            "started": False,
            "reason": "startup_grace",
            "retryAfterSeconds": startup_grace,
            "settings": settings,
        }
    if _product_background_task_is_running():
        return {"started": False, "reason": "busy", "settings": settings}

    rows = _load_product_cache_scan_rows()
    cache = _build_product_cache_info(
        rows,
        now=now,
        stale_after_seconds=int(settings["staleDays"]) * 24 * 60 * 60,
    )
    if not cache.get("hasCache"):
        return {"started": False, "reason": "no_cache", "settings": settings, "cache": cache}
    if not cache.get("isStale"):
        return {"started": False, "reason": "fresh", "settings": settings, "cache": cache}

    args = _node_cli_args("product-scan")
    start_task("product-scan", args, _build_product_task_env())
    return {"started": True, "reason": "stale", "settings": settings, "cache": cache}


def _product_auto_scan_scheduler_loop() -> None:
    while not product_auto_scan_scheduler_stop.is_set():
        try:
            result = _try_start_product_auto_scan_if_due()
            if result.get("started"):
                api_logger.info("[product-auto-scan] Started product-scan for stale product cache")
        except Exception:
            api_logger.exception("[product-auto-scan] Failed to evaluate stale product cache")

        settings = _product_auto_scan_settings()
        wait_seconds = max(5 * 60, int(settings.get("checkMinutes") or 60) * 60)
        product_auto_scan_scheduler_stop.wait(wait_seconds)


def _start_product_auto_scan_scheduler() -> None:
    global product_auto_scan_scheduler_thread
    if product_auto_scan_scheduler_thread and product_auto_scan_scheduler_thread.is_alive():
        return
    product_auto_scan_scheduler_stop.clear()
    product_auto_scan_scheduler_thread = threading.Thread(target=_product_auto_scan_scheduler_loop, daemon=True)
    product_auto_scan_scheduler_thread.start()


def _stop_product_auto_scan_scheduler() -> None:
    product_auto_scan_scheduler_stop.set()


def _normalize_issue_filters(raw: str) -> list[str]:
    tokens: list[str] = []
    for part in str(raw or "").split(","):
        key = part.strip()
        if key and key not in tokens:
            tokens.append(key)
    if not tokens:
        return []
    invalid = [k for k in tokens if k not in PRODUCT_ISSUE_FLAG_KEYS]
    if invalid:
        raise HTTPException(status_code=400, detail=f"Invalid issue filter: {', '.join(invalid)}")
    return tokens


SEO_REVIEW_STATUSES = {"pending", "approved", "rejected", "applied"}
MEDIA_SEO_FIELD_KEYS = ("filename", "title", "alt_text", "caption", "description")
MEDIA_SEO_METADATA_FIELD_KEYS = ("title", "alt_text", "caption", "description")
MEDIA_ISSUE_FLAG_KEYS = (
    "title_missing",
    "alt_text_missing",
    "caption_missing",
    "description_missing",
    "generated_not_synced",
    "processing_error",
    "needs_attention",
)


def _normalize_media_seo_text_value(value: Any, field_name: str) -> str:
    if isinstance(value, (dict, list, tuple, set)):
        raise HTTPException(status_code=400, detail=f"Invalid {field_name}: expected text")
    return str(value or "")


def _normalize_media_seo_filename_value(value: Any, fallback_filename: str) -> str:
    if isinstance(value, (dict, list, tuple, set)):
        raise HTTPException(status_code=400, detail="Invalid filename: expected text")
    return _normalize_ai_upload_filename(str(value or ""), fallback_filename, force_ext=".webp")


def _normalize_media_keyword_usage(value: Any) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise HTTPException(status_code=400, detail="Invalid keywordUsage: expected object")
    status = str(value.get("validationStatus") or "").strip()
    if status not in {"passed", "core-only", "inferred"}:
        raise HTTPException(status_code=400, detail="Invalid keywordUsage validationStatus")
    for field in ("candidateKeywords", "usedKeywords", "warnings"):
        if not isinstance(value.get(field, []), list):
            raise HTTPException(status_code=400, detail=f"Invalid keywordUsage {field}")
    normalized: dict[str, Any] = {
        "coreKeyword": str(value.get("coreKeyword") or "").strip(),
        "candidateKeywords": [str(item).strip() for item in value.get("candidateKeywords") or [] if str(item).strip()],
        "usedKeywords": [str(item).strip() for item in value.get("usedKeywords") or [] if str(item).strip()],
        "warnings": [str(item).strip() for item in value.get("warnings") or [] if str(item).strip()],
        "validationStatus": status,
    }
    if normalized["coreKeyword"] and (len(normalized["coreKeyword"]) < 2 or len(normalized["coreKeyword"]) > 60):
        raise HTTPException(status_code=400, detail="Invalid keywordUsage coreKeyword")
    return normalized


def _normalize_review_status(value: Any, field_name: str = "review_status") -> str:
    status = str(value or "").strip().lower()
    if status not in SEO_REVIEW_STATUSES:
        raise HTTPException(status_code=400, detail=f"Invalid {field_name}: {value}")
    return status


def _normalize_review_limit(value: Any, *, default: int = 100, max_limit: int = 300) -> int:
    try:
        clean = int(str(value if value is not None else default).strip() or default)
    except (TypeError, ValueError):
        raise HTTPException(status_code=400, detail=f"Invalid limit: {value}")
    return max(1, min(max_limit, clean))


def _build_media_issue_flags(item: dict[str, Any]) -> dict[str, bool]:
    title_missing = _normalize_text(item.get("title")) == ""
    alt_text_missing = _normalize_text(item.get("alt_text")) == ""
    caption_missing = _strip_html_for_issue_check(item.get("caption")) == ""
    description_missing = _strip_html_for_issue_check(item.get("description")) == ""
    gen_review_status = _normalize_text(item.get("gen_review_status"))
    generated_not_synced = bool(item.get("gen_seo_id")) and gen_review_status in {"pending", "approved"}
    processing_error = _normalize_text(item.get("status")) == "error"
    needs_attention = any(
        [
            title_missing,
            alt_text_missing,
            caption_missing,
            description_missing,
            generated_not_synced,
            processing_error,
        ]
    )
    return {
        "title_missing": title_missing,
        "alt_text_missing": alt_text_missing,
        "caption_missing": caption_missing,
        "description_missing": description_missing,
        "generated_not_synced": generated_not_synced,
        "processing_error": processing_error,
        "needs_attention": needs_attention,
    }


def _annotate_media_issue_fields(item: dict[str, Any]) -> dict[str, Any]:
    out = dict(item)
    flags = _build_media_issue_flags(out)
    order = [
        "title_missing",
        "alt_text_missing",
        "caption_missing",
        "description_missing",
        "generated_not_synced",
        "processing_error",
    ]
    out["issue_flags"] = flags
    out["issue_groups"] = [key for key in order if flags.get(key)]
    return out


def _normalize_media_issue_filters(raw: str) -> list[str]:
    tokens: list[str] = []
    for part in str(raw or "").split(","):
        key = part.strip()
        if key and key not in tokens:
            tokens.append(key)
    if not tokens:
        return []
    invalid = [k for k in tokens if k not in MEDIA_ISSUE_FLAG_KEYS]
    if invalid:
        raise HTTPException(status_code=400, detail=f"Invalid media issue filter: {', '.join(invalid)}")
    return tokens


def _normalize_media_seo_fields(raw: Any) -> list[str]:
    if raw is None:
        return list(MEDIA_SEO_FIELD_KEYS)
    if isinstance(raw, str):
        if not raw.strip():
            return list(MEDIA_SEO_FIELD_KEYS)
        values = [part.strip() for part in raw.split(",")]
    elif isinstance(raw, list):
        if not raw:
            return list(MEDIA_SEO_FIELD_KEYS)
        values = [str(part).strip() for part in raw]
    else:
        raise HTTPException(status_code=400, detail="Invalid media SEO fields: expected list or comma-separated text")
    fields: list[str] = []
    for value in values:
        if value and value not in fields:
            fields.append(value)
    if not fields:
        raise HTTPException(status_code=400, detail="No media SEO fields selected")
    invalid = [field for field in fields if field not in MEDIA_SEO_FIELD_KEYS]
    if invalid:
        raise HTTPException(status_code=400, detail=f"Invalid media SEO field: {', '.join(invalid)}")
    return fields


def _normalize_media_metadata_sync_fields(raw: Any) -> tuple[list[str], list[str]]:
    selected_fields = _normalize_media_seo_fields(raw)
    metadata_fields = [field for field in selected_fields if field in MEDIA_SEO_METADATA_FIELD_KEYS]
    unsupported_fields = [field for field in selected_fields if field not in MEDIA_SEO_METADATA_FIELD_KEYS]
    if not metadata_fields:
        raise HTTPException(
            status_code=400,
            detail=(
                "filename can be generated as a draft or used when uploading/replacing an image, "
                "but existing WordPress media filenames cannot be synced through the metadata API. "
                "Select title, alt_text, caption, or description to update WordPress metadata."
            ),
        )
    return metadata_fields, unsupported_fields


