@app.post("/daily-seo/runs/{run_id}/retry-failed")
def retry_failed_daily_seo_tasks(run_id: str):
    _recover_stale_daily_seo_runs()
    _ensure_daily_seo_tables()
    with get_db_connection() as conn:
        try:
            daily_seo_queue.get_daily_seo_run(conn, run_id)
        except KeyError:
            raise HTTPException(status_code=404, detail="Daily SEO run not found")
        current = daily_seo_queue.get_current_daily_seo_run(conn)
        if current and current.get("status") == "running":
            raise HTTPException(status_code=409, detail="A daily SEO run is already running")
        if not _daily_seo_has_runnable_tasks(conn, only_failed=True, source_run_id=run_id):
            raise HTTPException(status_code=400, detail="No failed daily SEO tasks to retry")
        run = daily_seo_queue.create_daily_seo_run(conn, only_failed=True, source_run_id=run_id)
    thread = threading.Thread(target=_run_daily_seo_background, args=(run["runId"], True), daemon=True)
    thread.start()
    return run


