@app.post("/products/{product_id}/detail-slices")
async def upload_product_detail_slices(
    product_id: int,
    files: List[UploadFile] = File(...),
    assetRole: str = Form("description_slice"),
    sectionKey: str = Form(""),
    sortOrder: int = Form(0),
):
    _ensure_daily_seo_tables()
    if not files:
        raise HTTPException(status_code=400, detail="No image files provided")
    assetRole = _normalize_product_detail_asset_role(assetRole)

    prepared_files: list[tuple[UploadFile, bytes, str]] = []
    for file in files:
        content_type = _validated_image_upload_content_type(file.filename or "file", file.content_type or "")
        data = await file.read()
        if not data:
            raise HTTPException(status_code=400, detail=f"{file.filename or 'file'} is empty")
        prepared_files.append((file, data, content_type))

    _ensure_product_category_columns()
    with get_db_connection() as conn:
        _assert_local_product_exists(conn, product_id)

    img_dir = Path(DB_PATH).parent / "product_ref_images" / str(product_id)
    img_dir.mkdir(parents=True, exist_ok=True)
    saved: list[dict[str, Any]] = []
    base_ts = int(time.time() * 1000)
    with get_db_connection() as conn:
        product_name = _product_name_for_upload_context(conn, product_id)
        used_filenames = {p.name.lower() for p in img_dir.iterdir() if p.is_file()}
        for idx, (file, data, content_type) in enumerate(prepared_files):
            ext = Path(file.filename or "image.png").suffix or ".png"
            safe_role = re.sub(r"[^a-zA-Z0-9_-]+", "-", assetRole or "description_slice").strip("-")
            ai_filename = _generate_ai_upload_filename_from_image(
                data,
                file.filename or f"{safe_role}_{base_ts + idx}{ext}",
                content_type or str(mimetypes.guess_type(file.filename or "")[0] or ""),
                main_keyword=" ".join(part for part in [product_name, sectionKey, assetRole] if part),
                extra_desc="Product detail slice local image upload.",
                force_ext=ext,
            )
            filename = _dedupe_upload_filename(
                _prefixed_ai_local_filename(
                    prefix=safe_role,
                    ai_filename=ai_filename,
                    fallback_filename=file.filename or f"{safe_role}_{base_ts + idx}{ext}",
                    content_type=content_type,
                    force_ext=ext,
                ),
                used_filenames,
                img_dir,
            )
            path = img_dir / filename
            path.write_bytes(data)
            saved.append(
                product_detail_slices.create_product_detail_slice(
                    conn,
                    product_id=product_id,
                    source_path=str(path),
                    asset_role=assetRole,
                    section_key=sectionKey,
                    sort_order=int(sortOrder or 0) + idx,
                )
            )
    return {"ok": True, "uploaded": len(saved), "images": saved}


