def _normalize_detail_slice_seo_batch_items(
    payload: ProductDetailSliceSeoBatchPayload,
) -> list[dict[str, Any]]:
    if not payload.items:
        raise HTTPException(status_code=400, detail="No detail slice batch items provided")
    items: list[dict[str, Any]] = []
    seen: set[tuple[int, int]] = set()
    shared_keyword = str(payload.keyword or "").strip()
    for raw in payload.items:
        product_id = int(raw.productId or 0)
        asset_id = int(raw.assetId or 0)
        if product_id <= 0 or asset_id <= 0:
            raise HTTPException(status_code=400, detail="Invalid detail slice batch item")
        key = (product_id, asset_id)
        if key in seen:
            continue
        seen.add(key)
        item_keyword = str(raw.keyword or "").strip() or shared_keyword
        items.append({"product_id": product_id, "asset_id": asset_id, "keyword": item_keyword})
    if not items:
        raise HTTPException(status_code=400, detail="No detail slice batch items provided")
    return items


def _detail_slice_snapshot(asset_id: int) -> Optional[dict[str, Any]]:
    try:
        with get_db_connection() as conn:
            return product_detail_slices.get_product_detail_slice(conn, int(asset_id))
    except Exception:
        return None


@app.post("/products/detail-slices/generate-seo-batch")
def generate_product_detail_slice_seo_batch(payload: ProductDetailSliceSeoBatchPayload):
    _ensure_daily_seo_tables()
    items = _normalize_detail_slice_seo_batch_items(payload)
    task_keys = [(int(item["product_id"]), str(item["asset_id"])) for item in items]
    item_by_key = {(int(item["product_id"]), str(item["asset_id"])): item for item in items}

    def _run_task(product_id: int, asset_key: str) -> dict[str, Any]:
        item = item_by_key[(int(product_id), str(asset_key))]
        asset_id = int(item["asset_id"])
        with get_db_connection() as conn:
            try:
                asset = product_detail_slices.get_product_detail_slice(conn, asset_id)
            except KeyError:
                raise RuntimeError(f"Detail slice not found: {asset_id}")
            if int(asset["productId"]) != int(product_id):
                raise RuntimeError("Detail slice not found for this product")
            product_name = _product_name_for_detail_slice_context(conn, int(product_id))

        processed = _process_product_assets(
            int(product_id),
            [asset_id],
            {"keyword": item["keyword"]},
            product_name,
            upload=False,
        )
        generated = processed[0] if processed else _detail_slice_snapshot(asset_id) or {}
        if str(generated.get("status") or "") == "failed":
            raise RuntimeError(str(generated.get("error") or "").strip() or f"Detail slice failed: {asset_id}")
        return generated

    def _make_failure(product_id: int, asset_key: str, error: BaseException) -> dict[str, Any]:
        asset_id = int(asset_key)
        snapshot = _detail_slice_snapshot(asset_id)
        message = _product_field_error_message(error)
        return {
            "productId": int(product_id),
            "assetId": asset_id,
            "status": str((snapshot or {}).get("status") or "failed"),
            "error": message,
            "image": snapshot,
        }

    results_map, failed, concurrency_stats = _run_adaptive_ai_batch_tasks(
        task_keys,
        _run_task,
        _make_failure,
        initial_concurrency=_get_ai_batch_concurrency(),
    )
    failures_by_key = {(int(item["productId"]), str(item["assetId"])): item for item in failed}
    results: list[dict[str, Any]] = []
    generated_count = 0
    for item in items:
        key = (int(item["product_id"]), str(item["asset_id"]))
        generated = results_map.get(key)
        if isinstance(generated, dict):
            generated_count += 1
            results.append(
                {
                    "productId": int(item["product_id"]),
                    "assetId": int(item["asset_id"]),
                    "ok": True,
                    "status": str(generated.get("status") or "seo_generated"),
                    "image": generated,
                }
            )
            continue
        failure = failures_by_key.get(key) or {
            "productId": int(item["product_id"]),
            "assetId": int(item["asset_id"]),
            "status": "failed",
            "error": "Detail slice SEO generation failed",
            "image": _detail_slice_snapshot(int(item["asset_id"])),
        }
        results.append(
            {
                "productId": int(item["product_id"]),
                "assetId": int(item["asset_id"]),
                "ok": False,
                "status": str(failure.get("status") or "failed"),
                "error": str(failure.get("error") or "Detail slice SEO generation failed"),
                "image": failure.get("image"),
            }
        )

    return {
        "ok": True,
        "requested": len(items),
        "generated": generated_count,
        "failed": len(failed),
        "results": results,
        "errors": failed[:20],
        "initial_concurrency": concurrency_stats["initial_concurrency"],
        "final_concurrency": concurrency_stats["final_concurrency"],
        "rate_limit_throttles": concurrency_stats["rate_limit_throttles"],
    }


def _require_reviewed_detail_slice_seo(asset: dict[str, Any]) -> None:
    required = {
        "filename": asset.get("seoFilename"),
        "title": asset.get("title"),
        "alt": asset.get("altText"),
        "caption": asset.get("caption"),
        "description": asset.get("description"),
    }
    missing = [label for label, value in required.items() if not str(value or "").strip()]
    if missing:
        raise HTTPException(
            status_code=400,
            detail=f"上传到 WordPress 前请先生成并审核图片 SEO。缺少字段：{', '.join(missing)}",
        )


@app.post("/products/{product_id}/detail-slices/{asset_id}/upload")
def upload_product_detail_slice_to_wp(product_id: int, asset_id: int):
    _ensure_daily_seo_tables()
    with get_db_connection() as conn:
        try:
            asset = product_detail_slices.get_product_detail_slice(conn, asset_id)
        except KeyError:
            raise HTTPException(status_code=404, detail="Detail slice not found")
        if asset["productId"] != product_id:
            raise HTTPException(status_code=404, detail="Detail slice not found for this product")
        _require_reviewed_detail_slice_seo(asset)
        product_name = f"Product #{product_id}"
        try:
            row = conn.execute("SELECT name FROM product_items WHERE id = ? LIMIT 1", (int(product_id),)).fetchone()
            if row is not None and str(row["name"] or "").strip():
                product_name = str(row["name"]).strip()
        except sqlite3.Error:
            pass
        try:
            upload = _upload_slice_image_to_wp(
                asset,
                {
                    "keyword": asset.get("altText") or asset.get("title") or product_name,
                    "productName": product_name,
                },
            )
        except Exception as exc:
            raise HTTPException(status_code=502, detail=str(exc))
        updated = product_detail_slices.update_product_detail_slice(
            conn,
            asset_id,
            {
                "wpMediaId": int(upload.get("wp_media_id") or upload.get("wpMediaId") or 0),
                "wpUrl": upload.get("wp_url") or upload.get("wpUrl") or "",
                "status": "uploaded",
                "error": "",
            },
        )

    source_path = Path(str(updated.get("sourcePath") or ""))
    if source_path.name and str(updated.get("wpUrl") or "").strip():
        try:
            _write_product_ref_image_wp_cache_entry(source_path.parent, source_path.name, str(updated["wpUrl"]))
        except Exception:
            pass
    return updated


