@app.get("/products")
def product_list(
    page: int = 1,
    limit: int = 20,
    q: str = "",
    category: str = "",
    issue: str = "",
):
    """List all scanned products from the database with pagination."""
    if not DB_PATH.exists():
        return {"items": [], "total": 0, "issue_summary": {}, "cache": _build_product_cache_info([])}
    try:
        _ensure_product_category_columns()
        page = max(1, page)
        limit = max(1, min(200, limit))
        offset = (page - 1) * limit
        keyword = q.strip()
        category_slug = category.strip().lower()
        issue_filters = _normalize_issue_filters(issue)
        with get_db_connection() as conn:
            c = conn.cursor()
            where_parts: list[str] = []
            where_args: list[Any] = []

            if keyword:
                where_parts.append("(name LIKE ? OR tag_names LIKE ?)")
                where_args.extend([f"%{keyword}%", f"%{keyword}%"])

            where_sql = f" WHERE {' AND '.join(where_parts)}" if where_parts else ""

            c.execute(
                f"""
                SELECT * FROM product_items{where_sql}
                ORDER BY datetime(NULLIF(updated_at, '')) DESC, id DESC
                """,
                tuple(where_args),
            )
            all_items = [_annotate_product_issue_fields(dict(row)) for row in c.fetchall()]
            if category_slug:
                all_items = [item for item in all_items if _product_matches_category(item, category_slug)]

            issue_summary_items = list(all_items)

            if issue_filters:
                all_items = [
                    item
                    for item in all_items
                    if any(bool(item.get("issue_flags", {}).get(flag)) for flag in issue_filters)
                ]

            total = len(all_items)
            items = all_items[offset: offset + limit]
            issue_summary = {
                key: sum(1 for item in issue_summary_items if bool(item.get("issue_flags", {}).get(key)))
                for key in PRODUCT_ISSUE_FLAG_KEYS
            }

            return {
                "items": items,
                "total": total,
                "issue_summary": issue_summary,
                "applied_issue_filters": issue_filters,
                "cache": _build_product_cache_info(all_items),
            }
    except HTTPException:
        raise
    except Exception:
        return {"items": [], "total": 0, "issue_summary": {}, "cache": _build_product_cache_info([])}


class ProductTemplatePayload(BaseModel):
    template: str = ""


def _read_user_product_template_file() -> str:
    if not PRODUCT_TEMPLATE_FILE.exists():
        return ""
    content = PRODUCT_TEMPLATE_FILE.read_text(encoding="utf-8").strip()
    content_hash = hashlib.sha256(content.encode("utf-8")).hexdigest()
    if content and content_hash == LEGACY_DEFAULT_PRODUCT_TEMPLATE_SHA256:
        PRODUCT_TEMPLATE_FILE.write_text("", encoding="utf-8")
        return ""
    return content


def _ensure_default_product_template_file() -> str:
    return _read_user_product_template_file()


@app.get("/product-template")
def get_product_template():
    """Get default product SEO template text."""
    try:
        content = _ensure_default_product_template_file()
        profile_template = _profile_product_template_text(_active_profile_template_pack())
        effective_template = "\n\n".join(part for part in (content, profile_template) if part)
        return {
            "template": effective_template,
            "path": str(CLIENT_PROFILES_FILE if profile_template else PRODUCT_TEMPLATE_FILE),
        }
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@app.put("/product-template")
def save_product_template(payload: ProductTemplatePayload):
    """Persist default product SEO template text."""
    template = (payload.template or "").strip()
    if not template:
        raise HTTPException(status_code=400, detail="Template cannot be empty")
    try:
        PRODUCT_TEMPLATE_FILE.parent.mkdir(parents=True, exist_ok=True)
        PRODUCT_TEMPLATE_FILE.write_text(template, encoding="utf-8")
        return {
            "ok": True,
            "path": str(PRODUCT_TEMPLATE_FILE),
        }
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


