def _upload_product_image_to_wp(
    *,
    filename: str,
    content: bytes,
    content_type: str,
    alt_text: str = "",
    ai_filename: str = "",
    filename_context: str = "",
) -> dict[str, Any]:
    creds = _resolve_cli_wp_credentials()
    wp_url = creds.get("wp_url", "").strip()
    wp_user = creds.get("wp_user", "").strip()
    wp_app_pass = creds.get("wp_app_pass", "").strip()
    if not wp_url or not wp_user or not wp_app_pass:
        raise HTTPException(
            status_code=400,
            detail=WP_CONFIG_REQUIRED_DETAIL,
        )

    original_filename = Path(filename or "product-image.jpg").name or "product-image.jpg"
    media_type = (
        _validated_image_upload_content_type(original_filename, content_type)
        or mimetypes.guess_type(original_filename)[0]
        or "image/jpeg"
    )
    safe_filename = _normalize_ai_upload_filename(
        ai_filename
        or _generate_ai_upload_filename_from_image(
            content,
            original_filename,
            media_type,
            main_keyword=filename_context or alt_text or Path(original_filename).stem,
        ),
        original_filename,
        media_type,
    )
    endpoint = f"{wp_url.rstrip('/')}/wp-json/wp/v2/media"

    resp = _http_request_with_proxy_fallback(
        "POST",
        endpoint,
        timeout=90,
        files={"file": (safe_filename, content, media_type)},
        auth=(wp_user, wp_app_pass),
    )
    if resp.status_code >= 400:
        detail = _response_detail(resp, f"WordPress media upload returned HTTP {resp.status_code}")
        raise HTTPException(status_code=502, detail=detail)

    data = resp.json()
    if not isinstance(data, dict) or not str(data.get("source_url") or "").strip():
        raise HTTPException(status_code=502, detail="WordPress did not return a media source_url")

    media_id = data.get("id")
    clean_alt = str(alt_text or "").strip()
    if media_id and clean_alt:
        try:
            _http_request_with_proxy_fallback(
                "POST",
                f"{endpoint}/{media_id}",
                timeout=30,
                json={"alt_text": clean_alt},
                auth=(wp_user, wp_app_pass),
            )
        except Exception:
            pass

    return {
        "id": media_id,
        "filename": safe_filename,
        "source_url": str(data.get("source_url") or "").strip(),
    }


def _normalize_upload_status(value: str) -> str:
    status = str(value or "").strip().lower()
    return status if status in {"draft", "publish", "pending", "private"} else "draft"


def _cache_uploaded_wc_product(product: dict[str, Any], item: ProductUploadPayload) -> None:
    product_id = product.get("id")
    if not isinstance(product_id, int) or not DB_PATH.exists():
        return

    try:
        _ensure_product_category_columns()
        with get_db_connection() as conn:
            exists = conn.execute(
                "SELECT name FROM sqlite_master WHERE type = 'table' AND name = 'product_items'"
            ).fetchone()
            if not exists:
                return

            category_slugs, category_names = _extract_wc_category_columns(product)
            tag_slugs, tag_names = _extract_wc_tags_columns(
                product,
                fallback_names=", ".join(_split_upload_tokens(item.tags)),
            )
            image_urls = [
                str(row.get("src") or "").strip()
                for row in (product.get("images") if isinstance(product.get("images"), list) else [])
                if isinstance(row, dict) and str(row.get("src") or "").strip()
            ]
            now = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())

            conn.execute(
                """
                INSERT INTO product_items (
                    id, name, slug, permalink, category_slugs, category_names,
                    tag_slugs, tag_names, image_urls, short_description, description,
                    acf_seo_extra_info, aioseo_title, aioseo_title_raw,
                    aioseo_description, aioseo_description_raw, raw_meta_scanned,
                    status, error_reason, updated_at, last_scanned_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1, 'uploaded', NULL, ?, ?)
                ON CONFLICT(id) DO UPDATE SET
                    name = excluded.name,
                    slug = excluded.slug,
                    permalink = excluded.permalink,
                    category_slugs = excluded.category_slugs,
                    category_names = excluded.category_names,
                    tag_slugs = excluded.tag_slugs,
                    tag_names = excluded.tag_names,
                    image_urls = excluded.image_urls,
                    short_description = excluded.short_description,
                    description = excluded.description,
                    acf_seo_extra_info = excluded.acf_seo_extra_info,
                    aioseo_title = excluded.aioseo_title,
                    aioseo_title_raw = excluded.aioseo_title_raw,
                    aioseo_description = excluded.aioseo_description,
                    aioseo_description_raw = excluded.aioseo_description_raw,
                    raw_meta_scanned = excluded.raw_meta_scanned,
                    status = excluded.status,
                    error_reason = NULL,
                    updated_at = excluded.updated_at,
                    last_scanned_at = excluded.last_scanned_at
                """,
                (
                    product_id,
                    str(product.get("name") or item.name).strip(),
                    str(product.get("slug") or item.slug).strip(),
                    str(product.get("permalink") or "").strip(),
                    category_slugs,
                    category_names,
                    tag_slugs,
                    tag_names,
                    json.dumps(image_urls, ensure_ascii=False) if image_urls else "",
                    item.short_description or str(product.get("short_description") or ""),
                    item.description or str(product.get("description") or ""),
                    item.acf_seo_extra_info,
                    item.aioseo_title,
                    item.aioseo_title,
                    item.aioseo_description,
                    item.aioseo_description,
                    now,
                    now,
                ),
            )
            conn.commit()
    except Exception as exc:
        print(f"[product-upload] cache skipped for product {product_id}: {exc}")


def _upload_product_to_wc(item: ProductUploadPayload) -> dict[str, Any]:
    name = str(item.name or "").strip()
    if not name:
        raise HTTPException(status_code=400, detail="请先填写产品名称。")

    wp_url, params, auth = _resolve_wc_write_context()
    payload: dict[str, Any] = {
        "name": name,
        "type": "simple",
        "status": _normalize_upload_status(item.status),
    }

    for field in ("slug", "sku", "regular_price", "sale_price", "short_description", "description"):
        value = str(getattr(item, field) or "").strip()
        if value:
            payload[field] = value

    category_names = _split_upload_tokens(item.categories)
    if category_names:
        category_ids = _get_or_create_wc_product_category_ids(
            wp_url=wp_url,
            params=params,
            auth=auth,
            names=category_names,
        )
        if category_ids:
            payload["categories"] = [{"id": category_id} for category_id in category_ids]

    tag_names = _split_upload_tokens(item.tags)
    if tag_names:
        tag_ids = _get_or_create_wc_product_tag_ids(
            wp_url=wp_url,
            params=params,
            auth=auth,
            names=tag_names,
        )
        if tag_ids:
            payload["tags"] = [{"id": tag_id} for tag_id in tag_ids]

    image_urls = _split_upload_tokens(item.images)
    if image_urls:
        payload["images"] = [{"src": url} for url in image_urls]

    meta_data: list[dict[str, str]] = []
    acf_value = str(item.acf_seo_extra_info or "").strip()
    if acf_value:
        meta_data.extend(
            [
                {"key": "short_description", "value": acf_value},
                {"key": "product_extra_info——seo", "value": acf_value},
            ]
        )
    aioseo_title = str(item.aioseo_title or "").strip()
    aioseo_desc = str(item.aioseo_description or "").strip()
    if aioseo_title:
        meta_data.append({"key": AIOSEO_PRODUCT_META_KEYS[0], "value": aioseo_title})
    if aioseo_desc:
        meta_data.append({"key": AIOSEO_PRODUCT_META_KEYS[1], "value": aioseo_desc})
    if meta_data:
        payload["meta_data"] = meta_data

    endpoint = f"{wp_url.rstrip('/')}/wp-json/wc/v3/products"
    resp = _http_request_with_proxy_fallback(
        "POST",
        endpoint,
        timeout=90,
        params=params,
        auth=auth,
        json=payload,
    )
    if resp.status_code >= 400:
        detail = _response_detail(resp, f"WooCommerce product create returned HTTP {resp.status_code}")
        raise HTTPException(status_code=502, detail=detail)

    product = resp.json()
    if not isinstance(product, dict) or not isinstance(product.get("id"), int):
        raise HTTPException(status_code=502, detail="WooCommerce did not return a created product ID")

    _cache_uploaded_wc_product(product, item)

    return {
        "ok": True,
        "id": product.get("id"),
        "name": product.get("name") or name,
        "permalink": product.get("permalink") or "",
        "status": product.get("status") or payload["status"],
        "warnings": [],
    }


@app.post("/products/upload")
def upload_product(payload: ProductUploadPayload):
    return _upload_product_to_wc(payload)


@app.post("/products/upload-images")
async def upload_product_images(
    files: List[UploadFile] = File(...),
    alt_text: str = Form(""),
):
    if not files:
        raise HTTPException(status_code=400, detail="No image files provided")
    if len(files) > 20:
        raise HTTPException(status_code=400, detail="Upload is limited to 20 images at a time")

    uploaded: list[dict[str, Any]] = []
    for file in files:
        content_type = _validated_image_upload_content_type(file.filename or "file", file.content_type or "")

        content = await file.read()
        if not content:
            raise HTTPException(status_code=400, detail=f"{file.filename or 'file'} is empty")

        uploaded.append(
            _upload_product_image_to_wp(
                filename=file.filename or "product-image",
                content=content,
                content_type=content_type,
                alt_text=alt_text,
                filename_context=alt_text,
            )
        )

    return {
        "ok": True,
        "images": uploaded,
        "urls": [item["source_url"] for item in uploaded],
    }


@app.post("/products/upload-batch")
def upload_products_batch(payload: ProductUploadBatchPayload):
    items = [item for item in payload.items if str(item.name or "").strip()]
    if not items:
        raise HTTPException(status_code=400, detail="No valid products provided")
    if len(items) > 200:
        raise HTTPException(status_code=400, detail="Batch upload is limited to 200 products at a time")

    results: list[dict[str, Any]] = []
    errors: list[dict[str, Any]] = []
    for index, item in enumerate(items, start=1):
        try:
            results.append({"row": index, **_upload_product_to_wc(item)})
        except Exception as exc:
            detail = exc.detail if isinstance(exc, HTTPException) else str(exc)
            errors.append({"row": index, "name": item.name, "detail": detail})

    return {
        "ok": len(errors) == 0,
        "uploaded": len(results),
        "failed": len(errors),
        "results": results,
        "errors": errors[:20],
    }


