def _ensure_local_product_ids_exist(ids: list[int]) -> None:
    if not DB_PATH.exists():
        raise HTTPException(status_code=404, detail="Database not found")
    _ensure_product_category_columns()
    placeholders = ",".join(["?"] * len(ids))
    with get_db_connection() as conn:
        rows = conn.execute(f"SELECT id FROM product_items WHERE id IN ({placeholders})", ids).fetchall()
    found_ids = {int(row["id"]) for row in rows}
    if any(product_id not in found_ids for product_id in ids):
        raise HTTPException(status_code=404, detail="Product items not found")


@app.post("/products/{product_id}/sync-seo")
def sync_product_seo(product_id: int, payload: Optional[ProductSingleSyncPayload] = None):
    """Sync one product's current local SEO fields to WooCommerce immediately."""
    if not DB_PATH.exists():
        raise HTTPException(status_code=404, detail="Database not found")
    _ensure_product_category_columns()

    try:
        with get_db_connection() as conn:
            c = conn.cursor()
            c.execute(
                """
                SELECT id, name, short_description, description,
                       acf_seo_extra_info, aioseo_title, aioseo_description,
                       slug, category_names, tag_names, tag_slugs,
                       image_urls, short_ref_images, full_ref_images
                FROM product_items
                WHERE id = ?
                """,
                (product_id,),
            )
            row = c.fetchone()
            if not row:
                raise HTTPException(status_code=404, detail="Product not found")
            item = dict(row)
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

    sync_fields = _normalize_product_sync_fields(payload.fields if payload else [])
    only_changed = True if payload is None else bool(payload.only_changed)
    sync_result = _sync_selected_product_fields_to_wp(
        product_id=product_id,
        item=item,
        fields=sync_fields,
        only_changed=only_changed,
    )

    if not bool(sync_result.get("skipped")):
        try:
            synced_fields_set = set(sync_result.get("synced_fields", []))
            with get_db_connection() as conn:
                c = conn.cursor()
                # Update status + reflect synced SEO values back into raw columns
                # so that issue badges re-evaluate correctly after sync.
                updates = [
                    "status = 'updated'",
                    "error_reason = NULL",
                    "updated_at = datetime('now')",
                ]
                params: list = []
                if "aioseo_title" in synced_fields_set:
                    updates.append("aioseo_title_raw = ?")
                    updates.append("aioseo_title = ?")
                    val = _normalize_text(item.get("aioseo_title"))
                    params.extend([val, val])
                if "aioseo_description" in synced_fields_set:
                    updates.append("aioseo_description_raw = ?")
                    updates.append("aioseo_description = ?")
                    val = _normalize_text(item.get("aioseo_description"))
                    params.extend([val, val])
                if "short_description" in synced_fields_set:
                    updates.append("short_description = ?")
                    params.append(item.get("short_description", ""))
                if "description" in synced_fields_set:
                    updates.append("description = ?")
                    params.append(item.get("description", ""))
                if "acf_seo_extra_info" in synced_fields_set:
                    updates.append("acf_seo_extra_info = ?")
                    params.append(item.get("acf_seo_extra_info", ""))
                if "tag_names" in synced_fields_set:
                    tag_slugs, tag_names = _extract_wc_tags_columns(
                        sync_result.get("remote", {}) if isinstance(sync_result, dict) else {},
                        fallback_names=str(item.get("tag_names") or ""),
                    )
                    updates.append("tag_slugs = ?")
                    updates.append("tag_names = ?")
                    params.extend([tag_slugs, tag_names])
                params.append(product_id)
                c.execute(
                    f"UPDATE product_items SET {', '.join(updates)} WHERE id = ?",
                    params,
                )
                conn.commit()
        except Exception:
            pass

    return {
        "ok": True,
        "product_id": product_id,
        "name": item.get("name", ""),
        "selected_fields": sync_fields,
        "synced_fields": sync_result.get("synced_fields", []),
        "skipped": bool(sync_result.get("skipped")),
        "synced_meta": _pick_product_meta(
            sync_result.get("remote", {}) if isinstance(sync_result, dict) else {},
            ["short_description", "product_extra_info——seo", "_aioseo_title", "_aioseo_description"],
        ),
    }


@app.post("/products/sync-seo-batch")
def sync_product_seo_batch(payload: ProductBatchSyncPayload):
    """Sync selected products' current local SEO fields to WooCommerce."""
    ids = _normalize_request_id_list(
        list(payload.ids),
        empty_detail="No valid product IDs provided",
        invalid_detail="Invalid product ID",
    )
    _ensure_local_product_ids_exist(ids)

    placeholders = ",".join(["?"] * len(ids))
    try:
        with get_db_connection() as conn:
            c = conn.cursor()
            c.execute(
                f"""
                SELECT id, name, short_description, description,
                       acf_seo_extra_info, aioseo_title, aioseo_description,
                       slug, category_names, tag_names, tag_slugs,
                       image_urls, short_ref_images, full_ref_images
                FROM product_items
                WHERE id IN ({placeholders})
                ORDER BY id ASC
                """,
                ids,
            )
            rows = [dict(r) for r in c.fetchall()]

            sync_fields = _normalize_product_sync_fields(payload.fields or [])
            only_changed = bool(payload.only_changed)
            applied = 0
            skipped = 0
            failed: list[dict[str, Any]] = []
            for item in rows:
                product_id = int(item["id"])
                try:
                    sync_result = _sync_selected_product_fields_to_wp(
                        product_id=product_id,
                        item=item,
                        fields=sync_fields,
                        only_changed=only_changed,
                    )
                    if bool(sync_result.get("skipped")):
                        skipped += 1
                    else:
                        # Update status + reflect synced values back into raw columns
                        synced_set = set(sync_result.get("synced_fields", []))
                        updates = [
                            "status = 'updated'",
                            "error_reason = NULL",
                            "updated_at = datetime('now')",
                        ]
                        upd_params: list = []
                        if "aioseo_title" in synced_set:
                            updates.append("aioseo_title_raw = ?")
                            updates.append("aioseo_title = ?")
                            val = _normalize_text(item.get("aioseo_title"))
                            upd_params.extend([val, val])
                        if "aioseo_description" in synced_set:
                            updates.append("aioseo_description_raw = ?")
                            updates.append("aioseo_description = ?")
                            val = _normalize_text(item.get("aioseo_description"))
                            upd_params.extend([val, val])
                        if "short_description" in synced_set:
                            updates.append("short_description = ?")
                            upd_params.append(item.get("short_description", ""))
                        if "description" in synced_set:
                            updates.append("description = ?")
                            upd_params.append(item.get("description", ""))
                        if "acf_seo_extra_info" in synced_set:
                            updates.append("acf_seo_extra_info = ?")
                            upd_params.append(item.get("acf_seo_extra_info", ""))
                        if "tag_names" in synced_set:
                            tag_slugs, tag_names = _extract_wc_tags_columns(
                                sync_result.get("remote", {}) if isinstance(sync_result, dict) else {},
                                fallback_names=str(item.get("tag_names") or ""),
                            )
                            updates.append("tag_slugs = ?")
                            updates.append("tag_names = ?")
                            upd_params.extend([tag_slugs, tag_names])
                        upd_params.append(product_id)
                        c.execute(
                            f"UPDATE product_items SET {', '.join(updates)} WHERE id = ?",
                            upd_params,
                        )
                        applied += 1
                except Exception as e:
                    msg = str(e)
                    c.execute(
                        """
                        UPDATE product_items
                        SET status = 'error',
                            error_reason = ?,
                            updated_at = datetime('now')
                        WHERE id = ?
                        """,
                        (msg[:500], product_id),
                    )
                    failed.append(
                        {
                            "product_id": product_id,
                            "name": item.get("name", ""),
                            "error": msg,
                        }
                    )
            conn.commit()

            return {
                "ok": True,
                "requested": len(ids),
                "found": len(rows),
                "applied": applied,
                "skipped": skipped,
                "failed": len(failed),
                "selected_fields": sync_fields,
                "only_changed": only_changed,
                "errors": failed[:10],
            }
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@app.put("/products/{product_id}")
def update_product(product_id: int, payload: ProductUpdatePayload):
    """Update product details in the local database."""
    if not DB_PATH.exists():
        raise HTTPException(status_code=404, detail="Database not found")
    _ensure_product_category_columns()
    try:
        with get_db_connection() as conn:
            c = conn.cursor()
            updates = []
            values = []
            if payload.short_description is not None:
                updates.append("short_description=?")
                values.append(payload.short_description)
            if payload.description is not None:
                updates.append("description=?")
                values.append(payload.description)
            if payload.short_ref_images is not None:
                updates.append("short_ref_images=?")
                values.append(payload.short_ref_images)
            if payload.full_ref_images is not None:
                updates.append("full_ref_images=?")
                values.append(payload.full_ref_images)
            if payload.acf_seo_extra_info is not None:
                updates.append("acf_seo_extra_info=?")
                values.append(payload.acf_seo_extra_info)
            if payload.aioseo_title is not None:
                updates.append("aioseo_title=?")
                values.append(payload.aioseo_title)
            if payload.aioseo_description is not None:
                updates.append("aioseo_description=?")
                values.append(payload.aioseo_description)
            if payload.catalog_text is not None:
                updates.append("catalog_text=?")
                values.append(payload.catalog_text)
            if payload.slug is not None:
                updates.append("slug=?")
                values.append(payload.slug)
            if payload.tag_names is not None:
                updates.append("tag_names=?")
                values.append(_normalize_product_tag_text(payload.tag_names, limit=20))
            if payload.tag_slugs is not None:
                updates.append("tag_slugs=?")
                values.append(payload.tag_slugs)
            
            if not updates:
                exists = c.execute("SELECT 1 FROM product_items WHERE id=? LIMIT 1", (product_id,)).fetchone()
                if not exists:
                    raise HTTPException(status_code=404, detail="Product not found")
                return {"ok": True}
                
            values.append(product_id)
            cursor = c.execute(f"UPDATE product_items SET {','.join(updates)} WHERE id=?", values)
            if cursor.rowcount == 0:
                raise HTTPException(status_code=404, detail="Product not found")
            conn.commit()
            return {"ok": True, "updated": cursor.rowcount}
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

