PRODUCT_SEO_KEYWORD_FIELDS = {
    "slug",
    "aioseo_title",
    "aioseo_description",
    "acf_seo_extra_info",
    "short_description",
    "description",
    "tag_names",
}


def _split_seo_keywords(seo_keywords: str) -> list[str]:
    import re

    keywords: list[str] = []
    seen: set[str] = set()
    for raw in re.split(r"[,，;\n]+", seo_keywords or ""):
        keyword = raw.strip()
        key = keyword.lower()
        if not keyword or key in seen:
            continue
        keywords.append(keyword)
        seen.add(key)
    return keywords


def _build_user_keywords_block(seo_keywords: str, field: str) -> str:
    keywords = _split_seo_keywords(seo_keywords)
    if not keywords or field not in PRODUCT_SEO_KEYWORD_FIELDS:
        return ""

    primary = keywords[0]
    secondary_keywords = keywords[1:8]
    secondary_block = ""
    if secondary_keywords:
        secondary_lines = "\n".join(f"- {keyword}" for keyword in secondary_keywords)
        secondary_block = f"""
Secondary keywords:
{secondary_lines}
"""

    placement_rules = {
        "slug": "- For slug: use the primary keyword once when it accurately identifies the product.",
        "aioseo_title": "- For aioseo_title: place the primary keyword within the FIRST 5 words.",
        "aioseo_description": "- For aioseo_description: place the primary keyword within the FIRST 60 characters.",
        "short_description": "- For short_description: include the primary keyword or a close natural variant where it fits naturally and factually.",
        "description": "- For description: include the primary keyword and 1-3 closely relevant secondary keywords where they fit naturally.",
        "acf_seo_extra_info": "- For acf_seo_extra_info: use the primary keyword or one closely relevant secondary keyword naturally in sentence 1 or 2. Do not force every keyword into the short card copy.",
        "tag_names": "- For tag_names: include the primary keyword as one tag if it is appropriate.",
    }

    return f"""
=== TARGET SEO KEYWORDS ===
Primary keyword: {primary}
{secondary_block}
Keyword usage rules for {field}:
- Use naturally and semantically; no stuffing.
- Use the closest natural variant when the exact phrase would sound awkward.
{placement_rules[field]}
=== END TARGET SEO KEYWORDS ===
"""


def _build_selected_keyword_context_block(keyword_context: str) -> str:
    text = str(keyword_context or "").strip()
    if not text:
        return ""
    return f"""
SELECTED PRODUCT KEYWORD DATABASE:
\"\"\"
{text[:20000]}
\"\"\"
Use this keyword database as category vocabulary. Prefer high-priority, product-specific, and audience-intent phrases where they fit naturally.
"""


_DEFAULT_MARKETING_TITLE_MAX_CHARS = 60
def _clean_marketing_list(value: Any) -> list[str]:
    if not isinstance(value, list):
        return []
    seen: set[str] = set()
    output: list[str] = []
    for item in value:
        text = re.sub(r"\s+", " ", str(item or "")).strip()
        if not text:
            continue
        key = text.lower()
        if key in seen:
            continue
        seen.add(key)
        output.append(text)
    return output


def _normalize_title_suffix(value: Any, brand_name: str = "") -> str:
    text = re.sub(r"\s+", " ", str(value or "")).strip()
    if not text and brand_name:
        text = brand_name
    label = re.sub(r"^\s*[|:-]\s*", "", text).strip()
    return f" | {label}" if label else ""


def _normalize_marketing_profile(profile: Optional[dict[str, Any]] = None) -> dict[str, Any]:
    data = profile if isinstance(profile, dict) else {}
    brand_name = re.sub(r"\s+", " ", str(data.get("brandName") or data.get("brand_name") or "")).strip()
    site_domain = re.sub(r"\s+", " ", str(data.get("siteDomain") or data.get("site_domain") or "")).strip()
    title_suffix = _normalize_title_suffix(data.get("titleBrandSuffix") or data.get("title_brand_suffix"), brand_name)
    try:
        title_max_chars = int(data.get("titleMaxChars") or data.get("title_max_chars") or _DEFAULT_MARKETING_TITLE_MAX_CHARS)
    except Exception:
        title_max_chars = _DEFAULT_MARKETING_TITLE_MAX_CHARS
    title_max_chars = max(20, min(title_max_chars, 1000))
    title_format = re.sub(r"\s+", " ", str(data.get("titleFormat") or data.get("title_format") or "")).strip()
    if not title_format:
        title_format = f"[Product Identity]{title_suffix}" if title_suffix else "[Product Identity]"
    return {
        "brandName": brand_name,
        "siteDomain": site_domain,
        "titleBrandSuffix": title_suffix,
        "titleMaxChars": title_max_chars,
        "productCategory": re.sub(r"\s+", " ", str(data.get("productCategory") or data.get("product_category") or "")).strip(),
        "audience": re.sub(r"\s+", " ", str(data.get("audience") or "")).strip(),
        "buyerIntent": re.sub(r"\s+", " ", str(data.get("buyerIntent") or data.get("buyer_intent") or "")).strip(),
        "procurementModifiers": _clean_marketing_list(data.get("procurementModifiers") or data.get("procurement_modifiers")),
        "industryTerms": _clean_marketing_list(data.get("industryTerms") or data.get("industry_terms")),
        "titleFormat": title_format,
    }


def _marketing_title_modifier_re(marketing_profile: Optional[dict[str, Any]] = None) -> Optional[re.Pattern[str]]:
    profile = _normalize_marketing_profile(marketing_profile)
    terms = [term for term in _clean_marketing_list(profile.get("procurementModifiers")) if len(term) >= 2]
    if not terms:
        return None
    pattern = "|".join(re.escape(term) for term in sorted(terms, key=len, reverse=True))
    return re.compile(rf"(?<![\w-])(?:{pattern})(?![\w-])", re.I)


def _strip_marketing_title_suffix(value: str, marketing_profile: Optional[dict[str, Any]] = None) -> str:
    profile = _normalize_marketing_profile(marketing_profile)
    text = re.sub(r"\s+", " ", str(value or "")).strip()
    labels = [
        re.sub(r"^\s*[|:-]\s*", "", profile["titleBrandSuffix"]).strip(),
        profile["brandName"],
    ]
    for label in [item for item in labels if item]:
        text = re.sub(rf"\s*[|:-]\s*{re.escape(label)}\s*$", "", text, flags=re.I).strip()
        text = re.sub(rf"\s+\b{re.escape(label)}\b\s*$", "", text, flags=re.I).strip()
    return text


def _clean_seo_title_base(value: Any, marketing_profile: Optional[dict[str, Any]] = None) -> str:
    text = _strip_prompt_artifact_labels(value)
    text = _strip_marketing_title_suffix(text, marketing_profile)
    text = re.sub(r"[|:;,()[\]{}]", " ", text)
    return re.sub(r"\s+", " ", text).strip()


def _remove_procurement_title_terms(value: Any, marketing_profile: Optional[dict[str, Any]] = None) -> str:
    text = _clean_seo_title_base(value, marketing_profile)
    pattern = _marketing_title_modifier_re(marketing_profile)
    if pattern:
        text = pattern.sub(" ", text)
    return re.sub(r"\s+", " ", text).strip(" |:;,-")


def _title_case_product_type(value: str) -> str:
    return " ".join(word.capitalize() for word in str(value or "").split())


def _product_type_from_context(marketing_profile: Optional[dict[str, Any]], *values: Any) -> str:
    profile = _normalize_marketing_profile(marketing_profile)
    combined = " ".join(_remove_procurement_title_terms(value, profile).lower() for value in values if value)
    patterns = [*_clean_marketing_list(profile.get("industryTerms"))]
    for value in values:
        for part in re.split(r"[,;|]+", str(value or "")):
            if part.strip():
                patterns.append(part.strip())
    for pattern in sorted((p for p in patterns if len(p.strip()) >= 4), key=len, reverse=True):
        clean_pattern = _remove_procurement_title_terms(pattern, profile).lower()
        if clean_pattern and clean_pattern in combined:
            return _title_case_product_type(clean_pattern)
    return ""


def _title_model_token(value: str) -> str:
    match = re.search(r"\b[A-Z]{1,5}-?\d[\w-]*\b", str(value or ""))
    return match.group(0) if match else ""


def _fit_seo_title(
    base: str,
    *,
    marketing_profile: Optional[dict[str, Any]] = None,
    required_type: str = "",
    max_chars: Optional[int] = None,
) -> str:
    profile = _normalize_marketing_profile(marketing_profile)
    suffix = profile["titleBrandSuffix"]
    max_chars = max(20, min(int(max_chars or profile["titleMaxChars"] or _DEFAULT_MARKETING_TITLE_MAX_CHARS), 1000))
    clean_base = re.sub(r"\s+", " ", str(base or "")).strip(" |:;,-")
    if not suffix:
        if len(clean_base) <= max_chars:
            return clean_base or "Product"
        trimmed = re.sub(r"\s+\S*$", "", clean_base[:max_chars]).strip(" |:;,-")
        if required_type and required_type.lower() not in trimmed.lower():
            model = _title_model_token(clean_base)
            compact = f"{model} {required_type}".strip()
            if compact and len(compact) <= max_chars:
                return compact
        return trimmed or "Product"
    title = f"{clean_base}{suffix}"
    if len(title) <= max_chars:
        return title
    max_base_len = max(1, max_chars - len(suffix))
    trimmed = re.sub(r"\s+\S*$", "", clean_base[:max_base_len]).strip(" |:;,-")
    if required_type and required_type.lower() not in trimmed.lower():
        model = _title_model_token(clean_base)
        compact = f"{model} {required_type}".strip()
        if len(f"{compact}{suffix}") <= max_chars:
            return f"{compact}{suffix}"
    return f"{trimmed or 'Product'}{suffix}"


def _enforce_seo_title(
    raw_title: Any,
    *,
    product_name: str = "",
    fallback_product_type: str = "",
    max_chars: Optional[int] = None,
    marketing_profile: Optional[dict[str, Any]] = None,
) -> str:
    profile = _normalize_marketing_profile(marketing_profile)
    raw_base = _clean_seo_title_base(raw_title, profile)
    title_modifier_re = _marketing_title_modifier_re(profile)
    preferred_source = product_name if title_modifier_re and title_modifier_re.search(raw_base) else raw_base
    required_type = _product_type_from_context(profile, fallback_product_type)
    base = (
        _remove_procurement_title_terms(preferred_source, profile)
        or _remove_procurement_title_terms(product_name, profile)
        or _remove_procurement_title_terms(fallback_product_type, profile)
        or "Product"
    )
    if required_type and required_type.lower() not in base.lower():
        base = f"{base} {required_type}".strip()
    return _fit_seo_title(
        base,
        marketing_profile=profile,
        required_type=required_type,
        max_chars=max_chars or profile["titleMaxChars"],
    )


def _build_marketing_context_block(scope: str = "product", marketing_profile: Optional[dict[str, Any]] = None) -> str:
    profile = _normalize_marketing_profile(marketing_profile)
    if scope == "media":
        title_rule = (
            f"Use product identity only: {profile['titleFormat']}. Keep configured title modifiers out."
            if profile["titleBrandSuffix"]
            else "Use product identity only. Do not append a brand unless the active site profile provides one."
        )
        field_contracts = f"""
- filename: Lowercase, hyphen-separated SEO filename ending in .webp. Use the product identity, not internal prompt labels.
- title: {title_rule}
- alt_text: Describe the visible image first, then include one natural product keyword or use-case phrase.
- caption: Short display line. It may include use context if it reads naturally.
- description: Search snippet grounded in visible/source evidence and user-provided keyword context.
""".strip()
    else:
        title_rule = (
            f"Use one strong product-specific search phrase and end with {profile['titleBrandSuffix']}. Avoid stacked configured title modifiers."
            if profile["titleBrandSuffix"]
            else "Use one strong product-specific search phrase. Do not append a brand unless the active site profile provides one."
        )
        field_contracts = f"""
- aioseo_title: {title_rule}
- aioseo_description: Use the primary keyword, a concrete benefit/spec, and source-supported use context within 160 characters.
- acf_seo_extra_info: Concise factual product-card support text. No CTA, no keyword stuffing.
- short_description: Valid WooCommerce HTML grounded in product facts and visible/reference material; structure comes only from the user's saved rule when present.
- description: Valid WooCommerce HTML grounded in product facts and visible/reference material; structure comes only from the user's saved rule when present.
- tag_names: Reusable taxonomy terms: product type, material, installation, application, and audience intent when factual.
""".strip()
    brand_site = " ".join(part for part in [profile["brandName"], f"({profile['siteDomain']})" if profile["siteDomain"] else ""] if part) or "(no brand configured)"
    product_category = profile["productCategory"] or "(not configured; use uploaded/source data only)"
    audience = profile["audience"] or "(not configured; infer only from source data)"
    buyer_intent = profile["buyerIntent"] or "(not configured; infer only from source data)"
    title_modifiers = ", ".join(profile["procurementModifiers"]) if profile["procurementModifiers"] else "(none configured)"
    industry_terms = ", ".join(profile["industryTerms"]) if profile["industryTerms"] else "(none configured; use uploaded/selected keyword context only)"
    return f"""
SEO MARKETING CONTEXT:
- Brand/site: {brand_site}
- Category: {product_category}
- Audience: {audience}
- Audience intent: {buyer_intent}
- Title format: "{profile["titleFormat"]}" (max {profile["titleMaxChars"]} chars)
- Title modifiers: {title_modifiers}
- Industry terms: {industry_terms}
- Field boundary: keep configured title modifiers out of title fields; route them to other fields only when user data supports them.
Field contracts:
{field_contracts}
""".strip()


def _build_seo_generation_brief_block(
    *,
    content_type: str,
    product_name: str = "",
    core_keyword: str = "",
    selected_fields: Optional[list[str]] = None,
    marketing_profile: Optional[dict[str, Any]] = None,
) -> str:
    profile = _normalize_marketing_profile(marketing_profile)
    fields = ", ".join(selected_fields or []) or "(all relevant SEO fields)"
    title_modifier_terms = ", ".join(profile["procurementModifiers"])
    modifier_rule = (
        f"Move {title_modifier_terms} terms out of title fields unless they are unavoidable in the exact product type. Use them in meta descriptions, captions, body copy, FAQ, and CTA context only when supported."
        if title_modifier_terms
        else "No title modifiers are configured; do not invent market/channel/company terms."
    )
    return f"""
SEO GENERATION BRIEF:
- Content type: {content_type}
- Product/source identity: {str(product_name or '').strip() or '(infer from source material)'}
- Core keyword: {str(core_keyword or '').strip() or '(choose the closest product-specific keyword)'}
- Selected fields: {fields}
- Title field contract: use "{profile["titleFormat"]}" when a brand suffix is configured; otherwise use a concise product-specific title. Keep it under {profile["titleMaxChars"]} characters.
- Title modifier routing: {modifier_rule}
- Quality bar: match search intent, use customer language, avoid keyword stuffing, and keep unsupported claims out.
""".strip()


def _strip_html(value: str) -> str:
    import re
    return re.sub(r"<[^>]+>", " ", value or "").strip()


def _strip_prompt_artifact_labels(value: Any) -> str:
    text = _strip_html(str(value or "")).strip()
    if text.startswith("```"):
        text = text.split("\n", 1)[1] if "\n" in text else text[3:]
    if text.endswith("```"):
        text = text[:-3]
    text = text.strip()
    if text.lower().startswith("json"):
        text = text[4:].strip()

    heading_re = re.compile(
        r"^=+\s*(?:target seo keywords?|end target seo keywords?|keyword strategy|output format)\s*=+$",
        re.I,
    )
    prefix_re = re.compile(
        r"^(?:batch core keyword|primary batch keyword|primary keyword guidance|primary keyword|"
        r"main keyword(?: to target)?|additional context|keyword usage rules)\s*:\s*",
        re.I,
    )
    drop_re = re.compile(r"^(?:secondary keywords|keyword placement strategy)\s*:?\s*$", re.I)

    cleaned: list[str] = []
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line or heading_re.match(line) or drop_re.match(line):
            continue
        line = prefix_re.sub("", line).strip()
        if line:
            cleaned.append(line)
    return "\n".join(cleaned).strip()


def _truncate(value: str, max_len: int) -> str:
    text = (value or "").strip()
    return text if len(text) <= max_len else text[:max_len].strip()


def _clean_trailing_seo_separator(value: str) -> str:
    return re.sub(r"\s*[|&:/,;\-]+\s*$", "", str(value or "").strip()).strip()


def _truncate_phrase_text(value: str, max_len: int) -> str:
    text = (value or "").strip()
    if not text:
        return ""
    if len(text) <= max_len:
        return _strip_dangling_phrase_tail(text)
    clipped = text[:max_len].rstrip()
    min_boundary = max(24, int(max_len * 0.55))
    boundary = -1
    for match in re.finditer(r"\s+", clipped):
        if match.start() >= min_boundary:
            boundary = match.start()
    if boundary >= min_boundary:
        candidate = clipped[:boundary].rstrip(" ,;:，；：-/")
        if candidate:
            return _strip_dangling_phrase_tail(_strip_dangling_summary_tail(candidate))
    return _strip_dangling_phrase_tail(clipped.rstrip(" ,;:，；：-/"))


BLOG_DANGLING_SUMMARY_WORDS = {
    "a", "an", "and", "as", "at", "by", "for", "from", "in", "into", "of",
    "on", "or", "the", "to", "with", "across", "featuring", "including",
    "covering", "through", "using", "via", "versus", "vs",
    "any", "either", "only",
    "wall", "wall-mounted", "mounted", "sensor", "automatic",
    "manual", "stainless", "steel", "reliable", "modern",
    "indicating",
}

BLOG_DANGLING_INFINITIVE_VERBS = {
    "boost", "compare", "enhance", "improve", "increase", "provide", "reduce",
    "simplify", "streamline", "support",
}

BLOG_DANGLING_REGION_WORDS = {
    "southeast", "southwest", "northeast", "northwest",
}


def _strip_unclosed_tail_fragment(value: str) -> str:
    text = (value or "").rstrip(" ,;:，；：-/&")
    for opener, closer in (("(", ")"), ("[", "]"), ("（", "）"), ("【", "】")):
        open_pos = text.rfind(opener)
        close_pos = text.rfind(closer)
        if open_pos >= 0 and open_pos > close_pos:
            candidate = text[:open_pos].rstrip(" ,;:，；：-/&")
            if candidate:
                text = candidate
    return text


def _strip_dangling_summary_tail(value: str) -> str:
    text = _strip_unclosed_tail_fragment(value)
    for _ in range(4):
        words = text.split()
        if not words:
            return ""
        last = re.sub(r"[^A-Za-z0-9+-]", "", words[-1]).lower()
        previous = re.sub(r"[^A-Za-z0-9+-]", "", words[-2]).lower() if len(words) > 1 else ""
        if not last:
            text = " ".join(words[:-1]).rstrip(" ,;:，；：-/&")
            continue
        if previous == "to" and last in BLOG_DANGLING_INFINITIVE_VERBS and len(words) > 2:
            text = " ".join(words[:-2]).rstrip(" ,;:，；：-/&")
            continue
        if last in BLOG_DANGLING_SUMMARY_WORDS or (last in BLOG_DANGLING_REGION_WORDS and previous in {"a", "an", "the"}):
            text = " ".join(words[:-1]).rstrip(" ,;:，；：-/&")
            continue
        break
    return text


IMAGE_DANGLING_PHRASE_ADJECTIVES = {"high-traffic", "ideal", "modern", "reliable"}
IMAGE_DANGLING_PHRASE_CONNECTORS = {"and", "any", "either", "for", "from", "in", "indicating", "of", "only", "or", "the", "to", "with"}


def _strip_dangling_phrase_tail(value: str) -> str:
    text = _strip_unclosed_tail_fragment(value)
    for _ in range(4):
        words = text.split()
        if not words:
            return ""
        last = re.sub(r"[^A-Za-z0-9+-]", "", words[-1]).lower()
        previous = re.sub(r"[^A-Za-z0-9+-]", "", words[-2]).lower() if len(words) > 1 else ""
        if last in IMAGE_DANGLING_PHRASE_CONNECTORS:
            text = " ".join(words[:-1]).rstrip(" ,;:，；：-/")
            continue
        if last in IMAGE_DANGLING_PHRASE_ADJECTIVES and (
            previous in IMAGE_DANGLING_PHRASE_CONNECTORS or re.search(r"[.!?。！？]$", words[-2])
        ):
            text = " ".join(words[:-1]).rstrip(" ,;:，；：-/")
            continue
        break
    return text


def _with_terminal_sentence_punctuation(value: str, max_len: int) -> str:
    text = (value or "").rstrip(" ,;:，；：-/&")
    if not text or re.search(r"[.!?。！？]$", text):
        return text
    if len(text) < max_len:
        return f"{text}."
    words = text.split()
    while len(words) > 1:
        words.pop()
        candidate = " ".join(words).rstrip(" ,;:，；：-/")
        if candidate and len(candidate) < max_len:
            return f"{candidate}."
    return text[: max(0, max_len - 1)].rstrip(" ,;:，；：-/") + "."


def _truncate_readable_text(value: str, max_len: int) -> str:
    text = (value or "").strip()
    if not text:
        return ""
    original_len = len(text)
    if len(text) > max_len:
        text = text[:max_len].rstrip()
    tail_safe = _strip_dangling_summary_tail(text)
    if tail_safe and tail_safe != text:
        text = tail_safe
        text = _with_terminal_sentence_punctuation(text, max_len)
    if re.search(r"[.!?。！？]$", text):
        tail_safe = _strip_dangling_summary_tail(text)
        if tail_safe and tail_safe != text:
            return _with_terminal_sentence_punctuation(tail_safe, max_len)
        return text
    if original_len < max_len:
        if original_len >= max_len - 16:
            return _with_terminal_sentence_punctuation(_strip_dangling_summary_tail(text), max_len)
        return _with_terminal_sentence_punctuation(text, max_len)

    min_boundary = max(24, int(max_len * 0.55))
    punctuation_positions = [match.end() for match in re.finditer(r"[.!?。！？;；:：]", text)]
    for pos in reversed(punctuation_positions):
        if pos >= min_boundary:
            return text[:pos].strip()

    boundary = -1
    for match in re.finditer(r"\s+", text):
        if match.start() >= min_boundary:
            boundary = match.start()
    if boundary >= min_boundary:
        candidate = text[:boundary].rstrip(" ,;:，；：-/")
        if candidate:
            return _with_terminal_sentence_punctuation(_strip_dangling_summary_tail(candidate), max_len)
    return _with_terminal_sentence_punctuation(_strip_dangling_summary_tail(text), max_len)


def _truncate_words(value: str, max_words: int) -> str:
    text = (value or "").strip()
    if not text:
        return ""
    words = [w for w in text.split() if w]
    if len(words) <= max_words:
        return " ".join(words)
    return " ".join(words[:max_words]).strip()


def _ensure_html(value: str, fallback: str = "") -> str:
    text = str(value or "").strip() or str(fallback or "").strip()
    if not text:
        return ""
    return text if re.search(r"<[^>]+>", text) else f"<p>{text}</p>"


def _parse_image_refs(value: Any) -> list[str]:
    if value is None:
        return []
    if isinstance(value, list):
        out = [str(v).strip() for v in value if str(v).strip()]
        return list(dict.fromkeys(out))

    text = str(value or "").strip()
    if not text:
        return []

    if text.startswith("[") and text.endswith("]"):
        try:
            parsed = json.loads(text)
            if isinstance(parsed, list):
                out = [str(v).strip() for v in parsed if str(v).strip()]
                return list(dict.fromkeys(out))
        except Exception:
            pass

    parts = re.split(r"[\r\n,]+", text)
    out = [p.strip() for p in parts if p.strip()]
    return list(dict.fromkeys(out))


def _pick_image_mime(source: str, content_type: str = "") -> str:
    ctype = (content_type or "").split(";")[0].strip().lower()
    if ctype.startswith("image/"):
        return ctype
    guessed, _ = mimetypes.guess_type(source)
    if guessed and guessed.startswith("image/"):
        return guessed
    return "image/jpeg"


def _load_image_inline_part(source: str, timeout: float = 20.0) -> Optional[dict[str, Any]]:
    src = str(source or "").strip()
    if not src:
        return None

    try:
        if src.startswith("file://"):
            local = Path(src.replace("file://", "", 1))
            if not local.exists() or not local.is_file():
                return None
            data = local.read_bytes()
            mime = _pick_image_mime(local.name)
        elif Path(src).is_absolute():
            local = Path(src)
            if not local.exists() or not local.is_file():
                return None
            data = local.read_bytes()
            mime = _pick_image_mime(local.name)
        elif src.startswith("http://") or src.startswith("https://"):
            resp = _http_request_with_proxy_fallback("GET", src, timeout=timeout, follow_redirects=True)
            if resp.status_code >= 400:
                return None
            data = resp.content
            mime = _pick_image_mime(src, resp.headers.get("content-type", ""))
        else:
            return None
    except Exception:
        return None

    if not data or len(data) > 5 * 1024 * 1024:
        return None
    if not str(mime).startswith("image/"):
        return None

    encoded = base64.b64encode(data).decode("ascii")
    return {"inlineData": {"mimeType": mime, "data": encoded}}


def _pick_file_mime(source: str, content_type: str = "") -> str:
    ctype = (content_type or "").split(";")[0].strip().lower()
    if ctype:
        return ctype
    suffix = Path(source or "").suffix.lower()
    if suffix in {".md", ".markdown"}:
        return "text/markdown"
    if suffix == ".csv":
        return "text/csv"
    if suffix in {".html", ".htm"}:
        return "text/html"
    if suffix == ".xlsx":
        return "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
    if suffix == ".xlsm":
        return "application/vnd.ms-excel.sheet.macroEnabled.12"
    if suffix == ".xls":
        return "application/vnd.ms-excel"
    guessed, _ = mimetypes.guess_type(source)
    return guessed or "application/octet-stream"


SUPPORTED_AI_INLINE_FILE_MIME_TYPES = frozenset({
    "application/pdf",
    "image/gif",
    "image/jpeg",
    "image/png",
    "image/webp",
})


def _is_supported_ai_inline_file_mime(mime_type: str) -> bool:
    normalized = str(mime_type or "").split(";", 1)[0].strip().lower()
    return normalized in SUPPORTED_AI_INLINE_FILE_MIME_TYPES


def _pick_ai_inline_file_mime(source: str, content_type: str = "") -> str:
    inferred = _pick_file_mime(source)
    if inferred != "application/octet-stream":
        return inferred
    return _pick_file_mime(source, content_type)


def _ai_inline_file_content_matches_mime(data: bytes, mime_type: str) -> bool:
    if mime_type == "application/pdf":
        return b"%PDF-" in data[:1024]
    if mime_type == "image/png":
        return data.startswith(b"\x89PNG\r\n\x1a\n")
    if mime_type == "image/jpeg":
        return data.startswith(b"\xff\xd8\xff")
    if mime_type == "image/gif":
        return data.startswith((b"GIF87a", b"GIF89a"))
    if mime_type == "image/webp":
        return len(data) >= 12 and data.startswith(b"RIFF") and data[8:12] == b"WEBP"
    return False


def _load_file_inline_part(source: Any, timeout: float = 20.0) -> Optional[dict[str, Any]]:
    if isinstance(source, dict):
        src = str(source.get("path") or source.get("source") or "").strip()
        content_type = str(source.get("contentType") or source.get("mimeType") or "").strip()
    else:
        src = str(source or "").strip()
        content_type = ""
    if not src:
        return None

    try:
        if src.startswith("file://"):
            local = Path(src.replace("file://", "", 1))
            if not local.exists() or not local.is_file():
                return None
            data = local.read_bytes()
            mime = _pick_ai_inline_file_mime(local.name, content_type)
        elif Path(src).is_absolute():
            local = Path(src)
            if not local.exists() or not local.is_file():
                return None
            data = local.read_bytes()
            mime = _pick_ai_inline_file_mime(local.name, content_type)
        elif src.startswith("http://") or src.startswith("https://"):
            resp = _http_request_with_proxy_fallback("GET", src, timeout=timeout, follow_redirects=True)
            if resp.status_code >= 400:
                return None
            data = resp.content
            mime = _pick_ai_inline_file_mime(src, content_type or resp.headers.get("content-type", ""))
        else:
            return None
    except Exception:
        return None

    if (
        not data
        or len(data) > MAX_KNOWLEDGE_FILE_BYTES
        or not _is_supported_ai_inline_file_mime(mime)
        or not _ai_inline_file_content_matches_mime(data, mime)
    ):
        return None
    encoded = base64.b64encode(data).decode("ascii")
    return {"inlineData": {"mimeType": mime, "data": encoded}}


_LONG_TAIL_CACHE: dict[str, list[str]] = {}


def _parse_suggest_response(data: Any) -> list[str]:
    if not isinstance(data, list) or len(data) < 2:
        return []
    values = data[1]
    if not isinstance(values, list):
        return []
    out: list[str] = []
    for val in values:
        if isinstance(val, str):
            text = val.strip()
            if text:
                out.append(text)
    return out


def _discover_long_tail_keywords(seed: str, language: str = "en", limit: int = 12) -> list[str]:
    root = str(seed or "").strip()
    if not root:
        return []

    cache_key = f"{language.lower()}::{root.lower()}"
    if cache_key in _LONG_TAIL_CACHE:
        return _LONG_TAIL_CACHE[cache_key][:limit]

    lang = (language or "en").split("-")[0].lower()
    variants = [root]

    found: list[str] = []
    for query in variants:
        q = quote_plus(query)
        urls = [
            f"https://suggestqueries.google.com/complete/search?client=firefox&hl={lang}&q={q}",
            f"https://api.bing.com/osjson.aspx?query={q}",
        ]
        for url in urls:
            try:
                resp = _http_request_with_proxy_fallback("GET", url, timeout=12, follow_redirects=True)
                if resp.status_code >= 400:
                    continue
                data = resp.json()
                for kw in _parse_suggest_response(data):
                    found.append(kw)
            except Exception:
                continue

    deduped: list[str] = []
    root_l = root.lower()
    for kw in found:
        norm = re.sub(r"\s+", " ", kw).strip()
        if not norm:
            continue
        if norm.lower() == root_l:
            continue
        if len(norm) < 6 or len(norm) > 120:
            continue
        if norm not in deduped:
            deduped.append(norm)

    _LONG_TAIL_CACHE[cache_key] = deduped[:50]
    return deduped[:limit]


def _parse_json_relaxed(raw: str) -> dict[str, Any]:
    text = str(raw or "").strip()
    if not text:
        return {}
    cleaned = re.sub(r"^```(?:json)?\s*|\s*```$", "", text, flags=re.IGNORECASE | re.DOTALL).strip()
    try:
        value = json.loads(cleaned)
        return value if isinstance(value, dict) else {}
    except Exception:
        pass

    start = cleaned.find("{")
    end = cleaned.rfind("}")
    if start >= 0 and end > start:
        try:
            value = json.loads(cleaned[start : end + 1])
            return value if isinstance(value, dict) else {}
        except Exception:
            return {}
    return {}


def _to_plain_text(value: Any) -> str:
    if value is None:
        return ""
    if isinstance(value, str):
        text = value
    elif isinstance(value, (int, float, bool)):
        text = str(value)
    elif isinstance(value, list):
        text = "; ".join(str(v) for v in value if str(v).strip())
    else:
        text = str(value)
    text = _strip_html(text)
    return re.sub(r"\s+", " ", text).strip()


def _to_plain_list(value: Any) -> list[str]:
    if isinstance(value, list):
        out = [_to_plain_text(v) for v in value]
    elif isinstance(value, str):
        out = [_to_plain_text(v) for v in re.split(r"[\r\n;]+", value)]
    else:
        out = []
    return [item for item in out if item]


def _safe_html_text(value: Any, fallback: str = "") -> str:
    text = _to_plain_text(value) or _to_plain_text(fallback)
    return escape(text, quote=True)



def _internal_link_url_key(url: Any) -> str:
    parsed = urlparse(str(url or "").strip())
    path = parsed.path.rstrip("/") or "/"
    return f"{parsed.netloc.lower()}{path}".strip()


def _upload_single_ref_image_to_wp(filepath: str, alt_text: str = "") -> str:
    """Upload a local image file to WordPress media library and return the source_url."""
    fpath = Path(filepath)
    if not fpath.exists() or not fpath.is_file():
        return ""

    creds = _resolve_cli_wp_credentials()
    wp_url = creds["wp_url"]
    wp_user = creds["wp_user"]
    wp_app_pass = creds["wp_app_pass"]

    if not wp_url or not wp_user or not wp_app_pass:
        return ""
    if _is_placeholder_wp_url(wp_url):
        print(f"[wp-upload] Refusing placeholder WordPress URL: {wp_url}")
        return ""

    endpoint = f"{wp_url.rstrip('/')}/wp-json/wp/v2/media"
    content_type = mimetypes.guess_type(str(fpath))[0] or "image/jpeg"

    file_bytes = fpath.read_bytes()
    if not file_bytes:
        return ""

    upload_filename = _generate_ai_upload_filename_from_image(
        file_bytes,
        fpath.name,
        content_type,
        main_keyword=alt_text or fpath.stem,
        extra_desc="Product reference image upload.",
    )
    files = {"file": (upload_filename, file_bytes, content_type)}

    resp = _http_request_with_proxy_fallback(
        "POST", endpoint, timeout=60,
        files=files, auth=(wp_user, wp_app_pass),
    )
    if resp.status_code >= 400:
        detail = resp.text or f"HTTP {resp.status_code}"
        try:
            payload = resp.json()
            if isinstance(payload, dict):
                detail = payload.get("message") or payload.get("detail") or payload.get("error") or detail
        except Exception:
            pass
        raise RuntimeError(f"WordPress media upload failed: {detail}")

    data = resp.json()
    if not isinstance(data, dict):
        raise RuntimeError("Invalid WordPress media upload response")
    media_id = int(data.get("id") or 0)
    if media_id <= 0:
        raise RuntimeError("WordPress media ID missing from upload response")
    source_url = str(data.get("source_url") or "").strip()
    if not source_url:
        raise RuntimeError("WordPress media source_url missing from upload response")

    if alt_text:
        update_resp = _http_request_with_proxy_fallback(
            "POST", f"{endpoint}/{media_id}", timeout=30,
            json={"alt_text": alt_text}, auth=(wp_user, wp_app_pass),
        )
        if update_resp.status_code >= 400:
            detail = update_resp.text or f"HTTP {update_resp.status_code}"
            try:
                payload = update_resp.json()
                if isinstance(payload, dict):
                    detail = payload.get("message") or payload.get("detail") or payload.get("error") or detail
            except Exception:
                pass
            raise RuntimeError(f"Metadata update failed: {detail}")

    print(f"[wp-upload] Uploaded {upload_filename} → {source_url}")
    return source_url


def _ensure_ref_images_uploaded_to_wp(product_id: int, product_name: str = "") -> list[str]:
    """Scan product_ref_images/{product_id}/, upload any new images to WP, return list of WP URLs.

    Cached in .wp_urls.json next to the images so each file is only uploaded once.
    """
    img_dir = Path(DB_PATH).parent / "product_ref_images" / str(product_id)
    if not img_dir.exists():
        return []

    cache_file = img_dir / ".wp_urls.json"
    cached: dict[str, str] = {}
    if cache_file.exists():
        try:
            cached = json.loads(cache_file.read_text())
        except Exception:
            cached = {}

    image_exts = {".jpg", ".jpeg", ".png", ".webp", ".gif", ".bmp"}
    wp_urls: list[str] = []
    updated = False

    for fpath in sorted(img_dir.iterdir()):
        if not fpath.is_file() or fpath.suffix.lower() not in image_exts:
            continue
        # Skip catalog images — they are AI-only context, not for HTML <img src>
        if fpath.name.startswith("catalog_"):
            continue
        if fpath.name in cached and cached[fpath.name]:
            wp_urls.append(cached[fpath.name])
        else:
            alt_text = f"{product_name} product detail" if product_name else ""
            wp_url = _upload_single_ref_image_to_wp(str(fpath), alt_text)
            if wp_url:
                cached[fpath.name] = wp_url
                wp_urls.append(wp_url)
                updated = True

    if updated:
        try:
            cache_file.write_text(json.dumps(cached, indent=2))
        except Exception:
            pass

    print(f"[wp-ref-upload] product_id={product_id}, found {len(wp_urls)} WP URLs for HTML <img src>")
    return wp_urls


def _reviewed_ref_image_wp_urls(product_id: int) -> list[str]:
    """Return already reviewed/uploaded product reference image URLs for HTML rendering."""
    try:
        _seed_product_detail_slices_from_ref_images(product_id)
        _ensure_daily_seo_tables()
        with get_db_connection() as conn:
            assets = product_detail_slices.list_product_detail_slices(
                conn,
                product_id=product_id,
                asset_role="description_slice",
            )
    except Exception:
        return []
    urls: list[str] = []
    for asset in assets:
        url = str(asset.get("wpUrl") or "").strip()
        if not url:
            continue
        if str(asset.get("status") or "").strip() != "uploaded":
            continue
        if url in urls:
            continue
        urls.append(url)
    return _public_html_image_urls(urls)


def _pick_image_url(images: list[str], index: int) -> str:
    if index < len(images):
        return images[index]
    return ""


def _public_html_image_urls(images: Optional[list[str]]) -> list[str]:
    urls: list[str] = []
    seen: set[str] = set()
    for value in images or []:
        url = str(value or "").strip()
        if not url:
            continue
        parsed = urlparse(url)
        if parsed.scheme not in ("http", "https") or not parsed.netloc:
            continue
        if url in seen:
            continue
        seen.add(url)
        urls.append(url)
    return urls


# Each entry: triggers, primary keyword file, optional list of extra files to merge
_CATEGORY_DETECTION: list[tuple[list[str], str, list[str]]] = []


def _detect_skills_keywords(product_text: str) -> str:
    """Return selected user keyword references when explicit detection rules exist."""
    text_lower = product_text.lower()
    kw_dir = SKILLS_DIR / "关键词" / "keywords"
    for triggers, primary_slug, extra_slugs in _CATEGORY_DETECTION:
        if any(t in text_lower for t in triggers):
            parts = []
            for slug in [primary_slug] + extra_slugs:
                kw_file = kw_dir / f"{slug}.md"
                if kw_file.exists():
                    parts.append(kw_file.read_text(encoding="utf-8")[:15000])
            if parts:
                merged = "\n\n---\n\n".join(parts)
                return (
                    f'\nCURATED KEYWORD REFERENCE for this product category:\n'
                    f'"""\n{merged}\n"""\n'
                    f'Use ⭐⭐⭐ priority keywords in title fields, ⭐⭐ in descriptions, ⭐ in details. Integrate naturally.\n'
                )
    return ""


def _normalize_acf_card_text(value: str, fallback_source: str, product_name: str) -> str:
    import re

    text = _strip_html(value or "").strip()
    fallback = _strip_html(fallback_source or "").strip() or (product_name or "").strip()

    if not text:
        text = fallback

    # Remove common CTA fragments that don't belong to subtitle-style copy.
    text = re.sub(
        r"(?i)\b(send inquiry now|get a quote|contact us|learn more|buy now|order now)\b",
        "",
        text,
    )
    text = re.sub(
        r"(?i)\b(best|top[-\s]?quality|premium|world[-\s]?class|perfect|ultimate|amazing|excellent)\b",
        "",
        text,
    )
    text = re.sub(r"\s+", " ", text).strip(" ,;")

    # Keep only the first 2-3 concise sentences for card copy.
    sentences = [s.strip() for s in re.split(r"(?<=[.!?])\s+", text) if s.strip()]
    if len(sentences) > 3:
        text = " ".join(sentences[:3]).strip()

    # Keep compact subtitle length, hard cap at 50 words.
    words = [w for w in text.split() if w]
    if len(words) < 18:
        text = fallback
    text = _truncate_words(text, 50)

    # Ensure proper ending punctuation for card subtitle readability.
    if text and text[-1] not in ".!?":
        text = f"{text}."
    return text


_GEMINI_MAX_RETRIES = 5
_GEMINI_RETRY_BASE_DELAY = 2  # seconds
_VERTEX_AI_DEFAULT_MIN_INTERVAL_SECONDS = 8.0
_VERTEX_AI_DEFAULT_RATE_LIMIT_COOLDOWN_SECONDS = 30.0
_AI_REQUEST_LOCK = threading.Lock()
_AI_NEXT_REQUEST_AT = 0.0
_VERTEX_TOKEN_REFRESH_MARGIN_SECONDS = 300
_VERTEX_AUTH_LOCK = threading.Lock()
_VERTEX_AUTH_TOKEN_CACHE: dict[str, Any] = {
    "cache_key": "",
    "token": "",
    "expires_at": 0.0,
}


def _ai_request_throttle_state_file() -> Path:
    raw = os.getenv("AI_REQUEST_THROTTLE_STATE_FILE", "").strip()
    path = Path(raw) if raw else Path(tempfile.gettempdir()) / "seo_wp_sync_ai_request_throttle.json"
    return path if path.is_absolute() else PROJECT_ROOT / path


def _ai_request_throttle_lock_dir() -> Path:
    raw = os.getenv("AI_REQUEST_THROTTLE_LOCK_DIR", "").strip()
    path = Path(raw) if raw else Path(f"{_ai_request_throttle_state_file()}.lock")
    return path if path.is_absolute() else PROJECT_ROOT / path


def _acquire_ai_request_throttle_lock() -> Path:
    lock_dir = _ai_request_throttle_lock_dir()
    lock_dir.parent.mkdir(parents=True, exist_ok=True)
    deadline = time.time() + 10.0
    while True:
        try:
            lock_dir.mkdir()
            return lock_dir
        except FileExistsError:
            try:
                if time.time() - lock_dir.stat().st_mtime > 30.0:
                    lock_dir.rmdir()
                    continue
            except OSError:
                pass
            if time.time() >= deadline:
                raise TimeoutError(f"Timed out waiting for AI request throttle lock: {lock_dir}")
            time.sleep(0.05)


def _release_ai_request_throttle_lock(lock_dir: Path) -> None:
    try:
        lock_dir.rmdir()
    except FileNotFoundError:
        pass
    except OSError:
        pass


def _read_ai_request_next_at() -> float:
    path = _ai_request_throttle_state_file()
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
        updated_wall_time = float(data.get("updated_wall_time") or 0.0)
        if updated_wall_time and time.time() - updated_wall_time > 86400:
            return 0.0
        value = data.get("next_request_at_ms")
        if value is None:
            legacy_value = float(data.get("next_request_at") or 0.0)
            value = legacy_value * 1000 if legacy_value < 10_000_000 else legacy_value
        return max(0.0, float(value or 0.0))
    except (OSError, ValueError, TypeError, json.JSONDecodeError):
        return 0.0


def _write_ai_request_next_at(next_request_at: float) -> None:
    path = _ai_request_throttle_state_file()
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(
            json.dumps(
                {
                    "next_request_at_ms": max(0.0, float(next_request_at)),
                    "updated_wall_time": time.time(),
                },
                ensure_ascii=False,
            ),
            encoding="utf-8",
        )
    except OSError:
        pass


def _get_ai_request_min_interval_seconds() -> float:
    raw = (
        os.getenv("AI_REQUEST_MIN_INTERVAL_SECONDS", "").strip()
        or os.getenv("VERTEX_AI_REQUEST_MIN_INTERVAL_SECONDS", "").strip()
    )
    try:
        value = float(raw) if raw else (_VERTEX_AI_DEFAULT_MIN_INTERVAL_SECONDS if _use_vertex_ai() else 1.5)
    except ValueError:
        value = _VERTEX_AI_DEFAULT_MIN_INTERVAL_SECONDS if _use_vertex_ai() else 1.5
    return max(0.0, min(value, 60.0))


def _get_vertex_ai_rate_limit_cooldown_seconds() -> float:
    if not _use_vertex_ai():
        return 0.0
    raw = os.getenv("VERTEX_AI_RATE_LIMIT_COOLDOWN_SECONDS", "").strip()
    try:
        value = float(raw) if raw else _VERTEX_AI_DEFAULT_RATE_LIMIT_COOLDOWN_SECONDS
    except ValueError:
        value = _VERTEX_AI_DEFAULT_RATE_LIMIT_COOLDOWN_SECONDS
    return max(0.0, min(value, 300.0))


def _clear_ai_request_rate_limit_state() -> None:
    global _AI_NEXT_REQUEST_AT
    with _AI_REQUEST_LOCK:
        _AI_NEXT_REQUEST_AT = 0.0
    lock_dir = _acquire_ai_request_throttle_lock()
    try:
        try:
            _ai_request_throttle_state_file().unlink()
        except FileNotFoundError:
            pass
    finally:
        _release_ai_request_throttle_lock(lock_dir)


def _wait_for_ai_request_slot() -> None:
    global _AI_NEXT_REQUEST_AT
    min_interval = _get_ai_request_min_interval_seconds()

    with _AI_REQUEST_LOCK:
        lock_dir = _acquire_ai_request_throttle_lock()
        try:
            now = time.monotonic()
            now_wall_ms = time.time() * 1000.0
            shared_next_request_at = _read_ai_request_next_at()
            memory_wait_seconds = max(0.0, _AI_NEXT_REQUEST_AT - now)
            shared_wait_seconds = max(0.0, (shared_next_request_at - now_wall_ms) / 1000.0)
            wait_seconds = max(memory_wait_seconds, shared_wait_seconds)
            _AI_NEXT_REQUEST_AT = now + wait_seconds + min_interval
            _write_ai_request_next_at(now_wall_ms + ((wait_seconds + min_interval) * 1000.0))
        finally:
            _release_ai_request_throttle_lock(lock_dir)

    if wait_seconds > 0:
        time.sleep(wait_seconds)


def _apply_ai_retry_cooldown(delay_seconds: float) -> None:
    global _AI_NEXT_REQUEST_AT
    if delay_seconds <= 0:
        return
    with _AI_REQUEST_LOCK:
        lock_dir = _acquire_ai_request_throttle_lock()
        try:
            cooldown_until = time.monotonic() + delay_seconds
            shared_cooldown_until = time.time() * 1000.0 + (delay_seconds * 1000.0)
            _AI_NEXT_REQUEST_AT = max(_AI_NEXT_REQUEST_AT, cooldown_until)
            _write_ai_request_next_at(max(_read_ai_request_next_at(), shared_cooldown_until))
        finally:
            _release_ai_request_throttle_lock(lock_dir)


def _retry_after_seconds(value: Optional[str]) -> Optional[float]:
    text = str(value or "").strip()
    if not text:
        return None
    try:
        return max(0.0, float(text))
    except ValueError:
        pass
    try:
        parsed = parsedate_to_datetime(text)
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone.utc)
        return max(0.0, parsed.timestamp() - time.time())
    except (TypeError, ValueError, OverflowError):
        return None


def _gemini_retry_delay_seconds(attempt: int, response: Optional[httpx.Response] = None) -> float:
    exponential = _GEMINI_RETRY_BASE_DELAY * (2 ** attempt)
    retry_after = _retry_after_seconds(response.headers.get("Retry-After")) if response is not None else None
    rate_limit_cooldown = (
        _get_vertex_ai_rate_limit_cooldown_seconds()
        if response is not None and response.status_code == 429
        else 0.0
    )
    retry_floor = retry_after if retry_after is not None else rate_limit_cooldown
    base_delay = max(exponential, retry_floor)
    jitter = random.uniform(0.0, min(1.0, max(0.0, base_delay * 0.1)))
    return base_delay + jitter


def _extract_gemini_text(data: dict) -> str:
    """Extract text from Gemini API response JSON."""
    candidates = data.get("candidates") or []
    if not candidates:
        return ""
    content = candidates[0].get("content") or {}
    text_parts = [
        str(p.get("text", "")).strip()
        for p in (content.get("parts") or [])
        if isinstance(p, dict)
    ]
    return "\n".join([t for t in text_parts if t]).strip()


def _gemini_http_post_with_retry(
    url: str,
    payload: dict,
    *,
    timeout: float = 90,
    headers: Optional[dict[str, str]] = None,
) -> dict:
    """POST to Gemini HTTP API with exponential-backoff retry on 429 / 5xx."""
    last_exc: Optional[Exception] = None
    last_status: Optional[int] = None
    for attempt in range(_GEMINI_MAX_RETRIES):
        try:
            _wait_for_ai_request_slot()
            resp = _httpx_request_with_proxy_fallback(
                "POST",
                url,
                timeout=timeout,
                follow_redirects=True,
                verify=True,
                apply_wp_rest_bypass=False,
                json=payload,
                headers=headers,
            )
            if resp.status_code == 429 or resp.status_code >= 500:
                last_status = resp.status_code
                if attempt >= _GEMINI_MAX_RETRIES - 1:
                    if resp.status_code == 429:
                        _apply_ai_retry_cooldown(_gemini_retry_delay_seconds(attempt, resp))
                    break
                delay = _gemini_retry_delay_seconds(attempt, resp)
                if resp.status_code == 429:
                    _apply_ai_retry_cooldown(delay)
                print(f"[Gemini] HTTP {resp.status_code}, retry {attempt + 1}/{_GEMINI_MAX_RETRIES} after {delay:.1f}s")
                time.sleep(delay)
                continue
            resp.raise_for_status()
            return resp.json()
        except httpx.HTTPStatusError:
            raise
        except Exception as e:
            last_exc = e
            if attempt >= _GEMINI_MAX_RETRIES - 1:
                break
            delay = _gemini_retry_delay_seconds(attempt)
            print(f"[Gemini] request error: {e}, retry {attempt + 1}/{_GEMINI_MAX_RETRIES} after {delay:.1f}s")
            time.sleep(delay)
    if last_status:
        raise RuntimeError(f"Gemini HTTP {last_status} after {_GEMINI_MAX_RETRIES} retries")
    raise last_exc or RuntimeError("Gemini API request failed after retries")


def _vertex_token_expiry_timestamp(expiry: Any) -> float:
    if isinstance(expiry, datetime):
        if expiry.tzinfo is None:
            expiry = expiry.replace(tzinfo=timezone.utc)
        return float(expiry.timestamp())
    return time.time() + 3000


def _refresh_vertex_access_token() -> tuple[str, float]:
    import google.auth
    from google.auth.transport.requests import Request

    credentials, _ = google.auth.default(
        scopes=["https://www.googleapis.com/auth/cloud-platform"]
    )
    try:
        credentials.refresh(Request())
    except Exception as exc:
        if not _should_retry_without_proxy(exc):
            raise
        import requests

        print(f"[Vertex] Proxy {_get_proxy_url()} failed during token refresh; retrying direct.")
        session = requests.Session()
        session.trust_env = False
        try:
            credentials.refresh(Request(session=session))
        finally:
            session.close()

    token = credentials.token
    if not token:
        raise RuntimeError("Unable to obtain Google Cloud access token for Vertex AI")
    return str(token), _vertex_token_expiry_timestamp(getattr(credentials, "expiry", None))


def _is_transient_vertex_auth_error(exc: BaseException) -> bool:
    seen: set[int] = set()
    pending: list[Optional[BaseException]] = [exc]
    while pending:
        current = pending.pop()
        if current is None:
            continue
        current_id = id(current)
        if current_id in seen:
            continue
        seen.add(current_id)

        message = str(current).lower()
        if any(
            token in message
            for token in (
                "connection",
                "eof occurred",
                "max retries exceeded",
                "proxyerror",
                "remote end closed",
                "server disconnected",
                "ssl",
                "temporarily unavailable",
                "timeout",
                "timed out",
            )
        ):
            return True

        pending.append(current.__cause__)
        pending.append(current.__context__)
    return False


def _get_vertex_access_token(credentials_path: str) -> str:
    cache_key = credentials_path or "google-auth-default"
    now = time.time()
    with _VERTEX_AUTH_LOCK:
        token = str(_VERTEX_AUTH_TOKEN_CACHE.get("token") or "")
        expires_at = float(_VERTEX_AUTH_TOKEN_CACHE.get("expires_at") or 0)
        if (
            token
            and _VERTEX_AUTH_TOKEN_CACHE.get("cache_key") == cache_key
            and expires_at - _VERTEX_TOKEN_REFRESH_MARGIN_SECONDS > now
        ):
            return token

        last_error: Optional[BaseException] = None
        for attempt in range(_GEMINI_MAX_RETRIES):
            try:
                token, expires_at = _refresh_vertex_access_token()
                break
            except BaseException as exc:
                last_error = exc
                if attempt >= _GEMINI_MAX_RETRIES - 1 or not _is_transient_vertex_auth_error(exc):
                    raise
                delay = _GEMINI_RETRY_BASE_DELAY * (2 ** attempt)
                print(
                    f"[Vertex] token refresh error: {exc}, "
                    f"retry {attempt + 1}/{_GEMINI_MAX_RETRIES} after {delay}s"
                )
                time.sleep(delay)
        else:
            raise last_error or RuntimeError("Unable to obtain Google Cloud access token for Vertex AI")

        _VERTEX_AUTH_TOKEN_CACHE.update(
            {
                "cache_key": cache_key,
                "token": token,
                "expires_at": expires_at,
            }
        )
        return token


def _clear_vertex_access_token_cache() -> None:
    with _VERTEX_AUTH_LOCK:
        _VERTEX_AUTH_TOKEN_CACHE.update({"cache_key": "", "token": "", "expires_at": 0.0})


def _vertex_generate_text(
    prompt: str,
    model_name: str = "gemini-2.5-flash",
    image_sources: Optional[list[str]] = None,
    file_sources: Optional[list[Any]] = None,
    timeout: float = 90,
) -> str:
    settings = _get_ai_provider_settings()
    model_name = _normalize_vertex_model_name(model_name)
    project = settings["project"]
    location = settings["location"] or "global"
    credentials_path = settings["credentials"]
    if not project:
        raise RuntimeError("Vertex AI 需要配置 GOOGLE_CLOUD_PROJECT。")
    if credentials_path:
        if not Path(credentials_path).is_file():
            raise RuntimeError(f"Service Account JSON 文件未找到：{credentials_path}")
        os.environ["GOOGLE_APPLICATION_CREDENTIALS"] = credentials_path

    token = _get_vertex_access_token(credentials_path)

    host = "https://aiplatform.googleapis.com" if location == "global" else f"https://{location}-aiplatform.googleapis.com"
    url = (
        f"{host}/v1/projects/{project}/locations/{location}/"
        f"publishers/google/models/{model_name}:generateContent"
    )
    parts: list[dict[str, Any]] = [{"text": prompt}]
    for source in (image_sources or [])[:16]:
        inline_part = _load_image_inline_part(source)
        if inline_part:
            parts.append(inline_part)
    for source in (file_sources or [])[:8]:
        inline_part = _load_file_inline_part(source)
        if inline_part:
            parts.append(inline_part)

    payload = {"contents": [{"role": "user", "parts": parts}]}
    data = _gemini_http_post_with_retry(
        url,
        payload,
        timeout=timeout,
        headers={
            "Authorization": f"Bearer {token}",
            "Content-Type": "application/json",
        },
    )
    return _extract_gemini_text(data)


def _raise_ai_error(exc: Exception) -> None:
    message = str(exc) or exc.__class__.__name__
    if isinstance(exc, httpx.HTTPStatusError):
        response = exc.response
        message = _response_detail(
            response,
            f"AI 服务返回 HTTP {response.status_code}。",
        )
        if response.status_code == 404 and (
            "publisher model" in message.lower()
            or "was not found" in message.lower()
            or "does not have access" in message.lower()
        ):
            raise HTTPException(
                status_code=404,
                detail=(
                    "Vertex AI 模型不可用：请检查模型 ID、Vertex 区域和当前 Google Cloud 项目权限。"
                    "如果要使用 Gemini 3.1 Pro，Vertex 模型 ID 应为 gemini-3.1-pro-preview。"
                ),
            )
        raise HTTPException(status_code=response.status_code, detail=message)
    raise HTTPException(status_code=502, detail=f"AI 服务调用失败：{message}")


def _require_ai_text(value: Any, label: str) -> str:
    text = str(value or "")
    if not text.strip():
        raise RuntimeError(f"AI provider returned empty {label}")
    return text


def _gemini_generate_text(
    api_key: str,
    prompt: str,
    model_name: str = "gemini-2.5-flash",
    image_sources: Optional[list[str]] = None,
    file_sources: Optional[list[Any]] = None,
    timeout: float = 90,
) -> str:
    if _use_vertex_ai():
        return _vertex_generate_text(
            prompt,
            model_name,
            image_sources=image_sources,
            file_sources=file_sources,
            timeout=timeout,
        )

    if not api_key:
        raise RuntimeError("未启用 Vertex AI 时，需要先配置 Gemini API Key。")

    image_sources = image_sources or []
    file_sources = file_sources or []
    if image_sources or file_sources:
        parts: list[dict[str, Any]] = [{"text": prompt}]
        for source in image_sources[:16]:
            inline_part = _load_image_inline_part(source)
            if inline_part:
                parts.append(inline_part)
        for source in file_sources[:8]:
            inline_part = _load_file_inline_part(source)
            if inline_part:
                parts.append(inline_part)

        url = (
            f"https://generativelanguage.googleapis.com/v1beta/models/"
            f"{model_name}:generateContent?key={api_key}"
        )
        payload = {"contents": [{"parts": parts}]}
        data = _gemini_http_post_with_retry(url, payload, timeout=timeout)
        return _extract_gemini_text(data)

    try:
        import google.generativeai as genai

        genai.configure(api_key=api_key)
        model = genai.GenerativeModel(model_name)
        try:
            response = model.generate_content(prompt, request_options={"timeout": timeout})
        except TypeError:
            response = model.generate_content(prompt)
        return (response.text or "").strip()
    except ModuleNotFoundError:
        url = (
            f"https://generativelanguage.googleapis.com/v1beta/models/"
            f"{model_name}:generateContent?key={api_key}"
        )
        payload = {
            "contents": [
                {
                    "parts": [{"text": prompt}],
                }
            ]
        }
        data = _gemini_http_post_with_retry(url, payload, timeout=timeout)
        return _extract_gemini_text(data)


def _ai_flash_model() -> str:
    return os.getenv("GENAI_FLASH_MODEL", "gemini-2.5-flash").strip() or "gemini-2.5-flash"


def _ai_pro_model() -> str:
    return (
        os.getenv("GENAI_PRO_MODEL", "").strip()
        or os.getenv("GENAI_FLASH_MODEL", "").strip()
        or "gemini-2.5-flash"
    )


def _strip_code_fence(value: str) -> str:
    text = (value or "").strip()
    if text.startswith("```"):
        text = text.split("\n", 1)[1] if "\n" in text else text[3:]
    if text.endswith("```"):
        text = text[:-3]
    text = text.strip()
    if text.lower().startswith("json"):
        text = text[4:].strip()
    return text


def _parse_ai_json_object(raw: str) -> dict[str, Any]:
    text = _strip_code_fence(raw)
    try:
        parsed = json.loads(text)
        return parsed if isinstance(parsed, dict) else {}
    except Exception:
        start = text.find("{")
        end = text.rfind("}")
        if start >= 0 and end > start:
            try:
                parsed = json.loads(text[start:end + 1])
                return parsed if isinstance(parsed, dict) else {}
            except Exception:
                return {}
    return {}


def _fallback_image_filename(filename: str, main_keyword: str = "") -> str:
    base = _strip_html(main_keyword or Path(filename or "image").stem or "image").lower()
    base = re.sub(r"[^a-z0-9]+", "-", base).strip("-") or "image"
    return f"{base}.webp"


_MEDIA_TITLE_FILLER_RE = re.compile(
    r"\b(?:orders?|projects?|purchase|solution|solutions|needs?)\b",
    re.I,
)
_MEDIA_MODEL_CODE_RE = re.compile(r"\b[A-Z]{1,5}\d?(?:[-_\s]?\d{1,5}[A-Z0-9]*)+\b")
_MEDIA_GENERIC_MODEL_RE = re.compile(r"^(?:IMG|DSC|PIC|PHOTO|IMAGE|PRODUCT)-?\d", re.I)
_MEDIA_DESCRIPTOR_STOP_WORDS = {
    "jpg",
    "jpeg",
    "png",
    "webp",
    "scaled",
    "copy",
    "image",
    "photo",
    "pic",
    "main",
    "front",
    "side",
    "back",
    "detail",
    "details",
    "view",
    "views",
    "scene",
}

def _media_title_case(value: str) -> str:
    words: list[str] = []
    for part in str(value or "").split():
        if len(part) > 1 and part.isupper():
            words.append(part)
        else:
            words.append(part[:1].upper() + part[1:].lower())
    return " ".join(words)


def _strip_media_title_brand(value: str, marketing_profile: Optional[dict[str, Any]] = None) -> str:
    return _strip_marketing_title_suffix(value, marketing_profile)


def _clean_media_title_product_phrase(value: Any, marketing_profile: Optional[dict[str, Any]] = None) -> str:
    text = _strip_prompt_artifact_labels(value)
    text = re.sub(r"\.[a-z0-9]+$", "", text, flags=re.I)
    text = re.sub(r"[_-]+", " ", text)
    text = re.sub(r"[|:;,()[\]{}]", " ", text)
    title_modifier_re = _marketing_title_modifier_re(marketing_profile)
    if title_modifier_re:
        text = title_modifier_re.sub(" ", text)
    text = _MEDIA_TITLE_FILLER_RE.sub(" ", text)
    text = re.sub(r"\s+", " ", text).strip()
    return _strip_media_title_brand(text, marketing_profile)


def _infer_media_title_product_type(
    parts: list[str],
    fallback: str = "",
    marketing_profile: Optional[dict[str, Any]] = None,
) -> str:
    profile = _normalize_marketing_profile(marketing_profile)
    combined = _clean_media_title_product_phrase(" ".join(str(part or "") for part in parts), profile).lower()
    patterns = [*profile["industryTerms"], fallback]
    for pattern in sorted((p for p in patterns if len(str(p or "").strip()) >= 4), key=len, reverse=True):
        clean_pattern = _clean_media_title_product_phrase(pattern, profile).lower()
        if clean_pattern and clean_pattern in combined:
            return _media_title_case(clean_pattern)
    fallback_phrase = _clean_media_title_product_phrase(fallback, profile)
    return _media_title_case(fallback_phrase) if fallback_phrase else "Product"


def _normalize_media_model_code(value: str) -> str:
    return re.sub(r"-+", "-", re.sub(r"[_\s]+", "-", value)).upper()


def _find_media_model_code(parts: list[str]) -> Optional[dict[str, Any]]:
    for source in parts:
        clean_source = re.sub(r"\.[a-z0-9]+$", "", _strip_prompt_artifact_labels(source), flags=re.I)
        for match in _MEDIA_MODEL_CODE_RE.finditer(clean_source):
            model = _normalize_media_model_code(match.group(0))
            if not _MEDIA_GENERIC_MODEL_RE.match(model):
                return {
                    "model": model,
                    "raw": match.group(0),
                    "source": clean_source,
                    "index": match.start(),
                }
    return None


def _extract_media_descriptor_after_model(model_match: Optional[dict[str, Any]], product_type: str) -> str:
    if not model_match:
        return ""
    product_words = {part.lower() for part in product_type.split() if part}
    rest = str(model_match["source"])[int(model_match["index"]) + len(str(model_match["raw"])):]
    rest = re.sub(r"\.[a-z0-9]+$", "", rest, flags=re.I)
    rest = re.sub(r"[_-]+", " ", rest)
    descriptor: list[str] = []
    for token in re.findall(r"[A-Za-z0-9]+", rest):
        lower = token.lower()
        if lower in product_words:
            break
        if lower in _MEDIA_DESCRIPTOR_STOP_WORDS:
            continue
        if re.match(r"^\d{4,}$", token):
            continue
        descriptor.append(token)
        if len(descriptor) >= 3:
            break
    return _media_title_case(" ".join(descriptor))


def _fit_media_title(base: str, marketing_profile: Optional[dict[str, Any]] = None) -> str:
    profile = _normalize_marketing_profile(marketing_profile)
    clean_base = _strip_media_title_brand(base, profile)
    title_modifier_re = _marketing_title_modifier_re(profile)
    if title_modifier_re:
        clean_base = title_modifier_re.sub(" ", clean_base)
    clean_base = re.sub(r"\s+", " ", clean_base).strip()
    return _fit_seo_title(clean_base or "Product", marketing_profile=profile)


def _enforce_media_title(
    raw: dict[str, Any],
    *,
    filename: str = "",
    main_keyword: str = "",
    marketing_profile: Optional[dict[str, Any]] = None,
) -> str:
    profile = _normalize_marketing_profile(marketing_profile)
    source_parts = [
        filename,
        str(_image_seo_raw_value(raw, "title") or ""),
        str(_image_seo_raw_value(raw, "alt_text") or ""),
        str(_image_seo_raw_value(raw, "caption") or ""),
        str(_image_seo_raw_value(raw, "description") or ""),
        main_keyword,
    ]
    product_type = _infer_media_title_product_type(source_parts, main_keyword or str(_image_seo_raw_value(raw, "title") or ""), profile)
    model_match = _find_media_model_code(source_parts)
    if not model_match:
        return _fit_media_title(product_type, profile)
    descriptor = _extract_media_descriptor_after_model(model_match, product_type)
    model_prefix = " ".join(part for part in [str(model_match["model"]), descriptor] if part).strip()
    return _fit_media_title(f"{model_prefix} {product_type}", profile)


def _normalize_image_seo(
    raw: dict[str, Any],
    *,
    filename: str = "",
    main_keyword: str = "",
    marketing_profile: Optional[dict[str, Any]] = None,
) -> dict[str, str]:
    fallback_name = _fallback_image_filename(filename, main_keyword)
    seed = _strip_prompt_artifact_labels(main_keyword or Path(filename or fallback_name).stem or "image") or "image"
    title = _enforce_media_title(raw or {"title": seed}, filename=filename, main_keyword=main_keyword, marketing_profile=marketing_profile)
    alt = _truncate_phrase_text(_strip_prompt_artifact_labels(_image_seo_raw_value(raw, "alt_text") or title) or title, 125)
    caption = _truncate_phrase_text(_strip_prompt_artifact_labels(_image_seo_raw_value(raw, "caption") or title) or title, 120)
    description = _truncate_readable_text(
        _strip_prompt_artifact_labels(_image_seo_raw_value(raw, "description") or title) or title,
        160,
    )
    out_filename = str(_image_seo_raw_value(raw, "filename") or fallback_name).strip() or fallback_name
    if not out_filename.lower().endswith(".webp"):
        out_filename = f"{Path(out_filename).stem or Path(fallback_name).stem}.webp"
    return {
        "filename": out_filename,
        "title": title,
        "alt": alt,
        "alt_text": alt,
        "caption": caption,
        "description": description,
    }


def _build_image_seo_prompt(
    *,
    main_keyword: str,
    extra_desc: str = "",
    keyword_context: str = "",
    company_context: str = "",
    text_context: Optional[dict[str, str]] = None,
    marketing_profile: Optional[dict[str, Any]] = None,
    keyword_candidates: Optional[list[dict[str, Any]]] = None,
    validation_feedback: str = "",
) -> str:
    profile = _normalize_marketing_profile(marketing_profile)
    text_context = text_context or {}
    source_block = ""
    if text_context:
        source_block = f"""
The original image bytes may be unavailable. Infer image intent from this context:
Filename: "{text_context.get('filename', '')}"
Current Title: "{text_context.get('currentTitle', '')}"
Current Alt: "{text_context.get('currentAlt', '')}"
Current Caption: "{text_context.get('currentCaption', '')}"
Current Description: "{text_context.get('currentDescription', '')}"
"""
    company_block = ""
    if company_context:
        company_block = f"""

COMPANY CONTEXT:
	\"\"\"
	{company_context[:15000]}
	\"\"\"
	Use company and product knowledge only when it is explicitly provided here."""
    keyword_block = ""
    if keyword_context:
        keyword_block = f"""
KEYWORD DATABASE:
\"\"\"
{keyword_context[:50000]}
\"\"\"
Use vocabulary from this database to optimize metadata. Use product-type vocabulary in the title, and move evidence-supported audience-intent modifiers into alt text, captions, and descriptions."""
    plan_source = " ".join(
        str(value or "")
        for value in [
            extra_desc,
            text_context.get("filename", ""),
            text_context.get("currentTitle", ""),
            text_context.get("currentAlt", ""),
            text_context.get("currentCaption", ""),
            text_context.get("currentDescription", ""),
        ]
    )
    product_keyword_plan_block = knowledge_plan.build_product_keyword_plan_block(
        product_name=main_keyword,
        source_text=plan_source,
        core_keyword=main_keyword,
        keyword_context=keyword_context,
    ) if main_keyword or keyword_context else ""
    marketing_context_block = _build_marketing_context_block("media", profile)
    seo_generation_brief_block = _build_seo_generation_brief_block(
        content_type="media",
        product_name=text_context.get("currentTitle", "") or text_context.get("filename", "") or main_keyword,
        core_keyword=main_keyword,
        selected_fields=["filename", "title", "alt_text", "caption", "description"],
        marketing_profile=profile,
    )
    extra_block = f"Additional Context: {extra_desc}" if extra_desc else ""
    keyword_instruction = (
        f"""Main Keyword to target: "{main_keyword}"."""
        if main_keyword
        else "No core keyword was provided. Inspect the provided image first, then infer the closest visible product type, model, features, and use case from the image and context."
    )
    candidate_rows = keyword_candidates or []
    candidate_block = f"""
MEDIA KEYWORD CONTRACT:
- The exact core keyword \"{main_keyword}\" must appear naturally in both filename and title.
- Use 1-3 phrases from this shortlist across alt, caption, and description when the shortlist is not empty:
{json.dumps(candidate_rows, ensure_ascii=False)}
- Return keywords_used, but the application will recompute actual usage from the final fields.
""" if main_keyword else ""
    feedback_block = (
        f"\nVALIDATION FAILED: {validation_feedback}\nRegenerate every field and correct this exact problem."
        if validation_feedback else ""
    )
    title_modifier_rule = (
        f'2. Keep configured title modifiers ({", ".join(profile["procurementModifiers"])}) out of the title unless they are part of the exact product name. Use them elsewhere only when supported by user data.'
        if profile["procurementModifiers"]
        else "2. No title modifiers are configured. Do not invent market, channel, or company terms."
    )
    return f"""You are an expert SEO specialist for the active website. Use only the active site profile, uploaded company knowledge, selected keyword database, and image/context evidence.{company_block}

Analyze the provided image or context and generate optimized WordPress media SEO metadata.
{keyword_instruction}
{extra_block}
{source_block}
{product_keyword_plan_block}
{marketing_context_block}
{seo_generation_brief_block}
{keyword_block}
{candidate_block}
{feedback_block}

Rules:
1. title: Media title, max {profile["titleMaxChars"]} characters, following the active site's SEO MARKETING CONTEXT. If no brand suffix is configured, do not append a brand.
{title_modifier_rule}
3. alt: Detailed accessibility text, max 125 characters.
4. caption: Brief display caption, max 120 characters.
5. description: Meta description for search results, max 160 characters.
6. filename: lowercase hyphen-separated .webp filename.
7. Avoid unsupported claims. If details are uncertain, describe visible product category and use case.
8. Do not copy WordPress placeholder tokens such as #image_title, #image_alt, or template labels into any field.
9. When only text context is available, treat Filename and Current Title as evidence only. Do not copy them verbatim, do not repeat model codes, and use any model code at most once in the title.

Return ONLY valid JSON:
{{"filename": "string.webp", "title": "string", "alt": "string", "caption": "string", "description": "string", "keywords_used": ["string"]}}"""


def _validated_image_seo_generation(
    *,
    main_keyword: str,
    keyword_candidates: list[dict[str, Any]],
    build_prompt: Callable[[str], str],
    image_sources: Optional[list[str]] = None,
    filename: str = "",
    marketing_profile: Optional[dict[str, Any]] = None,
) -> dict[str, Any]:
    feedback = ""
    for attempt in range(1, 3):
        raw = _gemini_generate_text(
            _get_gemini_api_key(),
            build_prompt(feedback),
            _ai_flash_model(),
            image_sources=image_sources,
        )
        try:
            parsed = _parse_ai_json_object(raw)
            _require_raw_image_seo_fields(parsed, ["filename", "title", "alt_text", "caption", "description"])
            normalized = _normalize_image_seo(
                parsed,
                filename=filename,
                main_keyword=main_keyword,
                marketing_profile=marketing_profile,
            )
            output = {**normalized, "alt_text": normalized["alt"]}
            usage = validate_keyword_usage(main_keyword, keyword_candidates, output)
            return {**normalized, "keywordUsage": usage}
        except (ValueError, RuntimeError, json.JSONDecodeError) as exc:
            feedback = str(exc)
            if attempt == 2:
                raise RuntimeError(f"Media SEO validation failed after 2 attempts: {feedback}") from exc
    raise RuntimeError("Media SEO validation failed after 2 attempts")


def _ai_status_probe_cache_key(settings: dict[str, str], provider: str, model: str) -> str:
    parts = [
        provider,
        model,
        settings.get("project", ""),
        settings.get("location", ""),
        settings.get("credentials", ""),
    ]
    return hashlib.sha256("\n".join(parts).encode("utf-8")).hexdigest()


def _get_cached_ai_status_probe(cache_key: str) -> Optional[dict[str, Any]]:
    with _ai_status_probe_lock:
        cached = dict(_ai_status_probe_cache.get(cache_key) or {})
    checked_at = float(cached.get("checked_at") or 0)
    if not checked_at:
        return None
    age = max(0, int(time.monotonic() - checked_at))
    if age > AI_STATUS_PROBE_CACHE_SECONDS:
        return None
    cached["probeAgeSeconds"] = age
    return cached


def _set_cached_ai_status_probe(cache_key: str, values: dict[str, Any]) -> dict[str, Any]:
    payload = dict(values)
    payload["checked_at"] = time.monotonic()
    payload["probeAgeSeconds"] = 0
    with _ai_status_probe_lock:
        _ai_status_probe_cache.clear()
        _ai_status_probe_cache[cache_key] = dict(payload)
    return payload


@app.get("/ai/status")
def ai_status(probe: bool = False):
    settings = _get_ai_provider_settings()
    provider = "vertex" if _use_vertex_ai() else "gemini"
    configured = _ai_configured()
    credentials_file_exists = None
    if provider == "vertex" and settings["credentials"]:
        credentials_file_exists = Path(settings["credentials"]).is_file()
    ready = configured and not (provider == "vertex" and credentials_file_exists is False)
    detail = ""
    if not configured:
        detail = _ai_missing_detail()
    elif provider == "vertex" and credentials_file_exists is False:
        detail = f"Service Account JSON 文件未找到：{settings['credentials']}"
    response: dict[str, Any] = {
        "ok": ready,
        "provider": provider,
        "configured": configured,
        "project": settings["project"] if provider == "vertex" else "",
        "location": settings["location"] if provider == "vertex" else "",
        "credentialsPath": settings["credentials"] if provider == "vertex" else "",
        "credentialsFileExists": credentials_file_exists,
        "model": _ai_flash_model(),
        "detail": detail,
        "verified": False,
        "probeAgeSeconds": None,
    }

    if not probe:
        return response

    if not ready:
        return response

    cache_key = _ai_status_probe_cache_key(settings, provider, str(response["model"]))
    cached = _get_cached_ai_status_probe(cache_key)
    if cached:
        response.update({
            "ok": bool(cached.get("ok")),
            "verified": bool(cached.get("verified")),
            "probeOk": bool(cached.get("probeOk")),
            "probeText": str(cached.get("probeText") or ""),
            "probeAgeSeconds": int(cached.get("probeAgeSeconds") or 0),
            "detail": str(cached.get("detail") or ""),
        })
        return response

    try:
        text = _gemini_generate_text(
            _get_gemini_api_key(),
            "Return exactly this text and nothing else: OK",
            _ai_flash_model(),
            timeout=AI_STATUS_PROBE_TIMEOUT_SECONDS,
        ).strip()
        response["probeOk"] = "OK" in text[:20].upper()
        response["probeText"] = text[:80]
        response["ok"] = bool(response["probeOk"])
        response["verified"] = bool(response["probeOk"])
        if not response["ok"]:
            response["detail"] = f"AI responded, but not with expected probe text: {text[:80]}"
    except Exception as exc:
        response["ok"] = False
        response["probeOk"] = False
        response["verified"] = False
        response["detail"] = str(exc)
    _set_cached_ai_status_probe(cache_key, {
        "ok": response["ok"],
        "verified": response["verified"],
        "probeOk": response.get("probeOk", False),
        "probeText": response.get("probeText", ""),
        "detail": response.get("detail", ""),
    })
    response["probeAgeSeconds"] = 0
    return response


