def _parse_marketing_profile_form(value: str = "") -> dict[str, Any]:
    text = str(value or "").strip()
    if not text:
        return {}
    try:
        parsed = json.loads(text)
        return parsed if isinstance(parsed, dict) else {}
    except Exception:
        return {}


def _optional_image_seo_core_keyword(value: Any) -> str:
    core_keyword = str(value or "").strip()
    if core_keyword and (len(core_keyword) < 2 or len(core_keyword) > 60):
        raise HTTPException(
            status_code=400,
            detail="AI media SEO mainKeyword must contain between 2 and 60 characters when provided.",
        )
    return core_keyword


@app.post("/ai/image-seo")
async def ai_image_seo(
    file: UploadFile = File(...),
    mainKeyword: str = Form(""),
    extraDesc: str = Form(""),
    keywordContext: str = Form(""),
    companyContext: str = Form(""),
    marketingProfile: str = Form(""),
    siteId: str = Form(""),
    keywordCategory: str = Form(""),
    keywordCandidates: str = Form(""),
):
    content_type = _validated_image_upload_content_type(file.filename or "file", file.content_type or "")
    core_keyword = _optional_image_seo_core_keyword(mainKeyword)
    if not _ai_configured():
        raise HTTPException(status_code=400, detail=_ai_missing_detail())

    import tempfile

    suffix = Path(file.filename or "image.webp").suffix or ".webp"
    tmp_path = ""
    try:
        data = await file.read()
        if not data:
            raise HTTPException(status_code=400, detail="Empty image file")
        with tempfile.NamedTemporaryFile(delete=False, suffix=suffix) as tmp:
            tmp.write(data)
            tmp_path = tmp.name

        candidate_text = keywordCandidates if isinstance(keywordCandidates, str) else ""
        clean_site_id = siteId if isinstance(siteId, str) else ""
        clean_keyword_category = keywordCategory if isinstance(keywordCategory, str) else ""
        try:
            supplied_candidates = json.loads(candidate_text) if candidate_text.strip() else []
        except json.JSONDecodeError:
            supplied_candidates = []
        candidates = supplied_candidates if isinstance(supplied_candidates, list) else []
        profile = _parse_marketing_profile_form(marketingProfile)
        resolved_context = _resolve_request_generation_context(
            site_id=clean_site_id,
            task_type="media",
            core_keyword=core_keyword,
            keyword_category=clean_keyword_category,
            target_text=f"{file.filename or ''} {extraDesc}",
            selected_fields=MEDIA_SEO_FIELD_KEYS,
            legacy_keyword_context=keywordContext,
            legacy_company_context=companyContext,
        )
        if not candidates:
            candidates = [{"keyword": keyword} for keyword in resolved_context.get("supportingKeywords") or []]
        result = _validated_image_seo_generation(
            main_keyword=core_keyword,
            keyword_candidates=candidates,
            build_prompt=lambda feedback: _build_image_seo_prompt(
                main_keyword=core_keyword,
                extra_desc=extraDesc,
                keyword_context=str(resolved_context.get("keywordContext") or ""),
                company_context=str(resolved_context.get("companyContext") or ""),
                marketing_profile=profile,
                keyword_candidates=candidates,
                validation_feedback=feedback,
            ),
            image_sources=[tmp_path],
            filename=file.filename or "",
            marketing_profile=profile,
        )
        result["generationContext"] = _generation_summary_with_usage(resolved_context, result.get("keywordUsage"))
        return result
    except HTTPException:
        raise
    except Exception as exc:
        _raise_ai_error(exc)
    finally:
        if tmp_path:
            try:
                Path(tmp_path).unlink(missing_ok=True)
            except Exception:
                pass


@app.post("/ai/image-seo-text")
def ai_image_seo_text(payload: ImageSeoTextPayload):
    main_keyword = _optional_image_seo_core_keyword(payload.mainKeyword)
    if not _ai_configured():
        raise HTTPException(status_code=400, detail=_ai_missing_detail())
    text_context = {
            "filename": payload.filename,
            "currentTitle": payload.currentTitle,
            "currentAlt": payload.currentAlt,
            "currentCaption": payload.currentCaption,
            "currentDescription": payload.currentDescription,
        }
    resolved_context = _resolve_request_generation_context(
        site_id=payload.siteId,
        task_type="media",
        core_keyword=main_keyword,
        keyword_category=payload.keywordCategory,
        target_text=" ".join(str(value or "") for value in text_context.values()),
        selected_fields=MEDIA_SEO_FIELD_KEYS,
        legacy_keyword_context=payload.keywordContext,
        legacy_company_context=payload.companyContext,
    )
    candidates = list(payload.keywordCandidates or []) or [
        {"keyword": keyword} for keyword in resolved_context.get("supportingKeywords") or []
    ]
    try:
        result = _validated_image_seo_generation(
            main_keyword=main_keyword,
            keyword_candidates=candidates,
            build_prompt=lambda feedback: _build_image_seo_prompt(
                main_keyword=main_keyword,
                extra_desc=payload.extraDesc,
                keyword_context=str(resolved_context.get("keywordContext") or ""),
                company_context=str(resolved_context.get("companyContext") or ""),
                text_context=text_context,
                marketing_profile=payload.marketingProfile,
                keyword_candidates=candidates,
                validation_feedback=feedback,
            ),
            filename=payload.filename,
            marketing_profile=payload.marketingProfile,
        )
        result["generationContext"] = _generation_summary_with_usage(resolved_context, result.get("keywordUsage"))
        return result
    except Exception as exc:
        _raise_ai_error(exc)


