def _build_company_prompt(company_context: str = "") -> str:
    if not company_context:
        return ""
    return f"""

COMPANY & SEO KNOWLEDGE BASE:
\"\"\"
{company_context[:30000]}
\"\"\"

Rules from the knowledge base:
- Write for the active website and its uploaded company profile.
- Target the audience described by the active site's knowledge base and current brief.
- Use priority keywords naturally without stuffing.
- Emphasize only claims, services, and differentiators supported by uploaded knowledge.
"""


BLOG_STOPWORDS = {
    "about", "after", "also", "and", "are", "can", "for", "from", "has", "have",
    "how", "into", "its", "more", "not", "our", "that", "the", "their", "this",
    "with", "your", "you", "what", "when", "where", "which", "will", "why",
    "product", "products", "blog", "page",
}

BLOG_TAG_STOPWORDS = BLOG_STOPWORDS | {
    "an", "as", "at", "be", "best", "by", "guide", "in", "is", "of", "on",
    "open", "or", "to", "using",
}

BLOG_TAG_PATTERNS: list[tuple[str, str]] = []

BLOG_TAG_ANCHOR_WORDS = {
    "application", "assembly", "audience", "capacity",
    "case", "catalog", "certificate", "certification",
    "compatibility", "compliance", "custom", "delivery",
    "feature", "installation", "maintenance", "material",
    "project", "quality", "replacement",
    "service", "specification", "support",
}


def _blog_plain_text(value: Any) -> str:
    text = str(value or "")
    text = re.sub(r"<!--[\s\S]*?-->", " ", text)
    text = re.sub(r"<script\b[\s\S]*?</script>", " ", text, flags=re.I)
    text = re.sub(r"<style\b[\s\S]*?</style>", " ", text, flags=re.I)
    text = re.sub(r"<br\s*/?>", " ", text, flags=re.I)
    text = re.sub(r"<[^>]+>", " ", text)
    return re.sub(r"\s+", " ", unescape(text)).strip()


def _blog_clean_tag_name(value: Any) -> str:
    text = _blog_plain_text(value).lower()
    text = text.replace("&", " and ")
    text = re.sub(r"[/_]+", " ", text)
    text = re.sub(r"[^a-z0-9+\-\s]", " ", text)
    text = re.sub(r"\s+", " ", text).strip(" -")
    text = re.sub(r"^(?:how to|what is|guide to|a guide to|best)\s+", "", text)
    text = re.sub(r"\s+", " ", text).strip(" -")
    words = text.split()
    if not words:
        return ""
    if len(words) > 6 or len(text) > 60:
        return ""
    if all(word in BLOG_TAG_STOPWORDS for word in words):
        return ""
    if len(words) == 1 and words[0] not in {"exhibition", "certificate", "certification", "project"}:
        return ""
    return text


def _blog_add_tag_candidate(out: list[str], seen: set[str], value: Any, limit: int) -> None:
    name = _blog_clean_tag_name(value)
    if not name:
        return
    key = name.lower()
    if key in seen:
        return
    seen.add(key)
    out.append(name)


def _blog_split_tag_seed(value: Any) -> list[str]:
    if value is None:
        return []
    if isinstance(value, list):
        raw_items = value
    else:
        raw_items = re.split(r"[\n,;|]+", str(value or ""))
    return [str(item or "").strip() for item in raw_items if str(item or "").strip()]


def _blog_known_phrase_candidates(text: str) -> list[str]:
    lowered = _blog_plain_text(text).lower()
    if not lowered:
        return []
    return [tag for tag, pattern in BLOG_TAG_PATTERNS if re.search(pattern, lowered, flags=re.I)]


def _blog_tag_tokens(text: str) -> list[str]:
    clean = _blog_plain_text(text).lower()
    clean = clean.replace("&", " and ")
    clean = re.sub(r"[^a-z0-9+\-\s]", " ", clean)
    tokens = [token for token in re.split(r"\s+", clean) if token]
    return [token for token in tokens if token not in BLOG_TAG_STOPWORDS and len(token) > 1]


def _blog_ngram_tag_candidates(text: str, max_candidates: int = 12) -> list[str]:
    tokens = _blog_tag_tokens(text)
    out: list[str] = []
    seen: set[str] = set()
    for size in (4, 3, 2):
        for index in range(0, max(0, len(tokens) - size + 1)):
            phrase_tokens = tokens[index:index + size]
            if not any(token in BLOG_TAG_ANCHOR_WORDS for token in phrase_tokens):
                continue
            phrase = _blog_clean_tag_name(" ".join(phrase_tokens))
            if not phrase or phrase in seen:
                continue
            seen.add(phrase)
            out.append(phrase)
            if len(out) >= max_candidates:
                return out
    return out


def _blog_auto_tag_names(
    *,
    title: str = "",
    explicit_keywords: str = "",
    content: str = "",
    seo_title: str = "",
    seo_description: str = "",
    excerpt: str = "",
    keyword_context: str = "",
    related_products: str = "",
    related_categories: str = "",
    article_type: str = "",
    limit: int = 10,
) -> list[str]:
    out: list[str] = []
    seen: set[str] = set()
    clean_limit = max(1, min(20, int(limit or 10)))

    for seed in _blog_split_tag_seed(explicit_keywords):
        _blog_add_tag_candidate(out, seen, seed, clean_limit)
        if len(out) >= clean_limit:
            return out

    source_blocks = [
        title,
        seo_title,
        seo_description,
        excerpt,
        related_products,
        related_categories,
        content,
        keyword_context[:5000],
    ]
    for block in source_blocks:
        for phrase in _blog_known_phrase_candidates(block):
            _blog_add_tag_candidate(out, seen, phrase, clean_limit)
            if len(out) >= clean_limit:
                return out

    article_type = _blog_clean_tag_name(article_type)
    if article_type in {"exhibition", "certificate", "project", "video"}:
        _blog_add_tag_candidate(out, seen, article_type, clean_limit)

    ngram_source = "\n".join(str(block or "") for block in source_blocks[:7])
    for phrase in _blog_ngram_tag_candidates(ngram_source):
        _blog_add_tag_candidate(out, seen, phrase, clean_limit)
        if len(out) >= clean_limit:
            return out

    return out[:clean_limit]


BLOG_REPAIR_MODES = {"format", "seo", "content"}
BLOG_CONTENT_THIN_WORD_LIMIT = 900
BLOG_SEO_ISSUE_FILTERS = {"", "missing_blog_seo", "missing_blog_tags", "missing_blog_schema"}


def _clean_blog_repair_mode(value: str) -> str:
    clean = str(value or "format").strip().lower()
    return clean if clean in BLOG_REPAIR_MODES else "format"


def _clean_blog_content_action(value: str) -> str:
    clean = str(value or "plan").strip().lower()
    return "draft" if clean == "draft" else "plan"


def _clean_blog_issue_filter(value: str) -> str:
    return str(value or "").strip()


def _blog_status(state: str, label: str) -> dict[str, str]:
    return {"state": state, "label": label}


def _blog_content_issue_codes(summary: dict[str, Any]) -> list[str]:
    word_count = int(summary.get("wordCount") or 0)
    return ["thin_blog_content"] if 0 < word_count < BLOG_CONTENT_THIN_WORD_LIMIT else []


def _blog_content_status(summary: dict[str, Any]) -> dict[str, str]:
    word_count = int(summary.get("wordCount") or 0)
    if 0 < word_count < 500:
        return _blog_status("missing", "内容太薄")
    if 0 < word_count < BLOG_CONTENT_THIN_WORD_LIMIT:
        return _blog_status("warning", "可继续加深")
    return _blog_status("ok", "内容深度 OK")


def _blog_first_text_value(row: dict[str, Any], keys: list[str]) -> str:
    for key in keys:
        if key not in row:
            continue
        clean = _blog_unwrapped_text_value(row.get(key))
        if clean:
            return clean
    return ""


def _blog_unwrapped_text_value(value: Any, depth: int = 0) -> str:
    if value is None or depth > 6:
        return ""
    if isinstance(value, str):
        return _blog_plain_text(value)
    if isinstance(value, dict):
        for key in ("raw", "rendered", "value", "title", "description", "content", "text"):
            if key not in value:
                continue
            clean = _blog_unwrapped_text_value(value.get(key), depth + 1)
            if clean:
                return clean
        return ""
    if isinstance(value, (list, tuple)):
        for item in value:
            clean = _blog_unwrapped_text_value(item, depth + 1)
            if clean:
                return clean
        return ""
    return ""


def _blog_nested_text_value(value: Any, keys: Sequence[str]) -> str:
    if not isinstance(value, dict):
        return ""
    for key in keys:
        if key not in value:
            continue
        clean = _blog_unwrapped_text_value(value.get(key))
        if clean:
            return clean
    return ""


def _blog_head_html_title(value: Any) -> str:
    if not isinstance(value, str):
        return ""
    text = value
    match = re.search(r"<title\b[^>]*>(.*?)</title>", text, flags=re.I | re.S)
    return _blog_plain_text(match.group(1)) if match else ""


def _blog_head_html_description(value: Any) -> str:
    if not isinstance(value, str):
        return ""
    text = value
    for match in re.finditer(r"<meta\b[^>]*>", text, flags=re.I | re.S):
        tag = match.group(0)
        name_match = re.search(r"\b(?:name|property)=([\"'])(.*?)\1", tag, flags=re.I | re.S)
        if not name_match:
            continue
        name = name_match.group(2).strip().lower()
        if name not in {"description", "og:description", "twitter:description"}:
            continue
        content_match = re.search(r"\bcontent=([\"'])(.*?)\1", tag, flags=re.I | re.S)
        if content_match:
            return _blog_plain_text(content_match.group(2))
    return ""


def _blog_readable_seo_title(row: dict[str, Any]) -> tuple[str, bool]:
    value = _blog_first_text_value(row, ["aioseo_title", "aioseoTitle", "seoTitle", "_aioseo_title"])
    if not value:
        value = _blog_nested_text_value(row.get("meta"), ["_aioseo_title", "aioseo_title", "rank_math_title", "_yoast_wpseo_title"])
    if not value:
        value = _blog_nested_text_value(row.get("aioseo_head_json"), ["title", "og_title"])
    if not value:
        value = _blog_head_html_title(row.get("aioseo_head"))
    if not value:
        value = _blog_nested_text_value(row.get("yoast_head_json"), ["title", "og_title"])
    has_value = bool(
        value
        or any(key in row for key in ("aioseo_title", "aioseoTitle", "seoTitle", "_aioseo_title", "meta", "aioseo_head_json", "aioseo_head", "yoast_head_json"))
    )
    return value, has_value


def _blog_readable_seo_description(row: dict[str, Any]) -> tuple[str, bool]:
    value = _blog_first_text_value(row, ["aioseo_description", "aioseoDescription", "seoDescription", "_aioseo_description"])
    if not value:
        value = _blog_nested_text_value(row.get("meta"), ["_aioseo_description", "aioseo_description", "rank_math_description", "_yoast_wpseo_metadesc"])
    if not value:
        value = _blog_nested_text_value(row.get("aioseo_head_json"), ["description", "og_description"])
    if not value:
        value = _blog_head_html_description(row.get("aioseo_head"))
    if not value:
        value = _blog_nested_text_value(row.get("yoast_head_json"), ["description", "og_description"])
    has_value = bool(
        value
        or any(key in row for key in ("aioseo_description", "aioseoDescription", "seoDescription", "_aioseo_description", "meta", "aioseo_head_json", "aioseo_head", "yoast_head_json"))
    )
    return value, has_value


def _blog_core_keyword_for_post(core_keywords: Optional[dict[str, str]], post_id: int) -> str:
    if not isinstance(core_keywords, dict):
        return ""
    return _blog_plain_text(
        core_keywords.get(str(post_id))
        or core_keywords.get(post_id)
        or ""
    )


def _blog_tag_names_from_post(row: dict[str, Any]) -> list[str]:
    tags = row.get("tags")
    names: list[str] = []
    if isinstance(tags, list):
        for tag in tags:
            if isinstance(tag, dict):
                name = _blog_clean_tag_name(tag.get("name") or tag.get("slug") or "")
            elif isinstance(tag, str):
                name = _blog_clean_tag_name(tag)
            else:
                name = ""
            if name and name not in names:
                names.append(name)
    for text in _blog_embedded_term_texts(row):
        name = _blog_clean_tag_name(text)
        if name and name not in names:
            names.append(name)
    return names


def _blog_merge_tag_names(existing: list[str], suggested: list[str], limit: int = 10) -> list[str]:
    out: list[str] = []
    seen: set[str] = set()
    for value in [*existing, *suggested]:
        clean = _blog_clean_tag_name(value)
        if not clean or clean in seen:
            continue
        seen.add(clean)
        out.append(clean)
        if len(out) >= limit:
            break
    return out


def _blog_has_faq_schema(html: str) -> bool:
    source = str(html or "").lower()
    return "wp:aioseo/faq" in source or "wp-block-aioseo-faq" in source or "frequently asked questions" in source


def _blog_has_youtube_embed(html: str) -> bool:
    return bool(re.search(r"(youtube\.com/embed/|youtu\.be/|wp-block-embed-youtube)", str(html or ""), flags=re.I))


def _blog_schema_preview(
    row: dict[str, Any],
    *,
    seo_title: str,
    seo_description: str,
    tag_names: list[str],
    blog_type: str,
) -> dict[str, Any]:
    content = _blog_content_from_post(row)
    has_faq = _blog_has_faq_schema(content)
    has_video = blog_type == "video" or _blog_has_youtube_embed(content)
    schema_types = ["BlogPosting", "Article"]
    warnings: list[str] = []
    will_write = []
    readiness_only = ["BlogPosting", "Article"]

    if not has_faq:
        schema_types.append("FAQPage")
        will_write.append("FAQPage")
        warnings.append("FAQ schema will be added through AIOSEO FAQ blocks in the optimized content preview.")
    if has_video:
        schema_types.append("VideoObject")
        readiness_only.append("VideoObject")
        warnings.append("VideoObject fields are prepared for review; no safe schema writer is configured yet.")

    return {
        "schemaTypes": list(dict.fromkeys(schema_types)),
        "willWrite": will_write,
        "readinessOnly": list(dict.fromkeys(readiness_only)),
        "fields": {
            "headline": seo_title or _blog_rendered_title(row),
            "description": seo_description or _blog_excerpt_from_post(row),
            "mainEntityOfPage": str(row.get("link") or ""),
            "datePublished": str(row.get("date") or ""),
            "dateModified": str(row.get("modified") or ""),
            "keywords": ", ".join(tag_names),
        },
        "warnings": warnings,
    }


def _blog_clean_seo_metadata_text(value: Any, limit: int, *, readable: bool = False) -> str:
    clean = _strip_html(str(value or ""))
    clean = _truncate_readable_text(clean, limit) if readable else _truncate_phrase_text(clean, limit)
    return _clean_trailing_seo_separator(clean)


def _blog_fallback_seo_metadata(row: dict[str, Any], core_keyword: str) -> dict[str, str]:
    title = _blog_rendered_title(row)
    excerpt = _blog_excerpt_from_post(row)
    content_text = _blog_plain_text(_blog_content_from_post(row))
    keyword_title = _truncate_phrase_text(core_keyword.title(), 48)
    seo_title = _blog_clean_seo_metadata_text(f"{keyword_title} Guide", 60) if keyword_title else _blog_clean_seo_metadata_text(title, 60)
    if title and core_keyword and core_keyword.lower() not in seo_title.lower():
        seo_title = _blog_clean_seo_metadata_text(f"{core_keyword.title()} | {title}", 60)
    source = excerpt or content_text or title
    if source and core_keyword:
        seo_description = f"{core_keyword}: {source}"
    elif source:
        seo_description = source
    else:
        seo_description = f"Learn how to evaluate {core_keyword} options for your project or buying decision." if core_keyword else "Review the available options, specifications, and buying considerations."
    return {
        "seoTitle": seo_title,
        "seoDescription": _blog_clean_seo_metadata_text(seo_description, 160, readable=True),
    }


def _blog_seo_metadata_from_ai_response(raw: str) -> dict[str, str]:
    parsed = _parse_ai_json_object(raw)
    seo_sources = [parsed]
    for wrapper_key in ("seo", "metadata", "result", "data", "output"):
        wrapped = parsed.get(wrapper_key)
        if isinstance(wrapped, dict):
            seo_sources.append(wrapped)

    def first_field(keys: Sequence[str]) -> str:
        for source in seo_sources:
            for key in keys:
                value = source.get(key)
                if isinstance(value, str) and value.strip():
                    return value
        return ""

    seo = {
        "seoTitle": _blog_clean_seo_metadata_text(
            first_field(("seoTitle", "seo_title", "metaTitle", "meta_title", "title")),
            60,
        ),
        "seoDescription": _blog_clean_seo_metadata_text(
            first_field((
                "seoDescription",
                "seo_description",
                "metaDescription",
                "meta_description",
                "description",
            )),
            160,
            readable=True,
        ),
    }
    return _validate_blog_seo_metadata(seo)


def _blog_generate_seo_metadata(
    row: dict[str, Any],
    *,
    core_keyword: str,
    keyword_context: str,
    company_context: str,
) -> dict[str, str]:
    clean_core_keyword = _blog_plain_text(core_keyword)
    fallback = _blog_fallback_seo_metadata(row, clean_core_keyword)
    if not _ai_configured():
        return fallback

    title = _blog_rendered_title(row)
    excerpt = _blog_excerpt_from_post(row)
    content = _blog_plain_text(_blog_content_from_post(row))
    prompt = f"""You are an SEO specialist for the active website.

Generate SEO metadata for one WordPress blog post.

Core keyword:
\"\"\"
{clean_core_keyword}
\"\"\"

Keyword context:
\"\"\"
{str(keyword_context or "")[:50000]}
\"\"\"

Company context:
\"\"\"
{str(company_context or "")[:30000]}
\"\"\"

Current title:
\"\"\"
{title}
\"\"\"

Current excerpt:
\"\"\"
{excerpt}
\"\"\"

Current content:
\"\"\"
{content[:12000]}
\"\"\"

Rules:
- SEO title must be 60 characters or less and naturally include the core keyword when possible.
- SEO description must be 160 characters or less and naturally use the core keyword.
- Do not invent unsupported certifications, prices, guarantees, stock, or customer names.

Return ONLY valid JSON:
{{"seoTitle": "max 60 chars", "seoDescription": "max 160 chars"}}"""
    try:
        return _blog_seo_metadata_from_ai_response(
            _gemini_generate_text(_get_gemini_api_key(), prompt, _ai_flash_model(), timeout=90)
        )
    except Exception:
        return fallback


def _blog_faq_body_change_summary(
    *,
    before_html: str,
    after_html: str,
    will_write: list[str],
    warnings: list[str],
) -> dict[str, Any]:
    return {
        "type": "faq_schema",
        "label": "FAQ schema requires body confirmation",
        "beforeHtml": before_html,
        "afterHtml": after_html,
        "willWrite": will_write,
        "warnings": warnings,
    }


def _blog_seo_repair_summary(row: dict[str, Any], repair_mode: str = "format", core_keyword: str = "") -> dict[str, Any]:
    clean_mode = _clean_blog_repair_mode(repair_mode)
    title = _blog_rendered_title(row)
    content = _blog_content_from_post(row)
    excerpt = _blog_excerpt_from_post(row)
    blog_type = _blog_bulk_format_type(row)
    existing_tags = _blog_tag_names_from_post(row)
    clean_core_keyword = _blog_plain_text(core_keyword)
    suggested_tags = _blog_auto_tag_names(
        title=title,
        explicit_keywords=clean_core_keyword,
        content=content,
        excerpt=excerpt,
        related_categories=" ".join(_blog_embedded_term_texts(row)),
        article_type="" if blog_type == "standard" else blog_type,
    )
    tag_names = _blog_merge_tag_names(([clean_core_keyword] if clean_core_keyword else []) + existing_tags, suggested_tags)

    seo_title, has_title_value = _blog_readable_seo_title(row)
    seo_description, has_description_value = _blog_readable_seo_description(row)
    generated_title = _clean_trailing_seo_separator(_truncate_phrase_text(seo_title or title, 60))
    generated_description = _truncate_readable_text(seo_description or excerpt or _blog_plain_text(content), 160)

    issue_codes: list[str] = []
    if has_title_value and not seo_title:
        issue_codes.append("missing_seo_title")
    if has_description_value and not seo_description:
        issue_codes.append("missing_seo_description")
    if not has_title_value and not has_description_value:
        issue_codes.append("seo_metadata_unknown")
    if seo_title and len(seo_title) > 60:
        issue_codes.append("seo_title_too_long")
    if seo_description and len(seo_description) > 160:
        issue_codes.append("seo_description_too_long")
    if not existing_tags:
        issue_codes.append("missing_tags")

    has_faq = _blog_has_faq_schema(content)
    has_video = blog_type == "video" or _blog_has_youtube_embed(content)
    if not has_faq:
        issue_codes.append("missing_faq_schema")
    if has_video:
        issue_codes.append("missing_video_schema_signal")

    schema_preview = _blog_schema_preview(
        row,
        seo_title=generated_title,
        seo_description=generated_description,
        tag_names=tag_names,
        blog_type=blog_type,
    )

    if "missing_tags" in issue_codes:
        tag_status = _blog_status("missing", "缺 Tags")
    else:
        tag_status = _blog_status("ok", "Tags OK")

    if any(code in issue_codes for code in ("missing_seo_title", "missing_seo_description")):
        seo_status = _blog_status("missing", "缺 SEO")
    elif "seo_metadata_unknown" in issue_codes:
        seo_status = _blog_status("unknown", "SEO 未知")
    elif any(code in issue_codes for code in ("seo_title_too_long", "seo_description_too_long")):
        seo_status = _blog_status("warning", "SEO 需检查")
    else:
        seo_status = _blog_status("ok", "SEO OK")

    if any(code in issue_codes for code in ("missing_faq_schema", "missing_article_schema_signal", "missing_video_schema_signal")):
        schema_status = _blog_status("warning", "Schema 需检查")
    else:
        schema_status = _blog_status("ok", "Schema OK")

    return {
        "repairMode": clean_mode,
        "coreKeyword": clean_core_keyword,
        "seoStatus": seo_status,
        "tagStatus": tag_status,
        "schemaStatus": schema_status,
        "issueCodes": list(dict.fromkeys(issue_codes)),
        "seoTitle": generated_title,
        "seoDescription": generated_description,
        "tagNames": tag_names,
        "schemaTypes": schema_preview["schemaTypes"],
        "schemaPreview": schema_preview,
        "seoBefore": {"seoTitle": seo_title, "seoDescription": seo_description},
        "seoAfter": {"seoTitle": generated_title, "seoDescription": generated_description},
        "tagsBefore": existing_tags,
        "tagsAfter": tag_names,
        "willWrite": schema_preview["willWrite"],
        "readinessOnly": schema_preview["readinessOnly"],
    }


def _blog_content_outline_snapshot(html: str) -> str:
    headings = [
        _blog_plain_text(match.group(2))
        for match in re.finditer(r"<h([1-4])[^>]*>([\s\S]*?)</h\1>", str(html or ""), flags=re.I)
        if _blog_plain_text(match.group(2))
    ]
    if not headings:
        return "No clear H2/H3 outline detected."
    return "\n".join(f"- {heading}" for heading in headings[:16])


def _blog_content_enrichment_prompt(
    *,
    title: str,
    content: str,
    keyword_context: str,
    company_context: str,
    knowledge_label: str,
    current_word_count: int,
    target_word_count: int,
) -> str:
    keyword_block = f"""
SELECTED PRODUCT KEYWORD KNOWLEDGE ({knowledge_label or "selected category"}):
\"\"\"
{keyword_context[:35000]}
\"\"\"
""" if keyword_context else "SELECTED PRODUCT KEYWORD KNOWLEDGE: none selected."
    company_block = f"""
COMPANY KNOWLEDGE:
\"\"\"
{company_context[:25000]}
\"\"\"
""" if company_context else "COMPANY KNOWLEDGE: none selected."
    geo_seo_block = _blog_geo_seo_writing_rules()
    return f"""You are a senior blog editor for the active website.
The task is to enrich a thin existing blog without rewriting unsupported facts.

Blog title: {_blog_plain_text(title)}
Current word count: {current_word_count}
Target word count: {target_word_count}

Current outline:
{_blog_content_outline_snapshot(content)}

Current article text:
\"\"\"
{_blog_plain_text(content)[:12000]}
\"\"\"

{keyword_block}
{company_block}
{geo_seo_block}

When planning additions, prefer sections that fill these SEO/GEO structure gaps:
- Missing direct answer opening.
- Missing product or entity definition.
- Missing audience context when the site or brief defines one.
- Missing topic-specific criteria, steps, examples, or supporting details.
- Missing a comparison or data table when verified comparable data exists.
- Missing relevant scenarios or examples supported by the sources.
- Missing FAQ-worthy reader questions when reliable answers exist.
- Missing a natural internal-link opportunity from the validated index.
- Missing a CTA only when the brief provides a verified next action.

Return ONLY valid JSON with this shape:
{{
  "targetWordCount": {target_word_count},
  "knowledgeSources": ["selected source names"],
  "additions": [
    {{
      "heading": "H2 section heading to add",
      "why": "why this section fills a thin-content gap",
      "direction": "short bullets describing what this section should cover before drafting",
      "source": "knowledge source or current article",
      "html": "<p>Reader-useful content. Use p, ul, ol, or table only; no h1.</p>"
    }}
  ],
  "warnings": ["missing or risky fact warning"]
}}

Rules:
- Add 3 to 6 substantial reader-focused sections that fit the existing article structure.
- Explain only topic-relevant criteria, steps, evidence, examples, comparisons, or questions supported by the current article and selected knowledge.
- Use the selected product keyword knowledge naturally; do not stuff keywords.
- Use company knowledge only for verified capabilities from the selected active-site knowledge base.
- Do not invent test results, certifications, model numbers, prices, stock, customer names, countries, dates, quantities, guarantees, or exact performance claims.
- The html field must contain only the body for that section, not the heading itself.
"""


def _blog_content_addition_html(value: Any) -> str:
    html = str(value or "").strip()
    if not html:
        return ""
    html = re.sub(r"<h1(\s[^>]*)?>([\s\S]*?)</h1>", r"<h2\1>\2</h2>", html, flags=re.I)
    if re.search(r"</?(p|ul|ol|table|blockquote|div)\b", html, flags=re.I):
        return html
    return f"<p>{escape(_blog_plain_text(html))}</p>"


def _normalize_blog_content_enrichment(
    raw: dict[str, Any],
    *,
    default_target_word_count: int,
    knowledge_label: str,
    has_company_context: bool,
) -> dict[str, Any]:
    target_word_count = raw.get("targetWordCount") or raw.get("target_word_count") or default_target_word_count
    try:
        target_word_count = max(0, int(float(target_word_count)))
    except (TypeError, ValueError):
        target_word_count = default_target_word_count

    raw_sources = raw.get("knowledgeSources") or raw.get("knowledge_sources") or []
    if isinstance(raw_sources, str):
        raw_sources = re.split(r"[\n,;|]+", raw_sources)
    sources: list[str] = []
    for source in (raw_sources if isinstance(raw_sources, list) else []):
        text = _blog_plain_text(source)
        if text and text not in sources:
            sources.append(text)
    if knowledge_label and knowledge_label not in sources:
        sources.insert(0, knowledge_label)
    if has_company_context and "公司知识库" not in sources:
        sources.append("公司知识库")

    raw_additions = raw.get("additions") or raw.get("sections") or raw.get("contentAdditions") or []
    if not isinstance(raw_additions, list):
        raw_additions = []
    additions: list[dict[str, str]] = []
    for addition in raw_additions:
        if not isinstance(addition, dict):
            continue
        heading = _truncate_phrase_text(_blog_plain_text(
            addition.get("heading") or addition.get("title") or addition.get("section") or ""
        ), 100)
        why = _truncate_readable_text(_blog_plain_text(
            addition.get("why") or addition.get("rationale") or addition.get("reason") or ""
        ), 220)
        direction = _truncate_readable_text(_blog_plain_text(
            addition.get("direction")
            or addition.get("whatToAdd")
            or addition.get("what_to_add")
            or addition.get("coverage")
            or addition.get("writingDirection")
            or addition.get("writing_direction")
            or ""
        ), 260)
        html = _blog_content_addition_html(
            addition.get("html")
            or addition.get("bodyHtml")
            or addition.get("body_html")
            or addition.get("suggestedHtml")
            or addition.get("suggestedCopy")
            or addition.get("content")
            or ""
        )
        source = _truncate_phrase_text(_blog_plain_text(
            addition.get("source") or addition.get("knowledgeSource") or addition.get("knowledge_source") or ""
        ), 80)
        if heading and why and html:
            normalized_addition = {
                "heading": heading,
                "why": why,
                "source": source,
                "html": html,
            }
            if direction:
                normalized_addition["direction"] = direction
            additions.append(normalized_addition)

    raw_warnings = raw.get("warnings") or []
    if isinstance(raw_warnings, str):
        raw_warnings = [raw_warnings]
    warnings = [
        _truncate_readable_text(_blog_plain_text(item), 220)
        for item in raw_warnings
        if _blog_plain_text(item)
    ] if isinstance(raw_warnings, list) else []

    if not additions:
        raise HTTPException(status_code=502, detail="AI content enrichment did not return usable sections")

    return {
        "targetWordCount": target_word_count,
        "knowledgeSources": sources,
        "additions": additions[:8],
        "warnings": warnings[:8],
    }


def _blog_generate_content_enrichment_plan(
    row: dict[str, Any],
    *,
    content: str,
    keyword_context: str = "",
    company_context: str = "",
    knowledge_label: str = "",
) -> dict[str, Any]:
    title = _blog_rendered_title(row)
    current_word_count = len(re.findall(r"\b[a-zA-Z0-9][a-zA-Z0-9'-]*\b", _blog_plain_text(content)))
    target_word_count = max(BLOG_CONTENT_THIN_WORD_LIMIT, current_word_count + 450)
    prompt = _blog_content_enrichment_prompt(
        title=title,
        content=content,
        keyword_context=keyword_context,
        company_context=company_context,
        knowledge_label=knowledge_label,
        current_word_count=current_word_count,
        target_word_count=target_word_count,
    )
    raw = _gemini_generate_text(_get_gemini_api_key(), prompt, _ai_pro_model(), timeout=120)
    parsed = _parse_ai_json_object(raw)
    if not parsed:
        raise HTTPException(status_code=502, detail="AI content enrichment did not return valid JSON")
    return _normalize_blog_content_enrichment(
        parsed,
        default_target_word_count=target_word_count,
        knowledge_label=knowledge_label,
        has_company_context=bool(company_context.strip()),
    )


def _blog_content_with_enrichment_sections(content: str, plan: dict[str, Any], *, highlight_additions: bool = False) -> str:
    sections: list[str] = []
    for addition in plan.get("additions") or []:
        if not isinstance(addition, dict):
            continue
        heading = _blog_plain_text(addition.get("heading") or "")
        body = _blog_content_addition_html(addition.get("html") or "")
        if not heading or not body:
            continue
        section = f"<h2>{escape(heading)}</h2>\n{body}"
        if highlight_additions:
            section = f'<div class="blog-content-added">\n{section}\n</div>'
        sections.append(section)
    if not sections:
        return content
    return f"{str(content or '').strip()}\n\n" + "\n\n".join(sections)


def _blog_rendered_title(row: dict[str, Any]) -> str:
    title = row.get("title")
    if isinstance(title, dict):
        return _blog_plain_text(title.get("raw") or title.get("rendered") or "")
    return _blog_plain_text(title)


def _blog_content_from_post(row: dict[str, Any]) -> str:
    content = row.get("content")
    if isinstance(content, dict):
        return str(content.get("raw") or content.get("rendered") or "")
    return str(content or "")


def _blog_excerpt_from_post(row: dict[str, Any]) -> str:
    excerpt = row.get("excerpt")
    if isinstance(excerpt, dict):
        return _blog_plain_text(excerpt.get("raw") or excerpt.get("rendered") or "")
    return _blog_plain_text(excerpt)


def _blog_bulk_format_search_text(row: dict[str, Any]) -> str:
    parts = [
        _blog_rendered_title(row),
        _blog_plain_text(row.get("slug") or ""),
        _blog_plain_text(row.get("link") or ""),
        _blog_excerpt_from_post(row),
        _blog_plain_text(_blog_content_from_post(row)),
    ]
    return " ".join(part for part in parts if part).lower()


def _blog_slugify(value: str, fallback: str = "blog-post") -> str:
    text = unescape(_blog_plain_text(value)).lower()
    text = text.replace("&", " and ")
    text = re.sub(r"[^a-z0-9]+", "-", text)
    text = re.sub(r"-+", "-", text).strip("-")
    return (text or fallback)[:80].strip("-") or fallback


def _blog_title_key(value: str) -> str:
    text = re.sub(r"^#+\s*", "", str(value or "").strip())
    text = _blog_plain_text(text).lower()
    text = text.replace("&", " and ")
    return re.sub(r"[^a-z0-9]+", " ", text).strip()


def _blog_without_leading_duplicate_title(content: str, title: str) -> str:
    source = str(content or "")
    title_key = _blog_title_key(title)
    if not source.strip() or not title_key:
        return source

    lines = source.replace("\r\n", "\n").replace("\r", "\n").split("\n")
    first_index = next((idx for idx, line in enumerate(lines) if line.strip()), -1)
    if first_index < 0:
        return source

    if _blog_title_key(lines[first_index]) != title_key:
        return source

    del lines[first_index]
    while first_index < len(lines) and not lines[first_index].strip():
        del lines[first_index]
    return "\n".join(lines).strip()


def _blog_url_key(url: str) -> str:
    parsed = urlparse(str(url or "").strip())
    path = parsed.path.rstrip("/") or "/"
    return f"{parsed.netloc.lower()}{path}".strip()


def _blog_auth_context() -> tuple[str, tuple[str, str]]:
    creds = _resolve_cli_wp_credentials()
    wp_url = creds.get("wp_url", "").strip().rstrip("/")
    wp_user = creds.get("wp_user", "").strip()
    wp_app_pass = creds.get("wp_app_pass", "").strip()
    if not wp_url or not wp_user or not wp_app_pass:
        raise HTTPException(
            status_code=400,
            detail=WP_CONFIG_REQUIRED_DETAIL,
        )
    return wp_url, (wp_user, wp_app_pass)


def _blog_wp_request(
    method: str,
    path: str,
    *,
    params: Optional[dict[str, Any]] = None,
    json_body: Optional[dict[str, Any]] = None,
    timeout: float = 60,
    max_attempts: Optional[int] = None,
) -> Any:
    wp_url, auth = _blog_auth_context()
    normalized_path = path if path.startswith("/") else f"/{path}"
    endpoint = f"{wp_url}/wp-json{normalized_path}"
    kwargs: dict[str, Any] = {
        "timeout": timeout,
        "params": params,
        "auth": auth,
    }
    if json_body is not None:
        kwargs["json"] = json_body
    request_attempts = (
        max(1, int(max_attempts))
        if max_attempts is not None
        else 3 if method.upper() == "GET" and timeout > 8 else 1
    )
    last_exc: Optional[BaseException] = None
    for attempt in range(request_attempts):
        try:
            resp = _http_request_with_proxy_fallback(
                method,
                endpoint,
                **kwargs,
            )
        except httpx.TimeoutException as exc:
            last_exc = exc
            if attempt >= request_attempts - 1:
                raise HTTPException(status_code=504, detail=f"WordPress REST API timed out after {timeout}s")
            time.sleep(min(2.0, 0.5 * (2 ** attempt)))
            continue
        if _is_cloudflare_challenge_response(resp):
            raise HTTPException(
                status_code=502,
                detail=(
                    "Cloudflare challenge is blocking WordPress REST access for blog publishing. "
                    "Set a WordPress REST bypass header in Settings and add a Cloudflare Skip rule for /wp-json/*."
                ),
            )
        if resp.status_code >= 400:
            if method.upper() == "GET" and resp.status_code in {408, 425, 429, 500, 502, 503, 504} and attempt < request_attempts - 1:
                retry_after = _retry_after_seconds(resp.headers.get("Retry-After"))
                time.sleep(retry_after if retry_after is not None else min(2.0, 0.5 * (2 ** attempt)))
                continue
            raise HTTPException(
                status_code=502,
                detail=_response_detail(resp, f"WordPress REST API returned HTTP {resp.status_code}"),
            )
        if not resp.text:
            return {}
        return resp.json()
    raise HTTPException(
        status_code=502,
        detail=str(last_exc or "WordPress REST API request failed"),
    )


def _blog_warning_detail(exc: Exception) -> str:
    detail = getattr(exc, "detail", None)
    if detail is None:
        detail = str(exc)
    text = _blog_plain_text(detail)
    return text[:220] + ("..." if len(text) > 220 else "")


def _blog_is_edit_context_denied(exc: Exception) -> bool:
    text = _blog_warning_detail(exc).lower()
    return "not allowed to edit this post" in text or "rest_cannot_edit" in text


def _blog_fetch_post_for_preview(post_id: int, *, timeout: float = SCAN_REST_PAGE_TIMEOUT_SECONDS) -> Any:
    path = f"/wp/v2/posts/{post_id}"
    try:
        return _blog_wp_request(
            "GET",
            path,
            params={"context": "edit", "_embed": "wp:term"},
            timeout=timeout,
        )
    except HTTPException as exc:
        if not _blog_is_edit_context_denied(exc):
            raise
        row = _blog_wp_request(
            "GET",
            path,
            params={"_embed": "wp:term"},
            timeout=timeout,
        )
        if isinstance(row, dict):
            row["_readOnlyPreview"] = True
        return row


def _blog_existing_tag_ids(post_row: Optional[dict[str, Any]]) -> list[int]:
    if not isinstance(post_row, dict):
        return []
    tags = post_row.get("tags")
    if not isinstance(tags, list):
        return []
    out: list[int] = []
    for tag in tags:
        tag_id: Optional[int] = None
        if isinstance(tag, int):
            tag_id = tag
        elif isinstance(tag, dict) and isinstance(tag.get("id"), int):
            tag_id = int(tag["id"])
        if tag_id and tag_id > 0 and tag_id not in out:
            out.append(tag_id)
    return out


def _blog_find_existing_wp_tag_id(name: str) -> Optional[int]:
    data = _blog_wp_request(
        "GET",
        "/wp/v2/tags",
        params={"search": name, "per_page": 100},
        timeout=45,
    )
    if not isinstance(data, list):
        return None
    target_name = _blog_clean_tag_name(name)
    target_slug = _blog_slugify(name)
    for row in data:
        if not isinstance(row, dict):
            continue
        row_id = row.get("id")
        row_name = _blog_clean_tag_name(row.get("name") or "")
        row_slug = str(row.get("slug") or "").strip().lower()
        if isinstance(row_id, int) and (row_name == target_name or row_slug == target_slug):
            return int(row_id)
    return None


def _blog_get_or_create_wp_tag_ids(names: list[str]) -> list[int]:
    ids: list[int] = []
    for name in names:
        clean_name = _blog_clean_tag_name(name)
        if not clean_name:
            continue
        existing_id = _blog_find_existing_wp_tag_id(clean_name)
        if existing_id is not None:
            if existing_id not in ids:
                ids.append(existing_id)
            continue

        try:
            row = _blog_wp_request(
                "POST",
                "/wp/v2/tags",
                json_body={"name": clean_name},
                timeout=45,
            )
        except Exception:
            retry_id = _blog_find_existing_wp_tag_id(clean_name)
            if retry_id is not None:
                if retry_id not in ids:
                    ids.append(retry_id)
                continue
            raise
        tag_id = row.get("id") if isinstance(row, dict) else None
        if not isinstance(tag_id, int):
            raise HTTPException(status_code=502, detail=f"WordPress did not return an ID for blog tag: {clean_name}")
        if tag_id not in ids:
            ids.append(tag_id)
    return ids


def _blog_attach_auto_tags(
    body: dict[str, Any],
    *,
    title: str = "",
    explicit_keywords: str = "",
    content: str = "",
    seo_title: str = "",
    seo_description: str = "",
    excerpt: str = "",
    keyword_context: str = "",
    related_products: str = "",
    related_categories: str = "",
    article_type: str = "",
    existing_post: Optional[dict[str, Any]] = None,
) -> Optional[str]:
    names = _blog_auto_tag_names(
        title=title,
        explicit_keywords=explicit_keywords,
        content=content,
        seo_title=seo_title,
        seo_description=seo_description,
        excerpt=excerpt,
        keyword_context=keyword_context,
        related_products=related_products,
        related_categories=related_categories,
        article_type=article_type,
    )
    if not names:
        return None

    try:
        generated_ids = _blog_get_or_create_wp_tag_ids(names)
        merged_ids = [*_blog_existing_tag_ids(existing_post)]
        for tag_id in generated_ids:
            if tag_id not in merged_ids:
                merged_ids.append(tag_id)
        if merged_ids:
            body["tags"] = merged_ids
        return None
    except Exception as exc:
        return f"Blog tag sync skipped: {_blog_warning_detail(exc)}"


def _blog_fetch_collection(
    path: str,
    params: dict[str, Any],
    max_pages: int = 2,
    timeout: float = 6,
    request_attempts: Optional[int] = None,
) -> list[dict[str, Any]]:
    rows, _warnings = _blog_fetch_collection_with_warnings(
        path,
        params,
        max_pages=max_pages,
        timeout=timeout,
        request_attempts=request_attempts,
    )
    return rows


def _blog_payload_detail(payload: Any, fallback: str) -> str:
    if isinstance(payload, dict):
        for key in ("message", "detail", "code"):
            value = payload.get(key)
            if isinstance(value, str) and value.strip():
                return value.strip()
        if payload:
            try:
                return json.dumps(payload, ensure_ascii=False)
            except Exception:
                return fallback
    return fallback


def _blog_fetch_collection_with_warnings(
    path: str,
    params: dict[str, Any],
    max_pages: int = 2,
    timeout: float = 6,
    request_attempts: Optional[int] = None,
) -> tuple[list[dict[str, Any]], list[str]]:
    rows: list[dict[str, Any]] = []
    warnings: list[str] = []
    per_page = int(params.get("per_page") or 100)
    for page in range(1, max_pages + 1):
        page_params = {**params, "page": page, "per_page": per_page}
        try:
            data = _blog_wp_request("GET", path, params=page_params, timeout=timeout, max_attempts=request_attempts)
        except HTTPException as exc:
            if page > 1:
                warnings.append(
                    f"WordPress Blog scan stopped after page {page - 1}; page {page} failed: {_blog_warning_detail(exc)}"
                )
                break
            raise
        if not isinstance(data, list):
            detail = _blog_payload_detail(data, "WordPress Blog scan response was not a list")
            if page > 1 and rows:
                warnings.append(
                    f"WordPress Blog scan stopped after page {page - 1}; page {page} response was not a list: {detail}"
                )
                break
            raise HTTPException(status_code=502, detail=f"WordPress Blog scan response was not a list: {detail}")
        valid_rows = [r for r in data if isinstance(r, dict)]
        if data and not valid_rows:
            break
        rows.extend(valid_rows)
        if len(data) < per_page:
            break
    return rows, warnings


def _blog_fetch_wc_collection(path: str, params: dict[str, Any], max_pages: int = 2) -> list[dict[str, Any]]:
    rows, _warnings = _blog_fetch_wc_collection_with_warnings(path, params, max_pages=max_pages)
    return rows


def _blog_fetch_wc_collection_with_warnings(
    path: str,
    params: dict[str, Any],
    max_pages: int = 2,
) -> tuple[list[dict[str, Any]], list[str]]:
    wp_url, wc_params, auth = _resolve_wc_write_context()
    endpoint = f"{wp_url.rstrip('/')}/wp-json{path if path.startswith('/') else '/' + path}"
    rows: list[dict[str, Any]] = []
    warnings: list[str] = []
    per_page = int(params.get("per_page") or 100)
    for page in range(1, max_pages + 1):
        page_params = {**params, **wc_params, "page": page, "per_page": per_page}
        try:
            resp = _http_request_with_proxy_fallback(
                "GET",
                endpoint,
                timeout=6,
                params=page_params,
                auth=auth,
            )
        except Exception as exc:
            if page > 1 and rows:
                warnings.append(
                    f"WooCommerce scan stopped after page {page - 1}; page {page} failed: {_blog_warning_detail(exc)}"
                )
                break
            raise
        if resp.status_code >= 400:
            if page > 1:
                warnings.append(
                    f"WooCommerce scan stopped after page {page - 1}; page {page} returned HTTP {resp.status_code}: "
                    f"{_response_detail(resp, f'WooCommerce API returned HTTP {resp.status_code}')}"
                )
                break
            raise HTTPException(
                status_code=502,
                detail=_response_detail(resp, f"WooCommerce API returned HTTP {resp.status_code}"),
            )
        data = resp.json()
        if not isinstance(data, list):
            detail = _blog_payload_detail(data, "WooCommerce API response was not a list")
            if page > 1 and rows:
                warnings.append(
                    f"WooCommerce scan stopped after page {page - 1}; page {page} response was not a list: {detail}"
                )
                break
            raise HTTPException(status_code=502, detail=f"WooCommerce API response was not a list: {detail}")
        rows.extend([r for r in data if isinstance(r, dict)])
        if len(data) < per_page:
            break
    return rows, warnings


YOUTUBE_VIDEO_ID_RE = re.compile(r"^[A-Za-z0-9_-]{11}$")


def _youtube_embed_url(video_id: str) -> str:
    return f"https://www.youtube.com/embed/{video_id}"


def _youtube_watch_url(video_id: str) -> str:
    return f"https://www.youtube.com/watch?v={video_id}"


def _youtube_video_id(value: str) -> str:
    raw = str(value or "").strip()
    if not raw:
        raise HTTPException(status_code=400, detail="请输入有效的 YouTube 视频链接。")

    parsed = urlparse(raw if re.match(r"^https?://", raw, flags=re.I) else f"https://{raw}")
    host = (parsed.hostname or "").lower()
    path = parsed.path.strip("/")
    candidate = ""

    if host in {"youtu.be", "www.youtu.be"}:
        candidate = path.split("/")[0]
    elif host in {"youtube.com", "www.youtube.com", "m.youtube.com", "youtube-nocookie.com", "www.youtube-nocookie.com"}:
        if path == "watch":
            candidate = (parse_qs(parsed.query).get("v") or [""])[0]
        elif path.startswith("embed/") or path.startswith("shorts/"):
            parts = path.split("/")
            candidate = parts[1] if len(parts) > 1 else ""

    if not YOUTUBE_VIDEO_ID_RE.match(candidate):
        raise HTTPException(status_code=400, detail="请输入有效的 YouTube 视频链接。")
    return candidate


def _html_attr(tag: str, attr_name: str) -> str:
    match = re.search(rf"\b{re.escape(attr_name)}\s*=\s*(['\"])(.*?)\1", tag, flags=re.I | re.S)
    return unescape(match.group(2)).strip() if match else ""


def _youtube_meta_content(html: str, key: str) -> str:
    for tag in re.findall(r"<meta\b[^>]*>", html or "", flags=re.I | re.S):
        prop = _html_attr(tag, "property") or _html_attr(tag, "name") or _html_attr(tag, "itemprop")
        if prop == key:
            return _html_attr(tag, "content")
    for tag in re.findall(r"<link\b[^>]*>", html or "", flags=re.I | re.S):
        prop = _html_attr(tag, "itemprop") or _html_attr(tag, "property") or _html_attr(tag, "name")
        if prop == key:
            return _html_attr(tag, "content")
    return ""


def _youtube_json_assignment(html: str, marker: str) -> dict[str, Any]:
    start_marker = (html or "").find(marker)
    if start_marker < 0:
        return {}
    start = html.find("{", start_marker)
    if start < 0:
        return {}

    depth = 0
    in_string = False
    escaped = False
    quote = ""
    for index in range(start, len(html)):
        char = html[index]
        if in_string:
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == quote:
                in_string = False
            continue
        if char in {"\"", "'"}:
            in_string = True
            quote = char
            continue
        if char == "{":
            depth += 1
        elif char == "}":
            depth -= 1
            if depth == 0:
                try:
                    return json.loads(html[start:index + 1])
                except Exception:
                    return {}
    return {}


def _youtube_best_thumbnail(value: Any) -> str:
    thumbnails: list[dict[str, Any]] = []
    if isinstance(value, dict):
        raw_items = value.get("thumbnails") or []
        if isinstance(raw_items, list):
            thumbnails = [item for item in raw_items if isinstance(item, dict)]
    if not thumbnails:
        return ""
    best = thumbnails[-1]
    return str(best.get("url") or "").strip()


def _youtube_metadata_from_html(html: str, *, video_id: str, source_url: str) -> dict[str, Any]:
    player = _youtube_json_assignment(html, "ytInitialPlayerResponse")
    video = player.get("videoDetails") if isinstance(player.get("videoDetails"), dict) else {}
    microformat = player.get("microformat") if isinstance(player.get("microformat"), dict) else {}
    renderer = microformat.get("playerMicroformatRenderer") if isinstance(microformat.get("playerMicroformatRenderer"), dict) else {}

    title = _blog_plain_text(video.get("title") or _youtube_meta_content(html, "og:title"))
    description = _blog_plain_text(
        video.get("shortDescription")
        or _youtube_meta_content(html, "og:description")
        or _youtube_meta_content(html, "description")
    )
    thumbnail = (
        _youtube_best_thumbnail(video.get("thumbnail"))
        or _youtube_best_thumbnail(renderer.get("thumbnail"))
        or _youtube_meta_content(html, "og:image")
    )
    channel = _blog_plain_text(
        video.get("author")
        or renderer.get("ownerChannelName")
        or _youtube_meta_content(html, "name")
    )
    published_at = _blog_plain_text(
        renderer.get("publishDate")
        or _youtube_meta_content(html, "datePublished")
    )

    warnings: list[str] = []
    if not title:
        warnings.append("YouTube title could not be fetched; please fill it manually.")
    if not description:
        warnings.append("YouTube description could not be fetched; please fill it manually.")
    if not thumbnail:
        warnings.append("YouTube thumbnail could not be fetched.")
    if not channel:
        warnings.append("YouTube channel name could not be fetched.")
    if not published_at:
        warnings.append("YouTube published date could not be fetched.")

    return {
        "youtubeUrl": source_url,
        "videoId": video_id,
        "title": title,
        "description": description,
        "thumbnailUrl": thumbnail,
        "channelName": channel,
        "publishedAt": published_at,
        "embedUrl": _youtube_embed_url(video_id),
        "warnings": warnings,
    }


def _youtube_minimal_metadata(video_id: str, source_url: str, warning: str) -> dict[str, Any]:
    return {
        "youtubeUrl": source_url,
        "videoId": video_id,
        "title": "",
        "description": "",
        "thumbnailUrl": "",
        "channelName": "",
        "publishedAt": "",
        "embedUrl": _youtube_embed_url(video_id),
        "warnings": [warning],
    }


def _blog_ai_article_type(value: str) -> str:
    clean = str(value or "").strip().lower()
    if clean in {"standard", "blog", "normal", "general", "article"}:
        return "standard"
    return clean if clean in {"exhibition", "certificate", "project", "video"} else "standard"


def _blog_ai_certificate_warning(payload: BlogAICreateDraftPayload) -> str:
    if _blog_ai_article_type(payload.articleType) == "certificate" and not payload.certificate.confirmedByUser:
        return "Certificate scope must be manually confirmed before creating a WordPress draft."
    return ""


def _blog_ai_clean_list(values: list[str]) -> list[str]:
    return [_blog_plain_text(value) for value in values if _blog_plain_text(value)]


def _blog_ai_images_summary(images: list[BlogAIImage]) -> str:
    if not images:
        return "No images selected."
    lines: list[str] = []
    for index, image in enumerate(images[:12], start=1):
        parts = [
            f"Image {index}",
            f"mediaId={image.mediaId or ''}",
            f"url={image.url or ''}",
            f"title={_blog_plain_text(image.title)}",
            f"purpose={_blog_plain_text(image.purpose)}",
            f"alt={_blog_plain_text(image.altText)}",
            f"caption={_blog_plain_text(image.caption)}",
            f"insertHint={_blog_plain_text(image.insertHint)}",
        ]
        lines.append(" | ".join(parts))
    return "\n".join(lines)


def _blog_ai_facts_summary(payload: BlogAIBasePayload) -> str:
    article_type = _blog_ai_article_type(payload.articleType)
    if article_type == "certificate":
        cert = payload.certificate
        return f"""Certificate facts:
- Source: {_blog_plain_text(cert.certificateSource)}
- Certification type: {_blog_plain_text(cert.certificationType)}
- Applicable products: {_blog_plain_text(cert.applicableProducts)}
- Applicable models: {_blog_plain_text(cert.applicableModels)}
- Scope statement: {_blog_plain_text(cert.scopeStatement)}
- Certificate file name: {_blog_plain_text(cert.certificateFileName)}
- Manually confirmed: {"yes" if cert.confirmedByUser else "no"}"""

    if article_type == "project":
        project = payload.project
        client_or_project_name = (
            _blog_plain_text(project.clientOrProjectName)
            if project.discloseClientName
            else "[hidden because disclosure is anonymous; do not mention]"
        )
        return f"""Project case facts:
- Internal project name: {_blog_plain_text(project.projectName)}
- Client/project name disclosure: {"public" if project.discloseClientName else "anonymous"}
- Client or project name: {client_or_project_name}
- Location: {_blog_plain_text(project.projectLocation)}
- Scenario: {_blog_plain_text(project.projectScenario)}
- Installed products: {_blog_plain_text(project.installedProducts)}
- Application areas: {_blog_plain_text(project.applicationAreas)}
- Project needs or pain points: {_blog_plain_text(project.projectNeeds)}
- Solution provided: {_blog_plain_text(project.solutionProvided)}
- Public results or highlights: {_blog_plain_text(project.projectResults)}
- Public project date: {_blog_plain_text(project.projectDate)}
- Project CTA: {_blog_plain_text(project.projectCta)}"""

    if article_type == "video":
        video = payload.video
        return f"""Product video facts:
- YouTube URL: {_blog_plain_text(video.youtubeUrl)}
- Video ID: {_blog_plain_text(video.videoId)}
- Video title: {_blog_plain_text(video.title)}
- Video description: {_blog_plain_text(video.description)}
- Channel name: {_blog_plain_text(video.channelName)}
- Published date: {_blog_plain_text(video.publishedAt)}
- Embed URL: {_blog_plain_text(video.embedUrl)}
- Product model: {_blog_plain_text(video.productModel)}
- Product category: {_blog_plain_text(video.productCategory)}
- Key selling points: {_blog_plain_text(video.keySellingPoints)}
- Intended audience: {_blog_plain_text(video.targetBuyer)}
- Use scenario: {_blog_plain_text(video.useScenario)}
- Video CTA: {_blog_plain_text(video.videoCta)}"""

    if article_type == "standard":
        return f"""Standard blog facts:
- Topic: {_blog_plain_text(payload.topic)}
- Target keywords: {_blog_plain_text(payload.targetKeywords)}
- Related products: {_blog_plain_text(payload.relatedProducts)}
- Related categories: {_blog_plain_text(payload.relatedCategories)}
- Intended audience: {", ".join(_blog_ai_clean_list(payload.targetAudience)) or "the audience described by this site's knowledge base"}"""

    exhibition = payload.exhibition
    return f"""Exhibition facts:
- Event name: {_blog_plain_text(exhibition.eventName)}
- Date: {_blog_plain_text(exhibition.eventDate)}
- Location: {_blog_plain_text(exhibition.eventLocation)}
- Booth number: {_blog_plain_text(exhibition.boothNumber)}
- Featured products: {_blog_plain_text(exhibition.featuredProducts)}
- Visitor highlights: {_blog_plain_text(exhibition.visitorHighlights)}
- Audience questions: {_blog_plain_text(exhibition.buyerQuestions)}
- Follow-up CTA: {_blog_plain_text(exhibition.followUpCta)}"""


def _blog_geo_seo_writing_rules() -> str:
    return """
Active-site Blog SEO/GEO writing standard:
- Use the site context and article brief to identify the real audience; do not assume an industry or business model.
- Start with a direct answer opening that answers the search intent in 1-2 short paragraphs.
- Define important entities early using only the supplied topic and evidence.
- Use clear H2/H3 sections where each section answers one relevant reader question.
- Cover criteria, steps, examples, or supporting details only when the topic and provided facts support them.
- Use a comparison table only when verified comparable data exists and a comparison helps answer the search intent.
- Add FAQ questions only when reliable answers exist; FAQ answers must match visible article content and any FAQ schema.
- Suggest natural internal-link opportunities from the validated index. Include a CTA only when the site context or brief supplies a verified next action.
- Do not invent test results, certifications, model numbers, prices, stock, lead times, customer names, countries, quantities, guarantees, warranties, or performance claims.
- Do not keyword-stuff, create near-duplicate query-variation sections, fake authority, or add structured data claims that are not visible to readers.
"""


def _blog_ai_video_prompt_rules() -> str:
    return """
Video Blog outline:
1. Introduction: explain what the video shows, who it is for, and which question it helps answer.
2. YouTube Embed: place the video near the top of the WordPress draft.
3. What the Video Shows: summarize visible or described facts without inferring missing details.
4. Key Points Highlighted in the Video: convert the supplied description and fields into 3-6 audience-relevant points.
5. Context and Applications: cover supported context from the video description, keyword source, or site knowledge.
6. Why It Matters: explain relevance only when supported by provided facts.
7. Reference Details: organize names, versions, sizes, dates, or other supplied attributes only when present.
8. Related Content: include natural internal-link direction from validated related inputs.
9. FAQ: answer relevant questions only when reliable answers are available.
10. CTA: invite readers to take the next step defined by the active site or provided brief.

Video safety rules:
- Treat the YouTube title and description as the primary source of truth.
- Do not read or invent YouTube captions or transcript content.
- Do not invent test results, certifications, customer names, quantities, prices, countries, installation sites, guarantees, or stock status.
- If the YouTube description is thin, return a warning and write conservatively from the optional product fields.
"""


def _blog_ai_certificate_explainer_structure() -> str:
    return """
Certificate Blog explainer structure:
1. Title: format around the certification type, verified scope, and reader value.
2. Opening introduction: introduce the active company context and the certificate as a documented trust signal.
3. What Does [Certification Type] Certification Mean?
4. Why the Confirmed Scope Matters
5. Scope Details Supported by the Source
6. Covered Entities or Items
7. Verified [Certification Type] Compliance
8. Certificate Statement
9. Certificate Image
10. Who Needs This Information?
11. Beyond Compliance
12. Additional Verified Context
13. Closing CTA only when the brief provides a real next action
14. FAQ
"""


def _blog_ai_certificate_outline_requirements() -> str:
    return """
Certificate outline requirements:
- Use the fixed H2/H3 structure from the Certificate Blog explainer structure.
- Include a distinct covered-models section named "Covered Product Models".
- Place certificate image planning after the certificate statement, not before the introduction.
- Include missing/risky fact warnings for certificate scope, file name, applicable products, applicable models, or unsupported claims.
"""


def _blog_ai_certificate_generation_requirements() -> str:
    return """
Certificate full-article requirements:
- Write Gutenberg-friendly HTML using h2, h3, p, ul, ol, and optionally one simple table.
- Do not place certificate images at the beginning of the article.
- Keep covered models as an explicit list or table.
- Use the confirmed scope statement for the Certificate Statement section.
- Add warnings for missing certificate scope, file name, applicable models, or unsupported claims.
"""


def _blog_ai_certificate_prompt_rules() -> str:
    return f"""
Certificate Blog layout rules:
{_blog_ai_certificate_explainer_structure()}

Writing rules:
1. Write a text-first certificate explainer page with clear H2/H3 sections and scope notes. Include FAQ and CTA only when supported by reliable answers and a real next action.
2. Do not place certificate images at the beginning of the article, and do not place galleries, cover blocks, or media blocks at the beginning of the article.
3. Treat selected images as reference/context for facts and SEO image metadata only. Do not insert wp:image blocks into the html unless the Certificate Image section explicitly needs one image as evidence.
4. Covered Product Models must be a separate section. Models must come only from applicableModels or verified company context.
5. Certificate Statement must be based on scopeStatement. Do not invent certificate number, issuing lab, issue date, expiry date, or test standard.
"""


def _blog_context_terms(payload: BlogAIBasePayload) -> set[str]:
    parts = [
        payload.topic,
        payload.targetKeywords,
        payload.relatedProducts,
        payload.relatedCategories,
        payload.articleType,
    ]
    text = " ".join(_blog_plain_text(part).lower() for part in parts)
    terms = {term.strip().lower() for term in re.split(r"[\n,;|/]+", text) if term.strip()}
    terms.update(match.group(0).strip().lower() for match in re.finditer(r"[a-z0-9][a-z0-9 -]{2,}", text))
    return {term for term in terms if len(term) >= 3}


def _blog_framework_for_payload(profile: dict[str, Any], payload: BlogAIBasePayload, article_type: str) -> Optional[dict[str, Any]]:
    frameworks = _normalize_blog_frameworks(profile.get("blogFrameworks") or [], profile.get("templatePack") or {})
    requested_id = _profile_slug(str(getattr(payload, "frameworkId", "") or ""), "")
    if requested_id:
        for framework in frameworks:
            if framework.get("id") == requested_id:
                return framework
    for framework in frameworks:
        if str(framework.get("articleType") or "").lower() == article_type:
            return framework
    return frameworks[0] if frameworks else None


def _blog_faq_matches_payload(faq: dict[str, Any], payload: BlogAIBasePayload, terms: set[str]) -> bool:
    haystack_parts = [
        *faq.get("productCategories", []),
        *faq.get("keywords", []),
        *faq.get("scenarios", []),
        faq.get("question", ""),
        faq.get("answer", ""),
    ]
    haystack = " ".join(_blog_plain_text(part).lower() for part in haystack_parts)
    if not terms:
        return True
    return any(term and (term in haystack or haystack in term) for term in terms)


def _blog_ai_profile_framework_faq_block(payload: BlogAIBasePayload, article_type: str) -> str:
    try:
        store = _load_client_profile_store(create=False)
        profile = _find_client_profile(store, payload.siteId) if payload.siteId else _active_client_profile(store)
    except Exception:
        return ""

    framework = _blog_framework_for_payload(profile, payload, article_type)
    terms = _blog_context_terms(payload)
    approved_faqs = [
        faq for faq in _normalize_faqs(profile.get("faqs") or [])
        if faq.get("status") == "approved" and _blog_faq_matches_payload(faq, payload, terms)
    ]
    if not approved_faqs:
        approved_faqs = [
            faq for faq in _normalize_faqs(profile.get("faqs") or [])
            if faq.get("status") == "approved"
        ][:5]

    blocks: list[str] = []
    if framework:
        outline_lines = []
        for item in framework.get("outlineBlocks") or []:
            heading = _blog_plain_text(item.get("heading") or "")
            intent = _blog_plain_text(item.get("intent") or "")
            content_rules = _blog_plain_text(item.get("contentRules") or "")
            if heading or intent or content_rules:
                outline_lines.append(
                    f"- {heading or 'Section'}"
                    f"{' | intent: ' + intent if intent else ''}"
                    f"{' | rules: ' + content_rules if content_rules else ''}"
                )
        prohibited = "; ".join(_blog_plain_text(item) for item in framework.get("prohibitedClaims") or [] if _blog_plain_text(item))
        voice_rules = "; ".join(_blog_plain_text(item) for item in framework.get("voiceRules") or [] if _blog_plain_text(item))
        evidence_rules = "; ".join(_blog_plain_text(item) for item in framework.get("evidenceRules") or [] if _blog_plain_text(item))
        preflight_checks = "; ".join(_blog_plain_text(item) for item in framework.get("preflightChecks") or [] if _blog_plain_text(item))
        word_count = framework.get("wordCount") if isinstance(framework.get("wordCount"), dict) else {}
        blocks.append(f"""
Selected Blog Framework:
- ID: {framework.get('id') or ''}
- Label: {framework.get('label') or ''}
- Article type: {framework.get('articleType') or ''}
- Content goal: {_blog_plain_text(framework.get('contentGoal') or '')}
- Funnel stage: {_blog_plain_text(framework.get('funnelStage') or '')}
- Default language: {_blog_plain_text(framework.get('defaultLanguage') or '')}
- Target audience: {_blog_plain_text(framework.get('targetAudience') or '')}
- Suggested word count: {word_count.get('min') or ''}-{word_count.get('max') or ''}
- Voice and readability rules: {voice_rules}
- Evidence rules: {evidence_rules}
- FAQ rules: {_blog_plain_text(framework.get('faqRules') or '')}
- CTA rules: {_blog_plain_text(framework.get('ctaRules') or '')}
- Internal link rules: {_blog_plain_text(framework.get('internalLinkRules') or '')}
- Media rules: {_blog_plain_text(framework.get('mediaRules') or '')}
- SEO rules: {_blog_plain_text(framework.get('seoRules') or '')}
- Preflight checks: {preflight_checks}
- Prohibited claims: {prohibited}
Outline blocks:
{chr(10).join(outline_lines) if outline_lines else '- Use a clear structure focused on the intended reader and supplied evidence.'}
""".strip())

    if approved_faqs:
        faq_lines = []
        for faq in approved_faqs[:8]:
            categories = ", ".join(faq.get("productCategories") or [])
            scenarios = ", ".join(faq.get("scenarios") or [])
            keywords = ", ".join(faq.get("keywords") or [])
            faq_lines.append(
                f"- Q: {_blog_plain_text(faq.get('question') or '')}\n"
                f"  A: {_blog_plain_text(faq.get('answer') or '')}\n"
                f"  Categories: {categories}; Scenarios: {scenarios}; Keywords: {keywords}"
            )
        blocks.append(f"""
Approved FAQ Library:
Use only these approved FAQ items when they are relevant. Do not use draft or disabled FAQs.
{chr(10).join(faq_lines)}
""".strip())

    return "\n\n".join(blocks)


